// Cyrus R1: the asset part of a build request, decided ON THE SERVER (lib/modbuilder/create.ts calls this after the
// token gate passed). Reads the real plan (lib/cyrus/tokens tierOf), runs the gate, and for an allowed asset kind
// creates/loads the mod's CyrusProject so the build has its reserved nx_ namespace. Dependencies are injectable so
// the gate wiring is unit-tested for every plan without a database (test/cyrus-assets.test.ts).
//
// Byte-identical rule: when nothing is requested, nothing is looked up, no project is created and `service` is null,
// so the build service request is exactly the pre-R1 one. When something is requested but refused, `service` is
// still null (the service sees no assets) and the refusal is only recorded for the user (`meta.notices`).
import type { BuildAssetKind, BuildAssetPlan } from "./plan";
import { anyAllowed, BUILD_ASSET_KINDS, planBuildAssets, requestedAssetKinds } from "./plan";
import { dataPackStudioOn, decideDataPackRoute, worldgenOn } from "../datapack/route";
import { decideDesignerRoute, designerOn } from "../designer/route";
import { decideItemStatesRoute, itemStatesOn } from "../itemmodel/route";
import { configStudioOn, decideConfigRoute } from "../config/route";

/** The build service's `assets` field (services/modbuilder/textures.js parseAssetsRequest). */
export type SvcAssets = { texture: boolean; sound: boolean; namespace: string; library?: boolean; datapack?: true; design?: true; /** R3: present (true) only when the designer route also covers menus / quests */ gameplay?: true; /** R3: present (true) only when the designer route also covers bosses / encounters */ bosses?: true; /** R4: present (true) only when the designer route also covers glyph HUDs */ hud?: true; /** motion core: present (true) only when the designer route also covers motion props */ motion?: true; /** R3: present (true) only when creatures are allowed */ creature?: true; /** R4: present (true) only when the worldgen part of the data pack route is routed */ worldgen?: true; /** R3 item model states: present (true) only when routed (texture allowed + CYRUS_ITEM_STATES) */ itemmodel?: true ; /** Config Studio: present (true) only when routed (CYRUS_CONFIG_STUDIO, plain plugin builds) */ config?: true; configTemplates?: string[] };

/** What ModBuild.cyrus.assets records about the request (lib/cyrus/meta.ts). */
export type CyrusAssetMeta = { requested: BuildAssetKind[]; allowed: BuildAssetKind[]; notices: string[]; projectId?: string; namespace?: string; datapack?: { route: boolean; matched: string[]; limits: string[]; worldgen?: true }; designer?: { route: boolean; matched: string[]; limits: string[]; gameplay?: { menus: boolean; quests: boolean }; bosses?: true; hud?: true }; itemStates?: { route: boolean; matched: string[] }; config?: { route: boolean; templates: string[] } };

export type ProjectRef = { id: string; namespace: string };
export type AssetRequestDeps = {
  /** The account's plan tier (token economy). Throwing = unknown = fail closed. */
  tierOf: (userId: string) => Promise<string>;
  projectForRootBuild: (rootBuildId: string) => Promise<ProjectRef | null>;
  createProject: (input: { userId: string; game: string; rootBuildId: string; title?: string | null }) => Promise<ProjectRef>;
  /** Sound slice: may customer builds use the owner's sound library (licence confirmed)? Default: CYRUS_SOUND_LIBRARY_CLEARED=1. */
  soundLibraryCleared?: () => boolean;
  /** Data pack studio switch (default: CYRUS_DATAPACK_STUDIO=1). Data packs are not plan-gated. */
  dataPackStudioOn?: () => boolean;
  /** R3: is the creature pipeline switched on? Default: CYRUS_CREATURES=1 (fail closed). */
  creaturesEnabled?: () => boolean;
  /** Gameplay designer switch (default: CYRUS_DESIGNER=1). Designers are not plan-gated. */
  designerOn?: () => boolean;
  /** Item model states switch (default: CYRUS_ITEM_STATES=1). Rides on the texture gate. */
  itemStatesOn?: () => boolean;
  /** R4: world generation (default: CYRUS_DATAPACK_STUDIO=1 and CYRUS_WORLDGEN=1). Not plan-gated. */
  worldgenOn?: () => boolean;
  /** Config Studio (default: CYRUS_CONFIG_STUDIO=1). Declared settings; not plan-gated (editing numbers is not asset creation). */
  configStudioOn?: () => boolean;
};

export type AssetRequestInput = {
  userId: string;
  /** The chain root: the new build's own id for a fresh build, base.rootBuildId ?? base.id for a change. */
  rootBuildId: string;
  change: boolean;
  /** body.assets from the client: a REQUEST only, never a permission. */
  explicit?: unknown;
  /** The prompt (fresh) or the change request (change). */
  text: string;
  mcVersion: string;
  /** Asset kinds the mod already has (the base build's stored result), so a change can keep editing them. */
  existing?: BuildAssetKind[];
  /** The base build already ships data packs (lib/cyrus/datapack/route.ts hasDatapacks). */
  existingDatapack?: boolean;
  /** The base build already ships item designs (lib/cyrus/designer/route.ts hasDesigns). */
  existingDesign?: boolean;
  /** R3: the base build ships boss / encounter designs (lib/cyrus/designer/route.ts hasBossDesigns). */
  existingBosses?: boolean;
  /** R4: the base build ships HUD designs (lib/cyrus/designer/route.ts hasHudDesigns). */
  existingHud?: boolean;
  /** R3: the base build ships menu / quest designs (lib/cyrus/designer/route.ts hasGameplayDesigns). */
  existingGameplay?: boolean;
  /** motion core: the base build ships motion designs (a change keeps the MOTION PROPS prompt part). */
  existingMotion?: boolean;
  /** The base build already ships item model state specs (lib/cyrus/itemmodel/route.ts hasItemModels). */
  existingItemModels?: boolean;
  /** R4: one of the base build's data packs carries world generation (a change keeps editing it). */
  existingWorldgen?: boolean;
  title?: string | null;
  /** Config Studio: the mod's universal category (ModBuild.cyrus.category), for the template choice. */
  category?: string | null;
};

export type AssetRequestResult = { plan: BuildAssetPlan | null; service: SvcAssets | null; meta: CyrusAssetMeta | null };

const NONE: AssetRequestResult = { plan: null, service: null, meta: null };

export async function resolveBuildAssets(input: AssetRequestInput, deps: AssetRequestDeps): Promise<AssetRequestResult> {
  const requested = requestedAssetKinds({ explicit: input.explicit, text: input.text, existing: input.existing });
  // Cyrus R2: the data pack route (capability router rules, not plan-gated). Off -> decides nothing (byte-identical).
  const dpOn = (deps.dataPackStudioOn ?? (() => dataPackStudioOn()))();
  const dp = decideDataPackRoute({ text: input.text, explicit: input.explicit, existing: input.existingDatapack, existingWorldgen: input.existingWorldgen, mcVersion: input.mcVersion, on: dpOn, worldgen: dpOn && (deps.worldgenOn ?? (() => worldgenOn()))() });
  const dpMeta = dp.route || dp.notices.length ? { datapack: { route: dp.route, matched: dp.matched, limits: dp.limits, ...(dp.worldgen ? { worldgen: true as const } : {}) } } : {};
  // Cyrus R3: the gameplay designer route (item with abilities; not plan-gated). Off -> decides nothing (byte-identical).
  const dz = decideDesignerRoute({ text: input.text, explicit: input.explicit, existing: input.existingDesign, existingGameplay: input.existingGameplay, existingBosses: input.existingBosses, existingHud: input.existingHud, existingMotion: input.existingMotion, mcVersion: input.mcVersion, on: (deps.designerOn ?? (() => designerOn()))() });
  const dzMeta = dz.route || dz.notices.length ? { designer: { route: dz.route, matched: dz.matched, limits: dz.limits, ...(dz.gameplay ? { gameplay: dz.gameplay } : {}), ...(dz.bosses ? { bosses: true as const } : {}), ...(dz.hud ? { hud: true as const } : {}), ...(dz.motion ? { motion: true as const } : {}) } } : {};
  // Config Studio: plain plugin builds declare their settings (off -> decides nothing: byte-identical)
  const cf = decideConfigRoute({ text: input.text, category: input.category, on: (deps.configStudioOn ?? (() => configStudioOn()))(), designRoute: dz.route });
  if (!requested.length && !dp.route && !dp.notices.length && !dz.route && !dz.notices.length && !cf.route) return NONE;
  let plan: BuildAssetPlan | null = null;
  let meta: CyrusAssetMeta;
  if (requested.length) {
    let tier: unknown = null;
    try { tier = await deps.tierOf(input.userId); } catch { tier = null; } // unknown token state: fail closed
    plan = planBuildAssets({ plan: tier, requested, mcVersion: input.mcVersion, change: input.change, existing: input.existing, creaturesOn: (deps.creaturesEnabled ?? (() => process.env.CYRUS_CREATURES === "1"))() });
    meta = { requested, allowed: BUILD_ASSET_KINDS.filter((k) => plan!.allowed[k]), notices: [...plan.notices, ...dp.notices, ...dz.notices], ...dpMeta, ...dzMeta };
  } else meta = { requested: [], allowed: [], notices: [...dp.notices, ...dz.notices], ...dpMeta, ...dzMeta };
  if ((!plan || !anyAllowed(plan.allowed)) && !dp.route && !dz.route && !cf.route) return { plan, service: null, meta };
  let project: ProjectRef | null = null;
  try {
    project = (await deps.projectForRootBuild(input.rootBuildId)) ?? (await deps.createProject({ userId: input.userId, game: "minecraft", rootBuildId: input.rootBuildId, title: input.title ?? null }));
  } catch {
    // A racing create (root_taken) means it exists now; anything else: no namespace, so no assets (fail closed).
    project = await deps.projectForRootBuild(input.rootBuildId).catch(() => null);
  }
  if (!project) {
    const msg = dz.route && !(plan && anyAllowed(plan.allowed)) && !dp.route
      ? "Cyrus couldn't set up this mod's project right now, so it writes the plugin as plain code instead of an item design. Try again later."
      : dp.route && !(plan && anyAllowed(plan.allowed))
      ? "Cyrus couldn't set up this mod's project right now, so it builds the plugin without the data pack. Try again later."
      : "Cyrus couldn't set up this mod's asset project right now, so it builds the plugin without custom assets. Try again later.";
    return { plan: plan ? { ...plan, allowed: { texture: false, sound: false, creature: false } } : null, service: null, meta: { ...meta, allowed: [], notices: [...meta.notices, msg], ...(dp.route ? { datapack: { route: false, matched: dp.matched, limits: dp.limits } } : {}), ...(dz.route ? { designer: { route: false, matched: dz.matched, limits: dz.limits } } : {}) } };
  }
  const texture = !!plan?.allowed.texture, sound = !!plan?.allowed.sound;
  // Cyrus R3 item model states: only on top of an allowed texture route; off -> decides nothing (byte-identical)
  const im = decideItemStatesRoute({ text: input.text, explicit: input.explicit, existing: input.existingItemModels, mcVersion: input.mcVersion, on: (deps.itemStatesOn ?? (() => itemStatesOn()))(), textureAllowed: texture });
  return {
    plan,
    // `library` only rides along with sound and `datapack` only when routed, so texture-only requests stay byte-identical
    service: { texture, sound, namespace: project.namespace, ...(sound ? { library: (deps.soundLibraryCleared ?? (() => process.env.CYRUS_SOUND_LIBRARY_CLEARED === "1"))() } : {}), ...(plan?.allowed.creature ? { creature: true as const } : {}), ...(dp.route ? { datapack: true as const } : {}), ...(dz.route ? { design: true as const } : {}), ...(dz.route && dz.gameplay ? { gameplay: true as const } : {}), ...(dz.route && dz.bosses ? { bosses: true as const } : {}), ...(dz.route && dz.hud ? { hud: true as const } : {}), ...(dz.route && dz.motion ? { motion: true as const } : {}), ...(dp.route && dp.worldgen ? { worldgen: true as const } : {}), ...(im.route ? { itemmodel: true as const } : {}), ...(cf.route ? { config: true as const, configTemplates: cf.templates } : {}) },
    meta: { ...meta, projectId: project.id, namespace: project.namespace, ...(im.route ? { itemStates: { route: true, matched: im.matched } } : {}), ...(cf.route ? { config: { route: true, templates: cf.templates } } : {}) },
  };
}

/** Asset kinds a stored build result already carries (ModBuild.result.assets, written by lib/cyrus/assets/sync.ts). */
export function existingAssetKinds(result: unknown): BuildAssetKind[] {
  const a = (result as { assets?: { textures?: unknown[]; sounds?: unknown[]; creatures?: unknown[] } } | null)?.assets;
  return [
    ...(Array.isArray(a?.textures) && a!.textures!.length ? (["texture"] as const) : []),
    ...(Array.isArray(a?.sounds) && a!.sounds!.length ? (["sound"] as const) : []),
    ...(Array.isArray(a?.creatures) && a!.creatures!.length ? (["creature"] as const) : []),
  ];
}
// Asset kinds a Cyrus build can generate (R1: texture + sound; R3: creature = an animated custom-model mob for the
// Nxeon-managed BetterModel, 26.x only; gated like textures: the plan-gate kind is "model"). Tiny and dependency-free so client code
// (lib/cyrus/meta.ts) can use it without pulling in the adapters or the version registry.
export const BUILD_ASSET_KINDS = ["texture", "sound", "creature"] as const;
export type BuildAssetKind = (typeof BUILD_ASSET_KINDS)[number];
export const isBuildAssetKind = (v: unknown): v is BuildAssetKind => typeof v === "string" && (BUILD_ASSET_KINDS as readonly string[]).includes(v);
// Cyrus R1 asset slice: which custom assets a BUILD may generate (pure, client-safe).
// The build request names what the user wants (an explicit `assets` list from the composer, words in the prompt that
// the adapter's route rules recognise, or textures the mod already has); the plan-tier gate
// (lib/cyrus/engine-core/asset-gate.ts) decides what the plan may create or edit; the version registry decides what
// the target version can show; ASSET_PIPELINE_READY says which pipelines exist. Anything refused is a DOWNGRADE: the
// plugin is still built, without that asset, with a plain reason for the user. Never trust the client for any of it:
// the server calls planBuildAssets on every request (lib/cyrus/assets/request.ts).
import { isLegacyVersion, legacyTexturesOn, versionAssetLimits } from "../itemmodel/legacy";
import { getAdapter } from "../adapters";
import { canAsset, normalizePlan, PLAN_LABEL, type AssetPlan } from "../engine-core/asset-gate";
import { getVersion, hasCapability, resourcePackFormat } from "../versions/registry";

import { BUILD_ASSET_KINDS, type BuildAssetKind } from "./kinds";
export { BUILD_ASSET_KINDS, isBuildAssetKind, type BuildAssetKind } from "./kinds";

/**
 * Which generation pipelines the build path can run today. Both slices are built (R1): the service writes texture
 * and sound specs, lib/cyrus/assets/sync.ts renders them (sounds on the render host, see docs "Cyrus sound slice (R1)").
 * The plan gate is unchanged: sound = Saka and the top plan, textures = the top plan, free/Katara none.
 */
export const ASSET_PIPELINE_READY: Readonly<Record<BuildAssetKind, boolean>> = { texture: true, sound: true, creature: true };

/**
 * Cyrus R3 creatures ship OFF: the creature pipeline is offered only when CYRUS_CREATURES=1 on the app host (fail
 * closed: unset, anything else = off, and the request says "not switched on yet" instead of pretending).
 */
export const CREATURES_FLAG = "CYRUS_CREATURES";
export const creaturesEnabled = (env: Record<string, string | undefined> = process.env) => env[CREATURES_FLAG] === "1";
/** The plan-gate kind of a build asset kind (lib/cyrus/engine-core/asset-gate.ts): a creature is a model asset. */
export const GATE_KIND: Readonly<Record<BuildAssetKind, "texture" | "sound" | "model">> = { texture: "texture", sound: "sound", creature: "model" };
/** What a creature request on a version without animated creatures gets instead (owner wording, R3). */
export const CREATURE_DOWNGRADE = "Animated custom creatures need Minecraft 26.x; on this version Cyrus can build the plugin with custom sounds (and a static item-style model later), on a vanilla-looking mob.";

export type AllowedAssets = Record<BuildAssetKind, boolean>;
export type AssetDecisionCode = "allowed" | "asset_locked" | "plan_unknown" | "version" | "not_ready";
export type BuildAssetDecision = { kind: BuildAssetKind; code: AssetDecisionCode; reason?: string; needs?: AssetPlan };
export type BuildAssetPlan = {
  /** What the request asked for (sorted, unique). Empty = no asset path at all (the pre-R1 behaviour). */
  requested: BuildAssetKind[];
  allowed: AllowedAssets;
  decisions: BuildAssetDecision[];
  /** Customer-visible, one per refused kind: why, and what Cyrus builds instead. */
  notices: string[];
  plan: AssetPlan | null;
};

const FALLBACK: Record<BuildAssetKind, string> = { texture: "vanilla item looks", sound: "vanilla sounds", creature: "a vanilla-looking mob" };
const WORD: Record<BuildAssetKind, string> = { texture: "Custom textures", sound: "Custom sounds", creature: "Animated custom creatures" };

/** Asset kinds the adapter's route rules recognise in the request text (deterministic keyword match, no AI). */
export function detectAssetKinds(text: string, game = "minecraft"): BuildAssetKind[] {
  const adapter = getAdapter(game);
  if (!adapter || !text) return [];
  const out = new Set<BuildAssetKind>();
  for (const rule of adapter.routeRules) {
    if (!rule.assetKinds?.length) continue;
    if (!rule.keywords.some((k) => new RegExp(k, "i").test(text))) continue;
    for (const k of rule.assetKinds) {
      if (rule.buildAssetKinds?.length) { for (const b of rule.buildAssetKinds) if ((BUILD_ASSET_KINDS as readonly string[]).includes(b)) out.add(b as BuildAssetKind); break; }
      if (k === "sound") out.add("sound");
      else if (k === "texture" || k === "model") out.add("texture"); // item models are drawn with the texture pipeline
    }
  }
  return BUILD_ASSET_KINDS.filter((k) => out.has(k));
}

/** The request's own list: `assets: ["texture"]` or `assets: { texture: true }` (anything else is ignored). */
export function explicitAssetKinds(raw: unknown): BuildAssetKind[] {
  if (Array.isArray(raw)) return BUILD_ASSET_KINDS.filter((k) => raw.includes(k));
  if (raw && typeof raw === "object") return BUILD_ASSET_KINDS.filter((k) => (raw as Record<string, unknown>)[k] === true);
  return [];
}

export function requestedAssetKinds(input: { explicit?: unknown; text?: string; existing?: BuildAssetKind[]; game?: string }): BuildAssetKind[] {
  const s = new Set<BuildAssetKind>([...explicitAssetKinds(input.explicit), ...detectAssetKinds(input.text ?? "", input.game), ...(input.existing ?? [])]);
  // a creature always comes with its sound set (the base mob is silenced), so it also asks for sounds
  if (s.has("creature")) s.add("sound");
  return BUILD_ASSET_KINDS.filter((k) => s.has(k));
}

/** Can the target version show this kind at all? Textures need 1.21.4+ item model definitions and a known pack format. */
function versionReason(kind: BuildAssetKind, mcVersion: string): string | null {
  if (kind === "creature") {
    if (!hasCapability(mcVersion, "animatedCreatures")) return `${CREATURE_DOWNGRADE} This mod targets ${mcVersion}.`;
    if (!getVersion(mcVersion)?.buildable) return `Animated custom creatures need a Minecraft 26.x version Cyrus can build, and ${mcVersion} is not buildable yet, so Cyrus builds the plugin with ${FALLBACK.creature}.`;
    return null;
  }
  if (kind === "texture" && !hasCapability(mcVersion, "itemModelDefinitions") && isLegacyVersion(mcVersion) && legacyTexturesOn()) {
    return resourcePackFormat(mcVersion).ok ? null : `${WORD.texture} aren't available for Minecraft ${mcVersion} yet (no verified pack format), so Cyrus builds it with ${FALLBACK.texture}.`;
  }
  const pf = resourcePackFormat(mcVersion, { needsItemModels: kind === "texture" });
  if (kind === "texture" && !hasCapability(mcVersion, "itemModelDefinitions")) {
    return `${WORD.texture} need Minecraft 1.21.4 or newer (item model definitions) and this mod targets ${mcVersion}, so Cyrus builds it with ${FALLBACK.texture}. Pick 1.21.4 or newer to get custom textures.`;
  }
  if (!pf.ok) return `${WORD[kind]} aren't available for Minecraft ${mcVersion} yet (${pf.error}), so Cyrus builds it with ${FALLBACK[kind]}.`;
  return null;
}

/**
 * Decide, per requested kind: plan gate first (create for a new mod, edit for a change), then the version, then
 * whether the pipeline exists. `plan` is whatever the token economy says (`all`, `yakko`, `saka`, ...); unknown or
 * missing -> nothing may be created (fail closed).
 */
export function planBuildAssets(input: { plan: unknown; requested: BuildAssetKind[]; mcVersion: string; change?: boolean; existing?: BuildAssetKind[]; creaturesOn?: boolean }): BuildAssetPlan {
  const plan = normalizePlan(input.plan);
  const allowed: AllowedAssets = { texture: false, sound: false, creature: false };
  const decisions: BuildAssetDecision[] = [];
  const notices: string[] = [];
  for (const kind of BUILD_ASSET_KINDS.filter((k) => input.requested.includes(k))) {
    const g = canAsset(plan, GATE_KIND[kind], input.change ? "edit" : "create");
    if (!g.ok) {
      const code = g.code === "plan_unknown" ? "plan_unknown" : "asset_locked";
      // Keeping what the mod already has is never gated: say so instead of implying the textures disappear.
      const reason = input.existing?.includes(kind)
        ? `This mod's existing ${WORD[kind].toLowerCase()} are kept exactly as they are. ${g.reason}`
        : `${g.reason} Cyrus will build the plugin with ${FALLBACK[kind]} instead.`;
      decisions.push({ kind, code, reason, ...(g.needs ? { needs: g.needs } : {}) });
      notices.push(reason);
      continue;
    }
    const vr = versionReason(kind, input.mcVersion);
    if (vr) { decisions.push({ kind, code: "version", reason: vr }); notices.push(vr); continue; }
    if (!ASSET_PIPELINE_READY[kind] || (kind === "creature" && !(input.creaturesOn ?? creaturesEnabled()))) {
      const reason = kind === "creature" ? `Animated custom creatures are not switched on in Cyrus yet, so this mod uses ${FALLBACK.creature} for now.` : `${WORD[kind]} are not built into Cyrus yet, so this mod uses ${FALLBACK[kind]} for now.`;
      decisions.push({ kind, code: "not_ready", reason });
      notices.push(reason);
      continue;
    }
    allowed[kind] = true;
    decisions.push({ kind, code: "allowed" });
    // 1.21.1 legacy path: allowed, but the user is told plainly what it cannot do (never dropped silently)
    if (kind === "texture" && isLegacyVersion(input.mcVersion)) notices.push(...versionAssetLimits(input.mcVersion).filter((l) => !l.supported || l.feature === "carrier_conflict").map((l) => l.message));
  }
  return { requested: [...input.requested].sort() as BuildAssetKind[], allowed, decisions, notices, plan };
}

export const anyAllowed = (a: AllowedAssets) => BUILD_ASSET_KINDS.some((k) => a[k]);
export const planLabel = (p: AssetPlan | null) => (p ? PLAN_LABEL[p] : "unknown");
// Cyrus engine core: the minimal capability router (MASTER-PLAN 4.3). DETERMINISTIC: no AI call, no network.
// Given a ModSpec (and optionally the raw prompt) and the game's adapter, decide which artifact routes the mod
// needs, which of them Cyrus can build today, and the honest limits the user must see before tokens are spent.
// With a plan, the asset tier gate runs here first and DOWNGRADES (strips gated custom assets with a reason)
// instead of failing. Game-agnostic: all game facts are the adapter's route rules and version capabilities.
import type { GameAdapter, RouteRule } from "../adapters/types";
import { ARTIFACT_ROUTES, type ArtifactRoute, type ModSpec } from "./spec";
import { canAsset, downgradeSpecAssets, type AssetDenial } from "./asset-gate";

export type RouteLimit = { id: string; severity: "info" | "warn" | "block"; message: string };

export type RouteDecision = {
  game: string;
  version: string;
  /** Every route the mod needs, in canonical order. */
  routes: ArtifactRoute[];
  /** Subsets of `routes` by what the adapter can do today. */
  available: ArtifactRoute[];
  planned: ArtifactRoute[];
  unsupported: ArtifactRoute[];
  /** "plugin", "plugin+resourcePack", "dataPack", ... or "clientMod-unsupported" when nothing buildable is left. */
  label: string;
  /** True when every needed route is available today and nothing blocks the target version. */
  buildableNow: boolean;
  limits: RouteLimit[];
  matchedRules: string[];
  /** The spec after the plan downgrade (unchanged when no plan was given). */
  spec: ModSpec;
  removedAssets: AssetDenial[];
};

export type RouteOptions = {
  prompt?: string;
  /** Pass to apply the asset tier gate. `{ plan: undefined }` = unknown plan, so asset creation fails closed. */
  gate?: { plan: unknown };
  /** Planned routes the HOST has switched on here (e.g. dataPack behind CYRUS_DATAPACK_STUDIO): they count as available. */
  routesOn?: readonly ArtifactRoute[];
};

const order = (s: Set<ArtifactRoute>) => ARTIFACT_ROUTES.filter((r) => s.has(r));

/** The text routing reads. Non-goals and constraints are left out on purpose ("no custom blocks" must not trigger). */
function routingText(spec: ModSpec, prompt?: string): string {
  return [spec.summary, ...spec.requirements.map((r) => r.text), ...spec.assets.map((a) => a.purpose), prompt ?? ""].join("\n").toLowerCase();
}

const compiled = new WeakMap<RouteRule, RegExp[]>();
function keywordHit(rule: RouteRule, text: string): boolean {
  let res = compiled.get(rule);
  if (!res) { res = rule.keywords.map((k) => new RegExp(k, "i")); compiled.set(rule, res); }
  return res.some((re) => re.test(text));
}

export function routeSpec(input: ModSpec, adapter: GameAdapter, opts: RouteOptions = {}): RouteDecision {
  const limits: RouteLimit[] = [];
  const matchedRules: string[] = [];
  let spec = input;
  let removedAssets: AssetDenial[] = [];
  if (opts.gate) {
    const d = downgradeSpecAssets(input, opts.gate.plan);
    spec = d.spec;
    removedAssets = d.removed;
    d.removed.forEach((r, i) => limits.push({ id: `asset_gate:${r.assetId}`, severity: "warn", message: d.notices[i] }));
  }
  const version = spec.target.version;
  const text = routingText(spec, opts.prompt);
  const kinds = new Set(spec.assets.map((a) => a.kind));
  const need = new Set<ArtifactRoute>(spec.routes);

  for (const rule of adapter.routeRules) {
    const byAsset = !!rule.assetKinds?.some((k) => kinds.has(k));
    if (!byAsset && !keywordHit(rule, text)) continue;
    matchedRules.push(rule.id);
    // Asked for in words only, for asset kinds this plan may not create: say so, do not add the route.
