import { db } from "@/lib/db";
import { cyrusDb } from "@/lib/cyrus/db";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { createModBuild } from "@/lib/modbuilder/create";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { forgeStream, routePrompt, type ForgeRequest } from "@/lib/cyrus/engine";
import { CATEGORY_BY_KEY, EMBLEMS, GAMES, GAME_BY_ID, MAX_GAMES, MODEL_BY_ID, TEMPLATES } from "@/lib/cyrus/data";
import { followBuild } from "@/lib/cyrus/follow";
import { promptProblem } from "@/lib/cyrus/prompt-check";
import { isRealModId, rootOfRealMod } from "@/lib/cyrus/real";
import { normalizeCategory, type CyrusCategoryId } from "@/lib/cyrus/categories";
import type { Game, GenEvent } from "@/lib/cyrus/types";

// Cyrus v5 forge stream (handoff START-HERE §6): NDJSON GenEvents.
//  - A prompt that routes to a game Cyrus really builds for (Minecraft), or a change to one of the
//    account's real mods, starts a REAL build through lib/modbuilder/create.ts (the same
//    validation, rate limits and token gate as POST /api/mod-builder/builds) and streams its real
//    progress and code (lib/cyrus/follow.ts). Token errors answer JSON (402/403/429 + code)
//    BEFORE the stream starts, for cyrusTokens.handleBuildError().
//  - Every other game has no builder yet: the handoff's TEMPLATE generator (forgeStream) runs,
//    clearly a preview, and spends no tokens.
//  - GET ?follow=<buildId> re-attaches to a real build that is still running (page reload, a
//    dropped connection).
// Same private-preview gate as the rest of Cyrus: 404 for everyone else.

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const NOT_FOUND = () => NextResponse.json({ error: "Not found" }, { status: 404, headers: { "x-robots-tag": "noindex" } });
const str = (v: unknown, max: number) => (typeof v === "string" ? v.slice(0, max) : "");

/** Only well-formed user-added games get through; everything is clamped (handoff, unchanged). */
function cleanGames(input: unknown): Game[] {
  if (!Array.isArray(input)) return [];
  return input
    .slice(0, MAX_GAMES)
    .filter((g) => g && typeof g === "object" && typeof g.id === "string" && g.id.startsWith("custom-"))
    .map((g) => {
      const template = TEMPLATES.find((t) => t.key === g.template) ?? TEMPLATES[0];
      // older clients may still hold v5 archetype keys ("worlds", "mechanics"): normalise them
      const categories: CyrusCategoryId[] = [...new Set((Array.isArray(g.categories) ? (g.categories as unknown[]) : []).map(normalizeCategory).filter((c): c is CyrusCategoryId => !!c && c in CATEGORY_BY_KEY))].slice(0, 6);
      return {
        id: str(g.id, 80),
        name: str(g.name, 40) || "Custom game",
        short: str(g.short, 16) || "Custom",
        toolchain: str(g.toolchain, 40) || template.toolchain,
        language: template.language,
        rgb: /^\d{1,3} \d{1,3} \d{1,3}$/.test(g.rgb) ? g.rgb : "167 139 250",
        emblem: EMBLEMS.includes(g.emblem) ? g.emblem : "cube",
        blurb: str(g.blurb, 120),
        aliases: (Array.isArray(g.aliases) ? g.aliases : []).map((a: unknown) => str(a, 40).toLowerCase()).filter(Boolean).slice(0, 6),
        categories: categories.length ? categories : ["gameplay"],
        template: template.key,
        custom: true,
      } satisfies Game;
    });
}

function ndjson(gen: (signal: AbortSignal) => AsyncGenerator<GenEvent>, req: Request) {
  const encoder = new TextEncoder();
  const abort = new AbortController();
  req.signal.addEventListener("abort", () => abort.abort());
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      try {
        for await (const event of gen(abort.signal)) controller.enqueue(encoder.encode(JSON.stringify(event) + "\n"));
      } catch (err) {
        if (!abort.signal.aborted) {
          console.error("[cyrus] forge stream", (err as Error).message);
          controller.enqueue(encoder.encode(JSON.stringify({ type: "error", message: "The forge lost its connection. Your build keeps going: it appears in the network when it's ready." }) + "\n"));
        }
      } finally {
        try { controller.close(); } catch { /* closed by a client abort */ }
      }
    },
    cancel() { abort.abort(); },
  });
  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      // no-transform keeps gzip from buffering the stream; nginx must not buffer it either.
      "Cache-Control": "no-cache, no-transform",
      "X-Accel-Buffering": "no",
    },
  });
}

/** The version a change builds on: the restored head, else the newest version that built. */
async function headOf(userId: string, rootId: string): Promise<string | null> {
  const rows = await cyrusDb.modBuild.findMany({ where: { userId, OR: [{ id: rootId }, { rootBuildId: rootId }] }, orderBy: { createdAt: "asc" } });
  const root = rows.find((r) => r.id === rootId);
  if (!root) return null;
  const ok = rows.filter((r) => r.status === "succeeded");
  const want = readCyrusMeta(root.cyrus).headBuildId;
  return (want && ok.find((r) => r.id === want)?.id) || ok[ok.length - 1]?.id || null;
}

export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  let body: ForgeRequest & { attachmentIds?: unknown; mcVersion?: unknown; retarget?: unknown; assets?: unknown };
  try {
    body = (await req.json()) as typeof body;
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }
  if (!body?.prompt || typeof body.prompt !== "string" || !body.prompt.trim()) return NextResponse.json({ error: "Prompt is required" }, { status: 400 });
  if (!MODEL_BY_ID[body.model]) return NextResponse.json({ error: "Pick Katara, Saka or Yakko." }, { status: 400 });
  body.games = cleanGames(body.games);
  const prompt = body.prompt.trim();
  // Gibberish and non-requests are refused on EVERY path, before routing, before any tokens, before any model.
  const unclear = promptProblem(prompt);
  if (unclear) return NextResponse.json({ error: unclear, code: "prompt_unclear" }, { status: 400 });
  const ctx = body.context ?? {};

  // Real or template?
  const refineReal = isRealModId(ctx.modId);
  // A change to a template mod stays on its template game, whatever the prompt mentions.
  const refineTemplate = !!ctx.modId && !refineReal;
  const route = refineReal || refineTemplate ? null : routePrompt(prompt, ctx, [...GAMES, ...body.games]);
  const real = refineReal || !!(route && GAME_BY_ID[route.gameId]?.real);

  if (real) {
    let baseBuildId: string | null = null;
    if (refineReal) {
      baseBuildId = await headOf(user.id, rootOfRealMod(ctx.modId!));
      if (!baseBuildId) return NextResponse.json({ error: "This mod has no version that built yet. Forge it again, or wait for the running build." }, { status: 400 });
    }
    const r = await createModBuild(user, {
      ...(baseBuildId ? { baseBuildId, changeRequest: prompt } : { prompt }),
      ...(typeof body.mcVersion === "string" ? { mcVersion: body.mcVersion } : {}),
      // Cyrus lifecycle: "Update with Cyrus for the new version" rebuilds the mod for mcVersion.
      ...(refineReal && body.retarget === true ? { retarget: true } : {}),
      model: body.model,
      attachmentIds: body.attachmentIds,
      // Cyrus R1: a REQUEST for custom assets (["texture"]); the server-side plan gate decides (lib/cyrus/assets/request.ts).
      ...(body.assets !== undefined ? { assets: body.assets } : {}),
    });
    if (!r.ok) return r.status === 404 ? NOT_FOUND() : NextResponse.json(r.json, { status: r.status });
    return ndjson((signal) => followBuild(r.build.id, { userId: user.id, refining: refineReal, signal }), req);
  }

  // NO BUILDER for this game yet. The handoff's template generator used to run here and hand back a made-up mod for a game
  // Cyrus cannot build for; that is not what a customer expects from a studio, so it is switched off. The studio shows the
  // game as "coming soon" and the dock refuses before this point; this is the server-side backstop.
  const named = (route && [...GAMES, ...body.games].find((g) => g.id === route.gameId)?.name) || ([...GAMES, ...body.games].find((g) => g.id === ctx.gameId)?.name) || "That game";
  return NextResponse.json({ error: `${named} support is coming soon. Cyrus builds Minecraft plugins today, and nothing was built or charged.`, code: "game_not_ready" }, { status: 409 });
  // eslint-disable-next-line no-unreachable
  return ndjson(async function* (signal) {
    for await (const ev of forgeStream(body, signal)) yield ev.type === "start" ? { ...ev, credits: 0, real: false } : ev;
  }, req);
}

export async function GET(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const id = new URL(req.url).searchParams.get("follow") || "";
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) return NextResponse.json({ error: "Bad build id" }, { status: 400 });
  const row = await cyrusDb.modBuild.findUnique({ where: { id } });
  if (!row || row.userId !== user.id) return NOT_FOUND();
  return ndjson((signal) => followBuild(id, { userId: user.id, refining: !!row.baseBuildId, signal }), req);
}

226 lib/cyrus/follow.ts
// Cyrus v5: a REAL build (the Minecraft plugin builder on the mod-builder VM) told as the studio's
// forge event stream (lib/cyrus/types.ts GenEvent, handoff START-HERE §6), so the network's beams,
// the thinking trace and the live code panel animate on real progress:
//   start -> build -> think(read) -> route -> think(stage)... file / chunk / file-set / file-done ... -> done | error
// Stages come from the build row (synced from the service), code from the service's live view
// (the file being written right now + the workspace files). Server only.
//
// The build runs on its own: if the client goes away the stream stops, the build does not (the
// worker sweep keeps syncing it), and GET /api/cyrus/generate?follow=<id> picks it up again.
import type { ModBuild } from "@prisma/client";
import { cyrusDb as db } from "./db";
import { svcLive, svcSource, type SvcLive } from "./builder/client";
import { toView } from "./builder/view";
import { getHost } from "./host";
import { isTerminal, type ModBuildView } from "./builder/types";
import { readCyrusMeta } from "./meta";
import { GAMES } from "./data";
import { deriveReal, realModId, realNotes, visibleSource } from "./real";
import { languageForPath } from "./engine/kit";
import type { CyrusCategoryId, GenEvent, ModelId } from "./types";
import { liveAssetsOn } from "./liveassets/flags";
import { assetEvents, assetQuery, newAssetFollow } from "./liveassets/follow-assets";

const REAL_GAME = GAMES.find((g) => g.real) ?? GAMES[0];
const sleep = (ms: number, signal?: AbortSignal) =>
  new Promise<void>((r) => {
    const t = setTimeout(r, ms);
    signal?.addEventListener("abort", () => { clearTimeout(t); r(); }, { once: true });
  });

/** What the studio calls each build stage (customer voice; never names a model). */
const STAGE: Record<string, { label: string; detail: (b: ModBuild) => string }> = {
  queued: { label: "Waiting for a free builder", detail: () => "Cyrus builds two mods at a time in the preview" },
  planning: { label: "Planning the plugin", detail: (b) => `Paper ${b.mcVersion} · Java 21 · commands, events, config` },
  coding: { label: "Writing the code", detail: () => "src/main/java" },
  compiling: { label: "Compiling into a real plugin", detail: (b) => `Gradle · Paper API ${b.mcVersion}` },
  repairing: { label: "Fixing what the compiler found", detail: () => "Cyrus reads the errors and repairs its own code" },
  scanning: { label: "Safety check", detail: () => "No internet, no system access, no surprises" },
};
const NOISE = new Set(["Error details", "API lookup"]);

export type RealRoute = { gameId: string; category: CyrusCategoryId; modName: string; modId: string; summary: string };

/** Where a build sits on the network: same derivation the client uses (lib/cyrus/real.ts). */
export async function routeOfBuild(userId: string, build: ModBuild): Promise<RealRoute> {
  const rows = await db.modBuild.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: 200 });
  if (!rows.some((r) => r.id === build.id)) rows.push(build);
  const model = deriveReal(rows.map(toView), REAL_GAME);
  const rootId = build.rootBuildId ?? build.id;
  const mod = model.mods.find((m) => m.id === realModId(rootId));
  return {
    gameId: REAL_GAME.id,
    category: mod?.category ?? "gameplay",
    modName: mod?.name ?? "New plugin",
    modId: realModId(rootId),
    summary: mod?.summary ?? build.prompt.slice(0, 140),
  };
}

async function sourceText(id: string, path: string): Promise<string | null> {
  try {
    const r = await svcSource(id, path);
    return r.ok ? await r.text() : null;
  } catch {
    return null;
  }
}

export async function* followBuild(buildId: string, opts: { userId: string; refining: boolean; signal: AbortSignal; maxMs?: number }): AsyncGenerator<GenEvent> {
  const { signal } = opts;
  let row = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!row || row.userId !== opts.userId) {
    yield { type: "error", message: "That build isn't yours or no longer exists." };
    return;
  }
  const hold = await db.cyrusTokenReservation.findUnique({ where: { buildId } }).catch(() => null);
  const model: ModelId = readCyrusMeta(row.cyrus).model ?? "saka";
  yield { type: "start", jobId: row.id, model, credits: hold?.amount ?? 0, real: true };
  yield { type: "build", build: toView(row) };

  const ask = (row.changeRequest || row.prompt).replace(/\s+/g, " ").trim();
  yield { type: "think", id: "read", label: opts.refining ? "Reading the current build" : "Reading your request", detail: `“${ask.length > 64 ? ask.slice(0, 63) + "…" : ask}”` };
  const route = await routeOfBuild(opts.userId, row);
  yield { type: "route", ...route, tags: [] };
  yield { type: "think-done", id: "read" };

  const deadline = Date.now() + (opts.maxMs ?? 20 * 60_000);
  let stage: string | null = null;
  let seenEvents = 0;
  let lastSync = 0;
  let syncFails = 0;
  let lastSent = Date.now();
  const files = new Map<string, { hash: string; content: string }>();
  const announced = new Set<string>();
  let draft: { path: string; seq: number; op: "write" | "edit"; text: string; done: boolean } | null = null;
  // Cyrus r48: asset specs as they are written (only with CYRUS_LIVE_ASSETS=1; off = the stream is unchanged)
  const assetsOn = liveAssetsOn();
  const af = newAssetFollow();

  const announce = function* (path: string): Generator<GenEvent> {
    if (announced.has(path)) return;
    announced.add(path);
    yield { type: "think", id: `w:${path}`, label: `Writing ${path.split("/").pop()}`, detail: path };
    yield { type: "file", path, language: languageForPath(path) };
  };

  while (!signal.aborted && Date.now() < deadline) {
    const out: GenEvent[] = [];
    // 1) the build row (stage, events) — synced every ~2 s
    if (Date.now() - lastSync > 1800) {
      lastSync = Date.now();
      try { row = await getHost().builds.sync(row!); syncFails = 0; } catch (e) {
        // The service may be busy: try again. But never silently for long: a permission problem on the jar folder once left
        // every studio sitting on "Compiling" for minutes (the web user could not write the jar; only the worker could).
        syncFails++;
        if (syncFails === 3 || syncFails % 60 === 0) console.error("[cyrus] follow: build sync keeps failing", buildId, (e as Error).message);
      }
    }
    const b = row!;
    if (!isTerminal(b.status) && b.status !== stage) {
      if (stage) out.push({ type: "think-done", id: `st:${stage}` });
      stage = b.status;
      const st = STAGE[b.status] ?? { label: "Working", detail: () => "" };
      out.push({ type: "think", id: `st:${stage}`, label: st.label, detail: st.detail(b) });
    }
    const events = ((b.result as { events?: { stage: string; message: string }[] } | null)?.events ?? []).filter((e) => e.message && !NOISE.has(e.message));
    if (events.length > seenEvents && stage && !isTerminal(b.status)) {
      const last = events[events.length - 1];
      out.push({ type: "think", id: `st:${stage}`, label: (STAGE[stage] ?? { label: "Working" }).label, detail: last.message.slice(0, 160) });
    }
    seenEvents = events.length;
    if (isTerminal(b.status)) {
      for (const e of out) yield e;
      break;
    }

    // 2) the code, live
    const dq = draft as { path: string; seq: number; text: string; done: boolean } | null;
    const live: SvcLive | null = await svcLive(b.id, dq && !dq.done ? dq.path : undefined, dq && !dq.done ? dq.text.length : 0, dq?.seq ?? 0, assetsOn ? assetQuery(af) : undefined).catch(() => null);
    if (assetsOn && live) for (const ev of assetEvents(af, live.assets)) out.push({ type: "asset", ev });
    if (live?.live) {
      const d: SvcLive["draft"] = live.draft;
      if (d) {
        const same = draft && draft.path === d.path && draft.seq === d.seq;
        if (!same) {
          if (draft && !draft.done && draft.op === "write") { out.push({ type: "file-done", path: draft.path }, { type: "think-done", id: `w:${draft.path}` }); }
          draft = { path: d.path, seq: d.seq, op: d.op, text: "", done: false };
          if (d.op === "write") {
            const fresh = !announced.has(d.path);
            out.push(...announce(d.path));
            if (!fresh) out.push({ type: "file-set", path: d.path, content: "" }, { type: "think", id: `w:${d.path}`, label: `Rewriting ${d.path.split("/").pop()}`, detail: d.path });
          } else {
            out.push(...announce(d.path));
            out.push({ type: "think", id: `w:${d.path}`, label: `Editing ${d.path.split("/").pop()}`, detail: d.path });
          }
        }
        const cur = draft!;
        if (cur.op === "write") {
          const next = (d.from <= cur.text.length ? cur.text.slice(0, d.from) : cur.text) + d.text;
          if (d.from === cur.text.length) { if (d.text) out.push({ type: "chunk", path: d.path, text: d.text }); }
          else out.push({ type: "file-set", path: d.path, content: next });
          cur.text = next;
        } else {
          cur.text = (d.from <= cur.text.length ? cur.text.slice(0, d.from) : cur.text) + d.text;
        }
        if (d.done && !cur.done) {
          cur.done = true;
          if (cur.op === "write") out.push({ type: "file-done", path: cur.path });
          out.push({ type: "think-done", id: `w:${cur.path}` });
        }
      }
      // workspace files that landed or changed (an edit, or a file written while we weren't looking)
      for (const f of live.files) {
        if (files.get(f.path)?.hash === f.hash) continue;
        if (draft && !draft.done && draft.path === f.path) continue; // still streaming it
        const text = await sourceText(b.id, f.path);
        if (text === null) continue;
        const dr = draft as { path: string; text: string } | null;
        const known = files.get(f.path)?.content ?? (dr && dr.path === f.path ? dr.text : null);
        files.set(f.path, { hash: f.hash, content: text });
        if (!announced.has(f.path)) {
          out.push(...announce(f.path));
          out.push({ type: "chunk", path: f.path, text }, { type: "file-done", path: f.path }, { type: "think-done", id: `w:${f.path}` });
        } else if (known !== text) {
          out.push({ type: "file-set", path: f.path, content: text });
        }
      }
    }
    if (out.length) lastSent = Date.now();
    else if (Date.now() - lastSent > 8000) { out.push({ type: "ping" }); lastSent = Date.now(); }
    for (const e of out) yield e;
    await sleep(900, signal);
  }
  if (signal.aborted || !row || !isTerminal(row.status)) return;
  // r48: the last validator verdicts and "built" land after the final poll: read them from the stored timeline.
  if (assetsOn) {
    const tail = await svcLive(row.id, undefined, 0, 0, assetQuery(af)).catch(() => null);
    for (const ev of assetEvents(af, tail?.assets)) yield { type: "asset", ev };
  }

  const view: ModBuildView = toView(row);
  if (row.status === "failed") {
    yield { type: "error", message: row.error || "This version didn't build. Any tokens it held go back to you." };
    return;
  }
  // The finished source: anything not seen live (resources, a last edit) lands now.
  const src = await getHost().mods.serviceBuildId(row.id);
  for (const f of visibleSource(view.result?.files ?? [])) {
    if (signal.aborted) return;
    const text = await sourceText(src, f.path);
    if (text === null) continue;
    if (!announced.has(f.path)) {
      for (const e of announce(f.path)) yield e;
      yield { type: "chunk", path: f.path, text };
      yield { type: "file-done", path: f.path };
      yield { type: "think-done", id: `w:${f.path}` };
    } else if (files.get(f.path)?.content !== text && !(draft?.path === f.path && draft.text === text)) {
      yield { type: "file-set", path: f.path, content: text };
    }
  }
  yield { type: "think", id: "pkg", label: "Compiled and safety-checked", detail: `${row.jarName ?? "plugin.jar"} · Paper ${row.mcVersion}` };
  yield { type: "think-done", id: "pkg" };
  const settled = await db.cyrusTokenReservation.findUnique({ where: { buildId: row.id } }).catch(() => null);
  yield { type: "build", build: view };
  yield { type: "done", summary: view.result?.summary?.tagline || view.result?.summary?.text || "Ready to install", notes: realNotes(view), tokens: settled?.charged ?? undefined };
}

"use client";

import { useEffect, useRef, useState } from "react";
import { ModelGlyph } from "@/components/cyrus/icons/ModelGlyphs";
import type { BuildSpend, ModSpend } from "@/lib/cyrus/tokens/spend";
import "./spend.css";

/**
 * r41 token spend UI: the live meter in the build screen, a one-line summary for a finished build, and the per-mod
 * breakdown. Reads GET /api/cyrus/tokens/spend (own builds only). "Estimated" is the AI usage reported so far, not a
 * charge; "spent" is what settle charged. Renders nothing for builds outside the token economy.
 */

const n = (v: number) => Math.round(v).toLocaleString("en-US");

const REASON: Record<string, string> = {
  succeeded: "Charged for the work it did",
  failed_free: "Failed on our side: no charge",
  failed_partial: "Failed: only part charged",
  failed_over_limit: "Failed after the free retries: charged",
  refused: "Refused: no charge",
  cancelled: "Cancelled",
  not_started: "Never started: all returned",
  stale: "Lost contact: all returned",
};
export const spendReason = (r: string | null) => (r ? REASON[r] ?? r : "");

async function getJson<T>(q: string): Promise<T | null> {
  const r = await fetch(`/api/cyrus/tokens/spend?${q}`, { cache: "no-store" }).catch(() => null);
  return r && r.ok ? ((await r.json()) as T) : null;
}

function useBuildSpend(buildId: string | undefined, live: boolean): BuildSpend | null {
  const [s, setS] = useState<BuildSpend | null>(null);
  const wasLive = useRef(live);
  useEffect(() => {
    if (!buildId) return;
    let stop = false;
    let t: number | undefined;
    const tick = async (left: number) => {
      const j = await getJson<BuildSpend>(`build=${encodeURIComponent(buildId)}`);
      if (stop) return;
      if (j) setS(j);
      const settled = j && j.state !== "running" && j.state !== "settling";
      // while live: every 3 s (9 s in a background tab); after it ends: a few more until the ledger settles
      if (live || (!settled && left > 0)) t = window.setTimeout(() => void tick(live ? left : left - 1), live ? (document.visibilityState === "hidden" ? 9000 : 3000) : 2000);
    };
    void tick(wasLive.current && !live ? 6 : 3);
    wasLive.current = live;
    return () => { stop = true; window.clearTimeout(t); };
  }, [buildId, live]);
  return s;
}

/** Build screen: estimated so far vs held while it runs, then the settled result. */
export function LiveSpendMeter({ buildId, live }: { buildId?: string; live: boolean }) {
  const s = useBuildSpend(buildId, live);
  if (!s || s.state === "untracked") return null;
  const running = s.state === "running" || s.state === "settling";
