export { MODBUILD_DIR, jarPathFor, toView };

// A build the service never heard back on for this long is failed (the VM was
// rebuilt, the tunnel down for an hour, ...). Generous: real builds take 1-10 min.
const STALE_MS = 2 * 60 * 60 * 1000;

function toResult(s: ServiceBuild): ModBuildResult {
  return {
    summary: s.summary,
    commands: (s.commands || []) as ModBuildResult["commands"],
    permissions: (s.permissions || []) as ModBuildResult["permissions"],
    config: (s.config || []) as ModBuildResult["config"],
    warnings: s.warnings || [],
    files: s.files || [],
    safety: (s.safety as ModBuildResult["safety"]) || null,
    ...(s.capabilities ? { capabilities: s.capabilities } : {}),
    ...(s.catalogOffered ? { librarySlots: librarySlotsFromService(s.librarySlots) } : {}),
    events: (s.events || []).slice(-150),
    repairs: s.repairs || 0,
    queuePosition: s.queuePosition || 0,
    errorDetail: s.errorDetail ? String(s.errorDetail).slice(0, 6000) : null,
    ai: {
      route: s.route?.class ?? null,
      routeMethod: s.route?.method ?? null,
      routeScore: s.route?.score ?? null,
      calls: (s.aiCalls || []).slice(0, 20).map((c) => ({
        kind: c.kind || "generate", route: c.route ?? null, model: c.model, resolvedModel: c.resolvedModel ?? null,
        costUsd: c.costUsd || 0, turns: c.turns ?? null, durationMs: c.durationMs ?? null,
      })),
    },
  };
}

/** Pull the service's view of one build into its row. Never throws for an unreachable service. */
export async function syncBuild(row: ModBuild): Promise<ModBuild> {
  const out = await syncBuildRow(row);
  // Cyrus tokens: a build that just finished settles its hold (idempotent, never throws).
  if (isTerminal(out.status) && !isTerminal(row.status)) {
    await safeSettle(out);
    notifyBuildFinished(out); // r40: bell/email + low-token check (off unless CYRUS_NOTIFY=1; never throws or waits)
    // r38: build.finished webhook (no-op unless CYRUS_API_V1_WEBHOOKS)
    await (await import("../cyrus/api/v1/emit")).emitBuildFinished(out);
  }
  return out;
}

async function syncBuildRow(row: ModBuild): Promise<ModBuild> {
  if (isTerminal(row.status)) return row;
  let s: ServiceBuild | null;
  try {
    s = await svcGet(row.id);
  } catch {
    if (Date.now() - row.createdAt.getTime() > STALE_MS) {
      return cyrusDb.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "unreachable", error: "We lost contact with the builder while this was running. Please try again.", finishedAt: new Date() } });
    }
    return row;
  }
  if (!s) {
    return cyrusDb.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "lost", error: "The builder has no record of this build. Please try again.", finishedAt: new Date() } });
  }
  let release: EngineRelease | null = null;
  const data: Prisma.ModBuildUpdateInput = {
    status: s.status,
    attempts: s.attempts || 0,
    costUsd: s.costUsd || 0,
    durationMs: s.durationMs || null,
    pluginName: s.pluginName || row.pluginName,
    version: s.version || row.version,
    error: s.error,
    errorCode: s.errorCode,
    result: toResult(s) as unknown as Prisma.InputJsonValue,
  };
  if (s.status === "succeeded" && s.jar) {
    // Store the jar before flipping the row to succeeded, so "succeeded" always
    // means "downloadable".
    const bytes = await svcArtifact(row.id);
    const sha = createHash("sha256").update(bytes).digest("hex");
    if (sha !== s.jar.sha256) throw new Error("artifact checksum mismatch");
    await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
    const dest = jarPathFor(row.id);
    await writeFile(dest + ".part", bytes, { mode: 0o640 });
    await rename(dest + ".part", dest);
    Object.assign(data, { jarName: s.jar.name, jarSize: bytes.length, jarSha256: sha, jarPath: dest });
    release = await engineReleaseFor(row, s, sha);
    // Cyrus R1: texture specs that came with the jar -> pack, hosting, Pack Loader entry, revision + asset rows.
    // Before the row flips to succeeded (a DB error throws, so the next sync retries; it is idempotent). Builds
    // without assets skip this entirely (no assetResult from the service).
    if (s.assetResult) {
      const assets = await syncBuildAssets({ id: row.id, userId: row.userId, rootBuildId: row.rootBuildId, mcVersion: row.mcVersion, pluginName: s.pluginName || row.pluginName, jarName: s.jar.name, jarSha256: sha, ...(release ? { engineRelease: release } : {}) }, s.assetResult, defaultAssetSyncDeps());
      if (assets) data.result = { ...toResult(s), assets } as unknown as Prisma.InputJsonValue;
      // Cyrus Config Studio: the build's settings schema, validated again (the service is not trusted)
      const cfg = checkReturnedConfig((s.assetResult as { config?: unknown }).config);
      if (cfg) data.result = { ...(data.result as Record<string, unknown>), cyrusConfig: cfg } as unknown as Prisma.InputJsonValue;
    }
  }
  if (isTerminal(s.status)) data.finishedAt = s.finishedAt ? new Date(s.finishedAt) : new Date();
  // Cyrus R5: the engine release record goes on the build's meta for EVERY succeeded build (before the flip, so a
  // succeeded build always has it when the record could be built; a failure here only logs).

