export const CYRUS_CATEGORY: Record<CyrusCategoryId, CyrusCategory> = Object.fromEntries(CYRUS_CATEGORIES.map((c) => [c.id, c])) as Record<CyrusCategoryId, CyrusCategory>;

export const isCyrusCategoryId = (v: unknown): v is CyrusCategoryId => typeof v === "string" && Object.prototype.hasOwnProperty.call(CYRUS_CATEGORY, v);

/**
 * Older ids that may still be stored somewhere -> the universal id.
 * v5 map keys (lib/cyrus/types.ts CategoryKey), v4 web categories, and words a GameSupport file

 * v5 map keys (lib/cyrus/types.ts CategoryKey), v4 web categories, and words a GameSupport file
 * might reasonably use.
 */
const LEGACY: Record<string, CyrusCategoryId> = {
  // v5 archetype keys
  worlds: "environment", characters: "creatures", mechanics: "gameplay", shaders: "visuals",
  // v4 web categories (lib/cyrus/categories.ts before v6)
  worldgen: "environment", biomes: "environment", structures: "environment", other: "gameplay",
  // plain words
  world: "environment", worldgeneration: "environment", npcs: "creatures", npc: "creatures", mobs: "creatures",
  weapon: "weapons", item: "items", gear: "items", vehicle: "vehicles", mounts: "vehicles",
  mechanic: "gameplay", quest: "quests", progression: "quests", minigame: "minigames", modes: "minigames", gamemodes: "minigames",
  shop: "economy", shops: "economy", moderation: "admin", protection: "admin", qol: "utility", commands: "utility",
  ui: "interface", hud: "interface", cosmetics: "visuals", sound: "audio", optimization: "performance", optimisation: "performance",
};

const squash = (s: string) => s.trim().toLowerCase().replace(/[\s_&-]+/g, "").replace(/and/g, "");

/** Any stored / legacy / free-text category -> a universal id (unknown -> null). */
export function normalizeCategory(v: unknown): CyrusCategoryId | null {
  if (typeof v !== "string" || !v.trim()) return null;
  const raw = v.trim().toLowerCase();
  if (isCyrusCategoryId(raw)) return raw;
  const k = raw.replace(/[\s_&-]+/g, "");
  if (isCyrusCategoryId(k)) return k;
  if (Object.prototype.hasOwnProperty.call(LEGACY, k)) return LEGACY[k];
  const byLabel = CYRUS_CATEGORIES.find((c) => squash(c.label) === squash(raw));
  return byLabel?.id ?? null;
}

/** Like normalizeCategory, but always answers (unknown -> Gameplay). */
export const toCategory = (v: unknown): CyrusCategoryId => normalizeCategory(v) ?? "gameplay";

export const cyrusCategory = (id: unknown): CyrusCategory => CYRUS_CATEGORY[toCategory(id)];

/* ───────────── Per-game availability ───────────── */

const ALL = CYRUS_CATEGORY_IDS as readonly CyrusCategoryId[];
const except = (...no: CyrusCategoryId[]) => ALL.filter((c) => !no.includes(c));

/**
 * What each game's engine can express, until the game's own GameSupport file (lib/cyrus/games/<id>.ts)
 * says otherwise. Deliberately generous: an unlisted category only hides a branch, it never blocks
 * a prompt (the router falls back to the nearest available one and says so).
 */
export const DEFAULT_GAME_CATEGORIES: Record<string, CyrusCategoryId[]> = {
  // Paper plugins (server-side Java): no client shaders, but particles, sounds, menus, world gen all work.
  minecraft: [...ALL],
  // UE4SS Lua on the dedicated server.
  palworld: except("vehicles", "audio", "visuals", "minigames"),
  // Oxide / Carbon C# server plugins: CUI interfaces, no client shaders or magic systems.
  rust: except("magic", "visuals", "audio"),
  // BepInEx + Harmony, usually installed on server AND clients.
  valheim: except("minigames"),
  // Build 41/42 Lua.
  zomboid: except("magic", "minigames"),
  // tModLoader C# content mods.
  terraria: except("admin"),
};

/**
 * A game's categories: its GameSupport list when it has one (normalised; unknown ids dropped),
 * else the default table, else everything (user-added games).
 */
export function categoriesForGame(gameId: string, support?: { categories?: readonly string[] } | null): CyrusCategoryId[] {
  const fromSupport = (support?.categories ?? []).map(normalizeCategory).filter((c): c is CyrusCategoryId => !!c);
  if (fromSupport.length) return ALL.filter((c) => fromSupport.includes(c));
  return DEFAULT_GAME_CATEGORIES[gameId] ?? [...ALL];
}

/** The closest category a game supports (same store bucket first, then same engine archetype, then Gameplay). */
export function nearestAvailable(id: CyrusCategoryId, allowed: readonly CyrusCategoryId[]): CyrusCategoryId {
  if (!allowed.length || allowed.includes(id)) return id;
  const me = CYRUS_CATEGORY[id];
  return (
    allowed.find((c) => CYRUS_CATEGORY[c].store === me.store) ??
    allowed.find((c) => CYRUS_CATEGORY[c].engine === me.engine) ??
    (allowed.includes("gameplay") ? "gameplay" : allowed[0])
  );
}

/* ───────────── Engine archetype ───────────── */

const NPC_WORDS = /\b(npc|trader|merchant|companion|follower|villager|survivor|doctor|bard|keeper|shopkeeper|guard|bodyguard)s?\b/i;

/** The template-generator archetype for a universal category (the text refines the merged ones). */
export function engineCategory(id: CyrusCategoryId | string, text = ""): CategoryKey {
  const c = cyrusCategory(id);
  if (c.id === "creatures" && NPC_WORDS.test(text)) return "characters";
  return c.engine;
}

/* ───────────── Keyword scoring (shared by the router and the auto-sorter) ───────────── */

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const RE_CACHE = new Map<string, RegExp>();
function wordRe(word: string): RegExp {
  let re = RE_CACHE.get(word);
  if (!re) {
    // whole words; simple plurals; multi-word phrases tolerate any run of spaces/hyphens
    const body = word.split(/[\s-]+/).map(escapeRe).join("[\\s-]*");
    re = new RegExp(`(?:^|[^a-z0-9])${body}(?:s|es)?(?=[^a-z0-9]|$)`, "gi");
    RE_CACHE.set(word, re);
  }
  re.lastIndex = 0;
  return re;
}

export const countWord = (text: string, word: string) => (text.match(wordRe(word)) ?? []).length;

const kwWeight = (k: string) => (k.length >= 8 ? 3 : k.length >= 5 ? 2 : 1.4) * (k.includes(" ") ? 1.4 : 1);

/** Score every category over `text` (longer, more specific keywords weigh more). */
export function keywordScores(text: string): Record<CyrusCategoryId, number> {
  const p = text.toLowerCase();
  const out = Object.fromEntries(ALL.map((c) => [c, 0])) as Record<CyrusCategoryId, number>;
  if (!p.trim()) return out;
  for (const c of CYRUS_CATEGORIES) {
    for (const k of c.keywords) {
      const n = countWord(p, k);
      if (n) out[c.id] += Math.min(n, 3) * kwWeight(k);
    }
  }
  return out;
}

/** The single best category for a short text, or null when nothing matches. */
export function bestCategory(text: string, allowed?: readonly CyrusCategoryId[]): { id: CyrusCategoryId; score: number; runnerUp: number } | null {
  const s = keywordScores(text);
  const pool = allowed && allowed.length ? ALL.filter((c) => allowed.includes(c)) : ALL;
  const ranked = [...pool].sort((a, b) => s[b] - s[a] || ALL.indexOf(a) - ALL.indexOf(b));
  if (!ranked.length || s[ranked[0]] <= 0) {
    // the evidence may all sit in a category this game doesn't have: move it to the nearest one
    const top = [...ALL].sort((a, b) => s[b] - s[a])[0];
    if (allowed && allowed.length && s[top] > 0) return { id: nearestAvailable(top, allowed), score: s[top] * 0.8, runnerUp: 0 };
    return null;
  }
  return { id: ranked[0], score: s[ranked[0]], runnerUp: s[ranked[1]] ?? 0 };
}

/* ───────────── Auto-sorter ───────────── */

/**
 * API-level signals in generated code, per category. A regex hit in the source counts strongly:
 * the code is what the mod really does, whatever the prompt said. Covers the loaders Cyrus writes
 * for (Paper/Bukkit Java, Oxide C#, BepInEx/Harmony C#, tModLoader C#, Zomboid Lua, UE4SS Lua).
 */
