  utility: [/\bteleport(Async)?\(/, /\b(set|get|del)Home\b/i, /\bwarp\b/i, /\bAsyncChatEvent\b|\bAsyncPlayerChatEvent\b/],
  interface: [/\bScoreboard\b|\bDisplaySlot\b/, /\bBossBar\b/, /\bcreateInventory\b|\bInventoryClickEvent\b|\bInventoryHolder\b/, /\bCuiHelper\b|\bCuiElementContainer\b/, /\bUIState\b|\bUserInterface\b/, /\bOnGUI\b|\bInventoryGui\b/, /\bISPanel\b|\bISUIElement\b|\bOnPreUIDraw\b/, /\bsendActionBar\b|\bshowTitle\b/, /\bTextDisplay\b/],
  visuals: [/\bspawnParticle\b|\bParticle\.[A-Z_]+/, /\bDust(Options|Transition)\b/, /\bFirework\b/, /\bShader\b|\bPostProcess\b|\bColorGrade\b/, /\bLightSource\b/],
  audio: [/\bplaySound\b/, /\bSoundEvent\b|\bSoundStyle\b|\bSoundEngine\b/, /\bAudioSource\b|\bAudioClip\b/, /\bgetSoundManager\b|\bplaySoundImpl\b/],
  performance: [/\bgetTPS\b|\bMSPT\b/, /\bChunkUnloadEvent\b|\bunloadChunk\b/, /\bmaxEntities\b|\bEntityLimit\b|\bentity[-_ ]?limit\b/i, /\bclear[-_ ]?lag\b|\bItemDespawnEvent\b|\bItemMergeEvent\b/i, /\bsetViewDistance\b|\bsetSimulationDistance\b/, /\bGC\.Collect\b|\bfreeMemory\b/],
