/** Command names that say a lot on their own. */
const COMMAND_SIGNALS: [RegExp, CyrusCategoryId][] = [
  [/^\/?(pay|bal|balance|baltop|money|eco|shop|sell|buy|auction|ah|bank|bounty)$/i, "economy"],
  [/^\/?(home|sethome|delhome|homes|spawn|setspawn|tpa|tpaccept|tpdeny|tp|tphere|warp|setwarp|back|heal|feed|fly|kit|afk|nick|msg|r|reply|discord|rules|website|motd|sort|trash)$/i, "utility"],
  [/^\/?(ban|tempban|unban|kick|mute|unmute|warn|jail|vanish|v|freeze|staff|report|claim|unclaim|trust|untrust|region|rg|whitelist|invsee|spy|socialspy|audit)$/i, "admin"],
  [/^\/?(arena|spleef|duel|join|leave|lobby|ctf|koth|race|tournament|bedwars|skywars)$/i, "minigames"],
  [/^\/?(quest|quests|daily|dailies|achievements?|rankup|prestige|level|rewards?|streak)$/i, "quests"],
  [/^\/?(lag|tps|clearlag|lagg|entities|perf|optimi[sz]e)$/i, "performance"],
  [/^\/?(boss|summon|spawnmob|pet|pets|tame)$/i, "creatures"],
  [/^\/?(scoreboard|sb|hud|menu|gui|board|tab)$/i, "interface"],
  [/^\/?(particles?|trails?|cosmetics?|glow|wings|hat)$/i, "visuals"],
  [/^\/?(music|sound|radio|jukebox)$/i, "audio"],
];

export type AutoSortInput = {
  /** The original request. */
  prompt?: string | null;
  /** Follow-up change requests (each version's ask). */
  changes?: (string | null | undefined)[];
  title?: string | null;
  /** Build summary: tagline + text + how to use. */
  summary?: string | null;
  commands?: { usage: string; description?: string; permission?: string }[];
  permissions?: { node: string; description?: string }[];
  config?: { key: string; description?: string }[];
  /** Generated source (path + content). Only the first ~200 KB is read. */
  files?: { path: string; content: string }[];
  /** Restrict the answer to what this game supports (categoriesForGame). */
  allowed?: readonly CyrusCategoryId[];
};

export type AutoSortResult = {
  primary: CyrusCategoryId;
  secondary: CyrusCategoryId[];
  /** 0..1, how far ahead the primary is and how much evidence there was. */
  confidence: number;
  /** False when the evidence was thin: the UI asks the owner to confirm instead of guessing. */
  confident: boolean;
  /** Human-readable evidence per category ("prompt: sword", "command: /pay", "code: BossBar"). */
  why: Partial<Record<CyrusCategoryId, string[]>>;
  scores: Record<CyrusCategoryId, number>;
};

const W = { title: 2.2, prompt: 1.6, change: 0.6, summary: 1.2, meta: 1.0, command: 4, code: 2.5 } as const;
const MAX_CODE = 200_000;

/** Deterministic, zero-API classification of a finished mod. */
export function autoSort(input: AutoSortInput): AutoSortResult {
  const scores = Object.fromEntries(ALL.map((c) => [c, 0])) as Record<CyrusCategoryId, number>;
  const why: Partial<Record<CyrusCategoryId, string[]>> = {};
  const note = (c: CyrusCategoryId, s: string) => {
    const list = (why[c] ??= []);
    if (list.length < 6 && !list.includes(s)) list.push(s);
  };
  const addText = (text: string | null | undefined, weight: number, label: string) => {
    if (!text?.trim()) return;
    const p = text.toLowerCase();
    for (const c of CYRUS_CATEGORIES) {
      for (const k of c.keywords) {
        const n = countWord(p, k);
        if (!n) continue;
        scores[c.id] += Math.min(n, 3) * weight * (k.length >= 8 ? 1.5 : k.length >= 5 ? 1.2 : 1);
        note(c.id, `${label}: ${k}`);
      }
    }
  };

  addText(input.title, W.title, "title");
  addText(input.prompt, W.prompt, "prompt");
  for (const ch of input.changes ?? []) addText(ch, W.change, "change");
  addText(input.summary, W.summary, "summary");
  for (const c of input.commands ?? []) {
    const name = c.usage.trim().split(/\s+/)[0] ?? "";
    for (const [re, cat] of COMMAND_SIGNALS) {
      if (re.test(name)) { scores[cat] += W.command; note(cat, `command: ${name}`); break; }
    }
    addText(c.description, W.meta, "command");
  }
  for (const p of input.permissions ?? []) addText(`${p.node.replace(/[._]/g, " ")} ${p.description ?? ""}`, W.meta * 0.5, "permission");
  for (const c of input.config ?? []) addText(`${c.key.replace(/[._-]/g, " ")} ${c.description ?? ""}`, W.meta * 0.6, "config");

  let budget = MAX_CODE;
  for (const f of input.files ?? []) {
    if (budget <= 0) break;
    if (!/\.(java|kt|cs|lua|ya?ml|json|toml|properties)$/i.test(f.path)) continue;
    const src = f.content.slice(0, budget);
    budget -= src.length;
    for (const c of ALL) {
      for (const re of CODE_SIGNALS[c]) {
        if (re.test(src)) {
          scores[c] += W.code;
          note(c, `code: ${re.source.replace(/\\b|\\/g, "").slice(0, 32)}`);
        }
      }
    }
  }

  const allowed = input.allowed && input.allowed.length ? input.allowed : ALL;
  // Evidence for a category this game doesn't have moves to the nearest one it does.
  for (const c of ALL) {
    if (allowed.includes(c) || scores[c] <= 0) continue;
    const near = nearestAvailable(c, allowed);
    scores[near] += scores[c] * 0.8;
    note(near, `(${CYRUS_CATEGORY[c].label} isn't a category on this game)`);
    scores[c] = 0;
  }
  const ranked = ALL.filter((c) => allowed.includes(c)).sort((a, b) => scores[b] - scores[a] || ALL.indexOf(a) - ALL.indexOf(b));
  const s1 = scores[ranked[0]] ?? 0;
  const s2 = scores[ranked[1]] ?? 0;
  if (s1 <= 0) {
    const fallback = allowed.includes("gameplay") ? "gameplay" : ranked[0];
    return { primary: fallback, secondary: [], confidence: 0, confident: false, why, scores };
  }
  const secondary = ranked.slice(1, 3).filter((c) => scores[c] >= Math.max(2.5, s1 * 0.35));
  const lead = (s1 - s2) / s1; // 0 = tie, 1 = nothing else
  const evidence = Math.min(1, s1 / 12);
  const confidence = Math.round((0.55 * lead + 0.45 * evidence) * 100) / 100;
  return { primary: ranked[0], secondary, confidence, confident: confidence >= 0.3 && s1 >= 3, why, scores };
}

/** Back-compat for v4 callers: the single best category of a title + text. */
export function classifyMod(parts: { title?: string | null; text?: string | null }): CyrusCategoryId {
  return autoSort({ title: parts.title, prompt: parts.text }).primary;
}

// Cyrus v5 <-> Nxeon: turns the account's real builds (ModBuild rows, grouped into projects by
// lib/cyrus/projects.ts) into the studio's network model (Mod + ModVersion, lib/cyrus/types.ts).
// Pure and client-safe; unit-tested in test/cyrus.test.ts.
//
// A real project lives on the Minecraft branch (the only game the build service compiles today).
// Its versions are its builds; their files load lazily from the build service
// (/api/mod-builder/builds/:id/source). Notes, favourite and the restored head stay in the DB
// (PATCH /api/mod-builder/projects/:rootId), exactly as before.
import { isTerminal, type ModBuildView } from "./builder/types";
import { CATEGORY_BY_KEY } from "./data";
import { autoSort, bestCategory, categoriesForGame, isCyrusCategoryId, type AutoSortInput, type AutoSortResult, type CyrusCategoryId } from "./categories";
import { languageForPath } from "./engine/kit";
import { groupProjects, spaced, viewMeta, type CyrusProject } from "./projects";
import type { Game, Mod, ModFile, ModVersion, ModelId } from "./types";

export const REAL_PREFIX = "nx-";
export const realModId = (rootId: string) => `${REAL_PREFIX}${rootId}`;
export const isRealModId = (id: string | undefined | null): id is string => !!id && id.startsWith(REAL_PREFIX);
export const rootOfRealMod = (id: string) => id.slice(REAL_PREFIX.length);

/** The category branches a real game may grow: its own plus at most this many more (auto-sorted ones; v6: 3, so the common Paper plugin kinds keep their own branch). */
const MAX_EXTRA_CATEGORIES = 3;
const FALLBACK: CyrusCategoryId = "gameplay";

/** The best universal category for a piece of text (null when nothing matches). */
export function scoreCategory(text: string): CyrusCategoryId | null {
  return bestCategory(text)?.id ?? null;
}

/** Everything the build service reported about a project, for the auto-sorter (no code: that loads lazily). */
export function projectSortInput(p: CyrusProject, game: Pick<Game, "id">): AutoSortInput {
  const head = p.head ?? p.latest;
  const r = head.result;
  const s = r?.summary;
  return {
    title: p.title,
    prompt: p.builds[0]?.prompt,
    changes: p.builds.slice(1).map((b) => b.changeRequest),
    summary: [head.pluginName ? spaced(head.pluginName) : "", s?.tagline, s?.text, ...(s?.howToUse ?? [])].filter(Boolean).join(" \n "),
    commands: r?.commands,
    permissions: r?.permissions,
    config: r?.config,
    allowed: categoriesForGame(game.id),
  };
}

/** The auto-sorter's answer for a project (pure; same on the client, the server and the migration helper). */
export const sortProject = (p: CyrusProject, game: Pick<Game, "id">): AutoSortResult => autoSort(projectSortInput(p, game));

/** A project's saved category (owner pick or a stored auto-sort), if any. */
export const savedCategory = (p: CyrusProject): CyrusCategoryId | null => p.meta.category ?? null;

/**
 * Category per project. A saved category (the owner's pick, or one the migration stored) is always
 * used as is. Auto-sorted ones keep the branch readable: the game's own categories, plus up to
 * three more; anything beyond goes to the project's best secondary category that is already on the
 * branch, else Gameplay.
 */
export function categoriesFor(projects: CyrusProject[], game: Game): Map<string, CyrusCategoryId> {
  const pinned = new Map<string, CyrusCategoryId>();
  const auto = new Map<string, AutoSortResult>();
  for (const p of projects) {
    const saved = savedCategory(p);
    if (saved) pinned.set(p.rootId, saved);
    else auto.set(p.rootId, sortProject(p, game));
  }
  const own = new Set<CyrusCategoryId>([...game.categories, ...pinned.values()]);
  const extraCount = new Map<CyrusCategoryId, number>();
  for (const r of auto.values()) if (!own.has(r.primary)) extraCount.set(r.primary, (extraCount.get(r.primary) ?? 0) + 1);
  let extras = [...extraCount.entries()].sort((a, b) => b[1] - a[1]).map(([c]) => c);
  if (extras.length > MAX_EXTRA_CATEGORIES) {
    const keep = extras.filter((c) => c !== FALLBACK).slice(0, MAX_EXTRA_CATEGORIES - (own.has(FALLBACK) ? 0 : 1));
    extras = own.has(FALLBACK) ? keep : [FALLBACK, ...keep];
  }
  const allowed = new Set<CyrusCategoryId>([...own, ...extras]);
  const out = new Map<string, CyrusCategoryId>(pinned);
  for (const [id, r] of auto) out.set(id, allowed.has(r.primary) ? r.primary : (r.secondary.find((c) => allowed.has(c)) ?? FALLBACK));
  return out;
}

const modelOf = (b: ModBuildView): ModelId => viewMeta(b).model ?? "saka";

/** Only the files a server owner cares about (same filter the v4 studio used). */
export const visibleSource = (files: { path: string; size: number }[]) =>
  files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json");

export function versionOf(b: ModBuildView, n: number): ModVersion {
  const s = b.result?.summary;
  return {
    id: b.id,
    label: `v${n}`,
    createdAt: Date.parse(b.createdAt),
    model: modelOf(b),
    credits: 0,
    prompt: b.changeRequest || b.prompt,
    summary: s?.changes || s?.tagline || (b.status === "failed" ? b.error || "This version didn't build." : b.changeRequest || b.prompt),
    files: [],
    additions: 0,
    deletions: 0,
    real: {
      buildId: b.id,
      status: b.status,
      mcVersion: b.mcVersion,
      jarName: b.jarName,
      jarSize: b.jarSize,
      error: b.error,
      attempts: b.attempts,
      durationMs: b.durationMs,
      paths: visibleSource(b.result?.files ?? []),
    },
  };
}

/** Cyrus's notes for a real build, from what the build service reported. */
export function realNotes(b: ModBuildView | null): string {
  if (!b) return "";
  if (b.status === "failed") return `# Didn't build\n\n${b.error || "The build stopped before it finished."}\n\nTokens held for a failed build go back to you.`;
  if (!isTerminal(b.status)) return "# Building\n\nCyrus is writing, compiling and safety-checking this version right now.";
  const r = b.result;
  const s = r?.summary;
  const out: string[] = [`# ${b.pluginName || "Your plugin"}${b.version ? ` v${b.version}` : ""}`];
  if (s?.text) out.push("", s.text);
  if (s?.howToUse?.length) out.push("", "## How to use", ...s.howToUse.map((x) => `- ${x}`));
  if (r?.commands?.length) out.push("", "## Commands", ...r.commands.map((c) => `- \`${c.usage}\` ${c.description}${c.permission ? ` (\`${c.permission}\`)` : ""}`));
  if (r?.permissions?.length) out.push("", "## Permissions", ...r.permissions.map((p) => `- \`${p.node}\` ${p.description} (default: ${p.default})`));
  if (r?.config?.length) out.push("", "## Config", ...r.config.map((c) => `- \`${c.key}\` ${c.description} (default \`${c.default}\`)`));
  if (s?.limitations?.length) out.push("", "## Limits", ...s.limitations.map((x) => `- ${x}`));
  const safety = r?.safety?.verdict;
  out.push("", "## Build", `- Paper ${b.mcVersion} · built in ${Math.max(1, Math.round((b.durationMs ?? 0) / 1000))}s${b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}`);
  if (safety) out.push(`- Safety check: **${safety === "pass" ? "passed" : safety === "warn" ? "passed with notes" : "blocked"}** (no internet, no system access)`);
  return out.join("\n");
}

export type RealModel = {
  projects: CyrusProject[];
  mods: Mod[];
  versions: Record<string, ModVersion[]>;
  active: Record<string, string>;
  notes: Record<string, string>;
  aiNotes: Record<string, string>;
};

/** Every project of the account as a mod on `game`'s branch (newest activity first). */
export function deriveReal(builds: ModBuildView[], game: Game): RealModel {
  const projects = groupProjects(builds);
  const cats = categoriesFor(projects, game);
  const out: RealModel = { projects, mods: [], versions: {}, active: {}, notes: {}, aiNotes: {} };
  for (const p of projects) {
    const id = realModId(p.rootId);
    const head = p.head;
    const s = (head ?? p.latest).result?.summary;
    out.mods.push({
      id,
      gameId: game.id,
      category: cats.get(p.rootId) ?? FALLBACK,
      name: p.title,
      summary: s?.tagline || s?.text?.split(/(?<=\.)\s/)[0] || p.builds[0].prompt.slice(0, 140),
      tags: [],
      createdAt: Date.parse(p.updatedAt || p.latest.createdAt),
      versions: [],
      real: { rootId: p.rootId, running: !!p.running, failed: !head && !p.running, headBuildId: head?.id ?? null, favourite: !!p.meta.favourite },
    });
    out.versions[id] = p.builds.map((b, i) => versionOf(b, i + 1));
    out.active[id] = (head ?? p.latest).id;
    out.notes[id] = p.meta.notes ?? "";
    out.aiNotes[id] = realNotes(head ?? p.latest);
  }
  return out;
}

/** A source file as the studio's ModFile. */
export const toModFile = (path: string, content: string): ModFile => ({ path, language: languageForPath(path), content });

/** Is this a universal category id (guards stale data). */
export const knownCategory = (k: string): k is CyrusCategoryId => isCyrusCategoryId(k) && k in CATEGORY_BY_KEY;

