// Cyrus v8 structure: the PARTS of a mod, for the Forge sub-branches and the project page. Pure + client-safe.
// Two sources:
//   - any built mod: its parts are DERIVED from what the build shipped (designs by kind, textures, sounds, creatures,
//     item models, data packs, settings, code), so old one-module mods get sub-branches too;
//   - a mod suite (ModSpec v2, CYRUS_MOD_SUITES): one part per module, with dependencies and status.
import type { ModBuildView } from "../builder/types";
import type { ModuleKind, ModSpecV2, ModuleStatus } from "../engine-core/modules";

/** Which studio opens a part (lib/cyrus/manifest StudioId) and how it is named. */
export const PART_META: Record<ModuleKind, { label: string; studio: string | null; noun: [string, string] }> = {
  items: { label: "Items", studio: "items", noun: ["item", "items"] },
  creatures: { label: "Creatures", studio: "model-editor", noun: ["creature", "creatures"] },
  quests: { label: "Quests", studio: "menus", noun: ["quest", "quests"] },
  menus: { label: "Menus", studio: "menus", noun: ["menu", "menus"] },
  bosses: { label: "Bosses", studio: "bosses", noun: ["boss", "bosses"] },
  hud: { label: "HUD", studio: null, noun: ["HUD", "HUDs"] },
  textures: { label: "Textures", studio: "texture", noun: ["texture", "textures"] },
  sounds: { label: "Sounds", studio: "sound", noun: ["sound set", "sound sets"] },
  models: { label: "Models", studio: "model", noun: ["model", "models"] },
  motions: { label: "Motions", studio: "motion", noun: ["motion", "motions"] },
  config: { label: "Config", studio: "config", noun: ["setting", "settings"] },
  datapack: { label: "Data pack", studio: "datapacks", noun: ["data pack", "data packs"] },
  worldgen: { label: "World gen", studio: "datapacks", noun: ["world gen pack", "world gen packs"] },
  code: { label: "Code", studio: null, noun: ["file", "files"] },
};

export type Part = {
  /** kind for derived parts; the module id for a suite */
  id: string;
  kind: ModuleKind;
  label: string;
  detail: string;
  count: number;
  /** the studio route that opens it, or null (code: the Files tab of the mod) */
  studio: string | null;
  module?: string;
  dependsOn?: string[];
  status?: ModuleStatus["flight"];
  rev?: number;
  tokens?: number;
};

const count = (n: number, k: ModuleKind) => `${n} ${n === 1 ? PART_META[k].noun[0] : PART_META[k].noun[1]}`;

/** The parts a built mod has, from what its build shipped. Empty kinds are left out; code is always there. */
export function partsOfBuild(b: Pick<ModBuildView, "result"> | null | undefined): Part[] {
  const r = b?.result;
  if (!r) return [];
  const a = r.assets ?? null;
  const out: Part[] = [];
  const add = (kind: ModuleKind, n: number, detail?: string) => { if (n > 0) out.push({ id: kind, kind, label: PART_META[kind].label, detail: detail ?? count(n, kind), count: n, studio: PART_META[kind].studio }); };
  const ds = a?.designs ?? [];
  const k = (x: string | undefined) => ds.filter((d) => (d.kind ?? "item") === x).length;
  add("items", k("item"));
  add("menus", k("menu"));
  add("quests", k("quest"));
  add("bosses", k("boss") + k("encounter"), [k("boss") ? count(k("boss"), "bosses") : "", k("encounter") ? `${k("encounter")} encounter${k("encounter") === 1 ? "" : "s"}` : ""].filter(Boolean).join(", "));
  add("hud", k("hud"));
  add("motions", k("motion"));
  add("creatures", a?.creatures?.length ?? 0);
  add("textures", a?.textures.length ?? 0);
  add("sounds", new Set((a?.sounds ?? []).map((s) => s.set)).size);
  add("models", a?.itemModels?.length ?? 0, a?.itemModels?.length ? `${a.itemModels.length} item model${a.itemModels.length === 1 ? "" : "s"} with states` : undefined);
  const packs = a?.datapacks ?? [];
  add("datapack", packs.filter((p) => !p.worldgen).length);
  add("worldgen", packs.filter((p) => p.worldgen).length);
  add("config", r.config?.length ?? 0);
  const src = (r.files ?? []).filter((f) => f.path.startsWith("src/")).length;
  out.push({ id: "code", kind: "code", label: PART_META.code.label, detail: src ? count(src, "code") : "the plugin source", count: src, studio: null });
  return out;
}

/** One part per module of a suite (ModSpec v2), with its status when known. */
export function partsOfSuite(spec: Pick<ModSpecV2, "modules">, status?: readonly ModuleStatus[]): Part[] {
  return spec.modules.map((m) => {
    const st = status?.find((s) => s.id === m.id);
    const n = m.designs.length + m.assets.length;
    return { id: m.id, kind: m.kind, label: m.title, detail: `${PART_META[m.kind].label}${n ? ` · ${n} part${n === 1 ? "" : "s"}` : ""}`, count: n, studio: PART_META[m.kind].studio, module: m.id, dependsOn: [...m.dependsOn], ...(st ? { status: st.flight, rev: st.rev, tokens: st.tokens } : {}) };
  });
}

/** Where a part opens: its studio scoped to the module (or the part kind), or the mod's Files tab for code. */
export function partHref(buildId: string, p: Part, studios?: Partial<Record<string, boolean>>): string | null {
  if (!p.studio) return `/dashboard/cyrus/${encodeURIComponent(buildId)}?tab=files`;
  if (studios && studios[p.studio] === false) return null;
  const q = new URLSearchParams({ part: p.kind, ...(p.module ? { module: p.module } : {}) });
  if (p.kind === "quests") q.set("tab", "quests");
  return `/dashboard/cyrus/${encodeURIComponent(buildId)}/studio/${p.studio}?${q}`;
}

/** Layers of a dependency DAG (modules without deps first), for the dependency view. Cycles end up in the last layer. */
export function dagLayers(parts: readonly Pick<Part, "id" | "dependsOn">[]): string[][] {
  const left = new Map(parts.map((p) => [p.id, (p.dependsOn ?? []).filter((d) => parts.some((x) => x.id === d))]));
  const layers: string[][] = [];
  const placed = new Set<string>();
  while (left.size) {
    const layer = [...left].filter(([, deps]) => deps.every((d) => placed.has(d))).map(([id]) => id);
    const take = layer.length ? layer : [...left.keys()];
    take.sort();
    layers.push(take);
    for (const id of take) { placed.add(id); left.delete(id); }
  }
  return layers;
}
