interface Attachment {
  id: string;
  url: string;
  name: string;
  /** Nxeon: the image uploaded for real builds (/api/mod-builder/uploads); Cyrus looks at it while it plans. */
  uploadId?: string;
  state: "up" | "ok" | "err";
}

/** Upload a reference image so a real build can read it (same endpoint and limits as v4). */
async function uploadImage(f: File): Promise<string | null> {
  if (!/^image\/(png|jpe?g|webp|gif)$/.test(f.type) || f.size > 5 * 1024 * 1024) return null;
  const fd = new FormData();
  fd.append("file", f, f.name || "pasted.png");
  const r = await fetch("/api/mod-builder/uploads", { method: "POST", body: fd }).catch(() => null);
  const j = r?.ok ? ((await r.json().catch(() => null)) as { upload?: { id: string } } | null) : null;
  return j?.upload?.id ?? null;
}

