"use client";

import { useEffect, useRef, useState } from "react";
import { ModelGlyph } from "@/components/cyrus/icons/ModelGlyphs";
import { CheckIcon, ChevronDownIcon } from "@/components/cyrus/icons/ui";
import { TokenCoin } from "@/components/cyrus/brand/CyrusBrand";
import { CyrusModelLock, CyrusModelPanelFoot, cyrusTokens, useCyrusTokens } from "@/components/cyrus-tokens";
import { MODELS, MODEL_BY_ID } from "@/lib/cyrus/data";
import { useStore } from "@/lib/cyrus/store";

function CreditMeter({ tier, rgb }: { tier: number; rgb: string }) {
  return (
    <span className="flex items-end gap-[2px]" aria-hidden>
      {[0, 1, 2].map((i) => (
        <span
          key={i}
          className="w-[3px] rounded-full"
          style={{
            height: 5 + i * 3,
            background: i < tier ? `rgb(${rgb})` : "var(--line-2)",
            boxShadow: i < tier ? `0 0 6px rgb(${rgb} / 0.7)` : undefined,
          }}
        />
      ))}
    </span>
  );
}

export function ModelSelect({ disabled, realTarget = true }: { disabled?: boolean; realTarget?: boolean }) {
  const model = useStore((s) => s.model);
  const setModel = useStore((s) => s.setModel);
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const current = MODEL_BY_ID[model];
  // Nxeon: what a typical (standard) build spends on each model, from the token economy.
  const tokens = useCyrusTokens().state;
  const typical = (id: keyof typeof MODEL_BY_ID) => (tokens?.active && realTarget ? tokens.reserve[id]?.standard : null);
  // A model the account's plan doesn't unlock opens the plans instead of being picked.
  const isLocked = (id: keyof typeof MODEL_BY_ID) => !!tokens?.active && tokens.enforce && realTarget && !tokens.models.includes(id);

  useEffect(() => {
    if (!open) return;
    const close = (e: PointerEvent) => {
      if (!ref.current?.contains(e.target as Node)) setOpen(false);
    };
    const esc = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    window.addEventListener("pointerdown", close);
    window.addEventListener("keydown", esc);
    return () => {
      window.removeEventListener("pointerdown", close);
      window.removeEventListener("keydown", esc);
    };
  }, [open]);

  return (
    <div ref={ref} className="relative">
      <button
        type="button"
        disabled={disabled}
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="listbox"
        aria-expanded={open}
        className="tint group flex h-9 items-center gap-2 rounded-xl border border-cy-line bg-[rgb(var(--glow)/0.06)] pl-2 pr-2.5 text-[13px] font-medium text-cy-ink transition hover:border-cy-line-2 hover:bg-[rgb(var(--glow)/0.12)] disabled:opacity-50"
        style={{ ["--c" as string]: current.rgb }}
      >
        <span className="grid h-6 w-6 place-items-center rounded-lg" style={{ background: `rgb(${current.rgb} / 0.14)` }}>
          <ModelGlyph id={current.id} size={18} />
        </span>
        <span className="font-cy-display">{current.name}</span>
        <CreditMeter tier={MODELS.indexOf(current) + 1} rgb={current.rgb} />
        <ChevronDownIcon className={`text-cy-muted transition ${open ? "rotate-180" : ""}`} />
      </button>

      {open && (
        <div role="listbox" aria-label="Forge model" className="cy5-solid animate-pop absolute bottom-[calc(100%+10px)] left-0 z-50 w-[min(340px,calc(100cqw-24px))] rounded-2xl p-1.5">
          <div className="flex items-center px-3 pb-1.5 pt-2 text-[10px] font-semibold uppercase tracking-[0.18em] text-cy-muted">
            Forge model
            <span className="ml-auto normal-case tracking-normal text-cy-faint">{realTarget ? "Typical tokens per build" : "Template preview: no tokens"}</span>
          </div>
          {MODELS.map((m, i) => {
            const active = m.id === model;
            const locked = isLocked(m.id);
            const t = typical(m.id);
            return (
              <button
                key={m.id}
                role="option"
                aria-selected={active}
                aria-disabled={locked || undefined}
                data-locked={locked ? "true" : undefined}
                type="button"
                onClick={() => {
                  if (locked) {
                    setOpen(false);
                    cyrusTokens.open({ tab: "plans", reason: "model_locked" });
                    return;
                  }
                  setModel(m.id);
                  setOpen(false);
                }}
                className="cy-mp-row"
                style={{ ["--c" as string]: m.rgb }}
              >
                <span className="cy-mp-ic">
                  <ModelGlyph id={m.id} size={26} variant={locked ? "mono" : "gradient"} style={locked ? { color: "var(--cy-ink3)" } : undefined} />
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-2">
                    <span className="cy-mp-name">{m.name}</span>
                    <span className="cy-mp-tag">{m.tagline}</span>
                    {active && !locked && (
                      <span className="cy-mp-pick" aria-hidden>
                        <CheckIcon />
                      </span>
                    )}
                    {locked && <span className="ml-auto"><CyrusModelLock model={m.id} /></span>}
                  </span>
                  <span className="cy-mp-desc">{m.description}</span>
                  <span className="cy-mp-cost">
                    <CreditMeter tier={i + 1} rgb={m.rgb} />
                    {t ? (
                      <span className="inline-flex items-center gap-1" title="Typical Minecraft build. A build only spends what it uses; a failed one gives the tokens back.">
                        <TokenCoin size={13} />
                        <b>
                          {t[0].toLocaleString("en-US")}–{t[1].toLocaleString("en-US")}
                        </b>{" "}
                        tokens / build
                      </span>
                    ) : (
                      <span>{["Spends the fewest tokens", "Spends more tokens", "Spends the most tokens"][i]}</span>
                    )}
                    {locked && <span className="cy-mp-unlock">Unlock</span>}
                  </span>
                </span>
              </button>
            );
          })}
          <div className="px-3 pb-1.5 text-[11px] leading-snug text-cy-muted [&_.cy-panel-foot]:m-0 [&_button]:text-cy-cyan">
            <CyrusModelPanelFoot fallback="Template games forge a preview and spend no tokens." />
          </div>
        </div>
      )}
    </div>
  );
}

