// Cyrus live-test fix (A): AUTOMATIC assets. Owner decision: "automatic asset generation follows the user's plan and
// access". Every prompt entry point (Forge prompt box, new-mod flow, the builds API, API v1) goes through
// lib/modbuilder/create.ts, which asks for these kinds automatically: every kind the plan may create AND the target
// version can show AND the pipeline exists for. They are OFFERED, not forced: the build service tells the model they
// are optional, so it decides what the mod needs (a golem gets a rock texture and grunt sounds; a /spawn command gets
// nothing). Refused auto kinds stay silent (nobody asked for them); refusals of kinds the user DID ask for keep their
// notice. Creatures are only auto-offered when the request is about a creature; on a version without animated
// creatures the user is told plainly what Cyrus builds instead ("Mob skin: coming soon").
// Pure + client-safe (the composer shows the same plan before the build).
import { keywordScores } from "../categories";
import { hasCapability, getVersion } from "../versions/registry";
import { BUILD_ASSET_KINDS, type BuildAssetKind } from "./kinds";
import { planBuildAssets, type BuildAssetPlan } from "./plan";

/** Is the request about a creature / mob (the universal category's keywords + a few body words)? */
export function creatureLike(text: string): boolean {
  if (!text) return false;
  if (keywordScores(text).creatures > 0) return true;
  return /\b(golems?|giants?|ogres?|titans?|yetis?|goblins?|orcs?|ghosts?|wraiths?|imps?|demons?|guardians?|wardens?|beasts?)\b/i.test(text);
}

/** The owner's honest line for a creature on a version without custom mob models. */
export function creatureFallbackLine(mcVersion: string, allowed: { texture: boolean; sound: boolean }): string {
  const extras = [allowed.sound ? "custom sounds for its voice (with subtitles)" : "", allowed.texture ? "custom-textured items for what it throws or drops" : ""].filter(Boolean);
  return `Mob skin: coming soon. Custom creature models and skins need Minecraft 26.x with BetterModel, so on ${mcVersion} Cyrus builds this creature on a vanilla base mob (scaled to size)${extras.length ? ` with ${extras.join(" and ")}` : ""}.`;
}

export type AutoAssetDecision = {
  /** Kinds offered automatically (allowed by plan + version + pipeline). */
  auto: BuildAssetKind[];
  /** Customer-visible lines about the automatic plan (only the creature line today; locked kinds stay quiet). */
  notices: string[];
  creature: boolean;
};

/** Which kinds a build gets automatically for this plan, version and request. */
export function autoAssetKinds(input: { plan: unknown; text: string; mcVersion: string; change?: boolean; existing?: BuildAssetKind[]; creaturesOn?: boolean }): AutoAssetDecision {
  const creature = creatureLike(input.text);
  const want = BUILD_ASSET_KINDS.filter((k) => k !== "creature" || creature);
  const p = planBuildAssets({ plan: input.plan, requested: [...want], mcVersion: input.mcVersion, change: input.change, existing: input.existing, creaturesOn: input.creaturesOn });
  const auto = BUILD_ASSET_KINDS.filter((k) => p.allowed[k]);
  const notices = creature && !p.allowed.creature && !hasCapability(input.mcVersion, "animatedCreatures") ? [creatureFallbackLine(input.mcVersion, p.allowed)] : [];
  return { auto, notices, creature };
}

export type AssetPlanLine = { kind: BuildAssetKind; state: "auto" | "locked" | "version" | "off"; text: string };
export type AssetPlanPreview = { lines: AssetPlanLine[]; notices: string[]; limits: string[] };

const WORD: Record<BuildAssetKind, string> = { texture: "Custom textures", sound: "Custom sounds", creature: "Animated creature model" };

/**
 * The asset plan the composer shows BEFORE a build (next to the cost): what Cyrus may create automatically, what the
 * plan or version cannot do, and why. Mirrors what the server will decide (the server decides again; this is a hint).
 */
export function previewAssetPlan(input: { plan: unknown; text: string; mcVersion: string; change?: boolean; existing?: BuildAssetKind[]; creaturesOn?: boolean }): AssetPlanPreview {
  const creature = creatureLike(input.text);
  const kinds = BUILD_ASSET_KINDS.filter((k) => k !== "creature" || creature);
  const p: BuildAssetPlan = planBuildAssets({ plan: input.plan, requested: [...kinds], mcVersion: input.mcVersion, change: input.change, existing: input.existing, creaturesOn: input.creaturesOn });
  const lines: AssetPlanLine[] = kinds.map((k) => {
    const d = p.decisions.find((x) => x.kind === k);
    if (d?.code === "allowed") return { kind: k, state: "auto", text: `${WORD[k]}: Cyrus creates them if the mod needs them` };
    if (d?.code === "asset_locked" || d?.code === "plan_unknown") return { kind: k, state: "locked", text: `${WORD[k]}: ${d.needs ? `needs the ${d.needs === "all" ? "All models" : d.needs[0].toUpperCase() + d.needs.slice(1)} plan` : "not on your plan"}` };
    if (d?.code === "version") return { kind: k, state: "version", text: k === "creature" ? `Mob skin: coming soon (needs Minecraft 26.x)` : `${WORD[k]}: not on Minecraft ${input.mcVersion}` };
    return { kind: k, state: "off", text: `${WORD[k]}: not switched on yet` };
  });
  const notices = creature && !p.allowed.creature && !hasCapability(input.mcVersion, "animatedCreatures") ? [creatureFallbackLine(input.mcVersion, p.allowed)] : [];
  const limits: string[] = [];
  if (!getVersion(input.mcVersion)?.buildable) limits.push(`Minecraft ${input.mcVersion} is not buildable yet.`);
  return { lines, notices, limits };
}

