// Cyrus per-game adapter contract (MASTER-PLAN 4.10). The engine core (lib/cyrus/engine-core) is game-agnostic;
// everything it needs to know about one game comes through this interface. Pure types + data, client-safe.
// Adapter #1 is lib/cyrus/adapters/minecraft.ts. A new game = one new adapter file + a row in adapters/index.ts.
import type { ArtifactRoute, AssetKind } from "../engine-core/spec";
import type { AssetProfile } from "./asset-profile";

/**
 * How far a game's support really goes. Never claim more than ran:
 * planned = nothing built; template = canned preview code only (no compile); beta = real AI build + compile + scan;
 * stable = beta plus boot and functional tests on every build.
 */
export type AdapterMaturity = "planned" | "template" | "beta" | "stable";

/** available = Cyrus produces it today; planned = on the roadmap, not built; unsupported = the game cannot use it. */
export type RouteAvailability = "available" | "planned" | "unsupported";

export type ArtifactType = {
  route: ArtifactRoute;
  availability: RouteAvailability;
  /** File form of the artifact ("jar", "zip", "dll"...). */
  packaging: string;
  side: "server" | "client" | "both";
  /** Customer-voice explanation, shown by the router. */
  note: string;
};

/** A version as the engine core sees it (an adapter maps its own registry rows to this). */
export type AdapterVersion = {
  id: string;
  status: "supported" | "preview" | "legacy" | "blocked";
  buildable: boolean;
  /** Game-specific capability flags, e.g. "dialogApi". The core only passes them through to router rules. */
  capabilities: readonly string[];
};

export type ToolchainProfile = {
  language: string;
  /** How a build is compiled (or "none" when only linted). */
  compiler: string;
  /** Compiler/runtime release per version, or null when the version is not buildable. */
  releaseFor: (version: string) => string | null;
  /** Where the deny-list / safety scan lives (repo path), so a build record can cite it. */
  scanner: string;
};

export type AssetDelivery = {
  supported: boolean;
  /** How asset files reach players. */
  via: "server-pushed-pack" | "client-zip" | "client-mod" | "server-files" | "none";
  /** available = delivery works today; planned = designed, not built. */
  availability: "available" | "planned" | "none";
  note: string;
};

export type InstallRules = {
  side: "server" | "client" | "both";
  serverPath: string;
  needsRestart: boolean;
  hotReload: boolean;
  summary: string;
};

export type TestLane = {
  compile: boolean;
  scan: boolean;
  /** Boot the real game server with the artifact. */
  boot: "none" | "planned" | "available";
  /** Scripted functional checks (bot, RCON...). */
  functional: "none" | "planned" | "available";
  notes: string;
};

/**
 * One deterministic routing rule. The core router matches `keywords` (lower-case regex sources) against the spec text
 * and prompt; on a match it adds `route` and the honest limit, and checks `requiresCapability` on the target version.
 */
export type RouteRule = {
  id: string;
  keywords: string[];
  /** Asset kinds that trigger this rule without any keyword. */
  assetKinds?: AssetKind[];
  route?: ArtifactRoute;
  requiresCapability?: { capability: string; message: string; /** true = a missing capability is a downgrade (warn), not a block */ downgrade?: boolean;
    /** a weaker capability that still serves the rule (e.g. 1.21.1 legacy custom model data): present = a warn with this message instead of the block */
    fallback?: { capability: string; message: string } };
  /** Build-asset kinds (lib/cyrus/assets/kinds.ts) this rule asks for, when they differ from the spec kinds in assetKinds. */
  buildAssetKinds?: string[];
  /** Shown whenever the rule matches (a fact the user must know: a restart, a client-side limit...). */
  limit?: { severity: "info" | "warn"; message: string };
};

export interface GameAdapter {
  game: string;
  name: string;
  maturity: AdapterMaturity;
  artifacts: readonly ArtifactType[];
  /** The route a request lands on when nothing else is asked for. */
  defaultRoute: ArtifactRoute;
  toolchain: ToolchainProfile;
  /** Where the model's API knowledge for this game lives (two systems exist today, see G-gaps.md (b)). */
  knowledge: { kind: "version-sheets" | "knowledge-pack" | "none"; ref: string };
  versions: {
    list: () => readonly AdapterVersion[];
    get: (id: string) => AdapterVersion | null;
    hasCapability: (id: string, capability: string) => boolean;
  };
  assetDelivery: Readonly<Record<AssetKind, AssetDelivery>>;
  install: InstallRules;
  testLane: TestLane;
  routeRules: readonly RouteRule[];
  /** Design file kinds this game's designers compile (lib/cyrus/designer). Absent = no designers (code only). Read by the capability manifest. */
  designers?: readonly ("item" | "menu" | "quest" | "boss" | "encounter" | "hud" | "motion")[];
  /** 3D/texture asset facts (formats, channels, delivery, worker class, legal). Optional: a game without one is text/code only. */
  assetProfile?: AssetProfile;
}
