// The game adapters the engine core knows about. Adding a game = one adapter file + one entry here.
import type { GameAdapter } from "./types";
import { minecraftAdapter } from "./minecraft";

export const ADAPTERS: readonly GameAdapter[] = [minecraftAdapter];

export function getAdapter(game: string): GameAdapter | null {
  return ADAPTERS.find((a) => a.game === game) ?? null;
}

export type { GameAdapter } from "./types";

