  const rule = c?.lanes[lane];
  if (!rule) return { lane, availability: "unavailable", reason: `${ctx.gameName} has no capability entry for this yet, so Cyrus does not offer it.`, substitute: null, minVersion: null, cause: "game" };
  const base = { lane, substitute: rule.substitute ? fill(rule.substitute, ctx) : null, minVersion: rule.minVersion ?? null };
  if (rule.base === "unavailable") return { ...base, availability: "unavailable", reason: fill(rule.reason, ctx), cause: "game" };
  if (rule.requires && !ctx.hasCapability(rule.requires.capability)) {
    const fb = rule.requires.fallback;
    if (fb && ctx.hasCapability(fb.capability)) return { ...base, availability: "limited", reason: fill(fb.reason, ctx), cause: "version" };
    return { ...base, availability: "unavailable", reason: fill(rule.requires.reason, ctx), cause: "version" };
  }
  if (rule.flag && !ctx.flags?.[rule.flag]) return { ...base, availability: "unavailable", reason: `${fill(rule.reason, ctx).replace(/\.$/, "")}, but it is not switched on in Cyrus yet.`, cause: "flag" };
  return { ...base, availability: rule.base, reason: fill(rule.reason, ctx), cause: "ok" };
}

/** The whole "what this version supports" panel, in lane order. */
export function resolveCapabilities(c: CapabilityCatalogue | null | undefined, ctx: CapabilityContext): LaneCapability[] {
  return LANES.map((l) => resolveLane(c, l, ctx));
}

/** The pre-build warning for one lane the prompt needs but this game/version cannot produce. */
export function laneWarning(cap: LaneCapability, label: string, ctx: Pick<CapabilityContext, "gameName" | "version">): string {
  const sub = cap.substitute ? ` Cyrus will build ${cap.substitute.replace(/\.$/, "")} instead.` : "";
  const pick = cap.cause === "version" && cap.minVersion ? ` Pick ${cap.minVersion} or newer to get them.` : "";
  return `${label} ${cap.availability === "limited" ? "are limited" : "are not available"} on ${ctx.gameName} ${ctx.version}: ${cap.reason.replace(/\.$/, "")}.${sub}${pick}`;
}

