export type HealthIssue = { code: string; severity: "error" | "warn"; message: string };

const ISO_DAY = /^\d{4}-\d{2}-\d{2}/;

/**
 * Every rule a record must satisfy. `adapterMaturity` = what the adapter file really says; null = the record names an
 * adapter file but it could not be loaded; undefined = not checked (the admin page, for adapters not registered yet).
 * Errors fail the onboarding health test; warnings are shown on the admin dashboard.
 */
export function checkRecord(r: OnboardingRecord, adapterMaturity?: Maturity | null): HealthIssue[] {
  const out: HealthIssue[] = [];
  const err = (code: string, message: string) => out.push({ code, severity: "error", message });
  const warn = (code: string, message: string) => out.push({ code, severity: "warn", message });
  const signed = (g: OwnerGateId) => !!r.gates[g]?.by && !!r.gates[g]?.at;
  const grandfathered = r.status === "reference" || r.retrofit === true;

  if (!GAME_ID_RE.test(r.game)) err("bad_game_id", `game id "${r.game}" must match ${GAME_ID_RE}`);
  if (!ONBOARDING_STATUSES.includes(r.status)) err("bad_status", `unknown status ${String(r.status)}`);
  if (!PHASE_IDS.includes(r.phase)) err("bad_phase", `unknown phase ${String(r.phase)}`);
  if (!MATURITY_LADDER.includes(r.declaredMaturity)) err("bad_maturity", `unknown maturity ${String(r.declaredMaturity)}`);
  if (!ISO_DAY.test(r.updatedAt)) err("bad_date", "updatedAt must be an ISO date");
  for (const s of r.emitters) if (!STUDIO_IDS.includes(s)) err("bad_emitter", `unknown studio id ${s}`);
  for (const [g, sig] of Object.entries(r.gates)) {
    if (!OWNER_GATES.some((x) => x.id === g)) err("bad_gate", `unknown owner gate ${g}`);
    else if (!sig?.by || !sig?.at || !ISO_DAY.test(sig.at)) err("bad_signature", `gate ${g} needs by + an ISO date (only the owner signs)`);
  }
  for (const [k, v] of Object.entries(r.evidence)) if (v && (!v.ref || !ISO_DAY.test(v.at))) err("bad_evidence", `evidence ${k} needs a ref and an ISO date`);

  // 1. The claim never exceeds the evidence.
  const proven = evidenceMaturity(r.evidence);
  if (rank(r.declaredMaturity) > rank(proven)) err("maturity_exceeds_evidence", `declared ${r.declaredMaturity} but the evidence only supports ${proven} (${LADDER_CRITERIA[r.declaredMaturity].summary})`);
  // 2. The adapter file never claims more than the record.
  if (adapterMaturity) {
    if (rank(adapterMaturity) > rank(r.declaredMaturity)) err("adapter_exceeds_record", `adapter says ${adapterMaturity}, the onboarding record ${r.declaredMaturity}`);
    else if (adapterMaturity !== r.declaredMaturity) warn("adapter_below_record", `adapter says ${adapterMaturity}, the record ${r.declaredMaturity}`);
  } else if (adapterMaturity === null && r.adapterFile) err("adapter_not_loaded", `record names ${r.adapterFile} but no adapter maturity was read`);
  // 3. Owner gates in front of the rungs (retro-fitted games and the reference implementation predate the playbook).
  if (rank(r.declaredMaturity) >= rank("beta") && !signed("G6-beta")) (grandfathered ? warn : err)("beta_gate", "beta needs owner gate G6-beta signed");
  if (r.declaredMaturity === "stable" && !signed("G7-legal")) err("stable_gate", "stable needs owner gate G7-legal signed");
  if (phaseNumber(r.phase) > 0 && !signed("G0-go") && r.status === "active") (grandfathered ? warn : err)("go_gate", "a game past screening needs owner gate G0-go");
  // 4. Status rules.
  if ((r.status === "on-hold" || r.status === "rejected") && !r.holdReason?.trim()) err("hold_reason", `${r.status} needs a holdReason`);
  if (r.status === "live") {
    if (!signed("G9-launch")) err("live_gate", "live needs owner gate G9-launch");
    if (rank(r.declaredMaturity) < rank("beta")) err("live_maturity", "a live game needs at least beta");
  }
  // 5. Shape of the work.
  if (r.adapterFile && !/^lib\/cyrus\/adapters\/[a-z0-9-]+\.ts$/.test(r.adapterFile)) err("adapter_path", "adapterFile must be lib/cyrus/adapters/<id>.ts");
  if (r.supportFile && !/^lib\/cyrus\/games\/[a-z0-9-]+\.ts$/.test(r.supportFile)) err("support_path", "supportFile must be lib/cyrus/games/<id>.ts");
  if (!r.research.length) warn("no_research", "no research files listed (reuse what exists before researching again)");
  if (r.playbookVersion !== undefined && !/^\d+\.\d+\.\d+$/.test(r.playbookVersion)) err("bad_playbook_version", "playbookVersion must be x.y.z");
  return out;
}

