      requires: { capability: "itemModelDefinitions", reason: "per-state item looks need 1.21.4+ item model definitions" },
    },
    sound: { base: "available", reason: "custom sounds with subtitles travel in the server-pushed resource pack; players accept it on join", substitute: "vanilla sounds" },
    model3d: {
      base: "limited", reason: "a server cannot add new entity models; Cyrus can shape looks from item models on display entities (static, no skeleton)",
      substitute: "display entities wearing custom-textured item models", minVersion: "1.21.4",
      requires: { capability: "itemModelDefinitions", reason: "{game} {version} has no item model definitions for display-entity looks" },
    },
    creature: {
      base: "available", reason: "animated custom creatures are BetterModel display-entity models on an invisible, silenced vanilla mob",
      substitute: "a vanilla base mob (scaled to size) with custom sounds and custom-textured items", minVersion: "26.1.2", flag: "CYRUS_CREATURES",
      requires: { capability: "animatedCreatures", reason: "custom mob models and skins need Minecraft 26.x with BetterModel (Mob skin: coming soon)" },
    },
    designItem: { base: "available", reason: "items with abilities are built from a typed design, editable in config.yml", substitute: "plain plugin code", flag: "CYRUS_DESIGNER" },
    designMenu: { base: "available", reason: "chest-menu GUIs, shops and dialogues from a typed design (no player trading or auctions)", substitute: "plain plugin code", flag: "CYRUS_DESIGNER" },
    designQuest: { base: "available", reason: "quests with objectives, chains, repeats and rewards from a typed design", substitute: "plain plugin code", flag: "CYRUS_DESIGNER" },
    designBoss: { base: "available", reason: "boss fights on a vanilla mob: phases, telegraphed attacks, waves, a boss bar (no custom boss models)", substitute: "plain plugin code", flag: "CYRUS_DESIGNER" },
    designHud: { base: "limited", reason: "glyph HUDs only (action bar, boss bars, sidebar); free-form widgets and minimaps need a client mod", substitute: "plain action bar and boss bar text", flag: "CYRUS_DESIGNER" },
    motion: { base: "limited", reason: "animated props are display entities placed by command; they are not saved with the world", substitute: "static blocks or items", minVersion: "1.21.4", flag: "CYRUS_DESIGNER",
      requires: { capability: "itemModelDefinitions", reason: "animated props need 1.21.4+ item models" } },
    config: { base: "available", reason: "settings live in the plugin's config.yml (the Config Studio edits them when it is switched on)" },
    datapack: { base: "available", reason: "recipes, loot tables, advancements and tags as a data pack (vanilla items only)", substitute: "plugin code for the same rules", flag: "CYRUS_DATAPACK_STUDIO" },
    worldgen: { base: "limited", reason: "new biomes and structures in the mod's own dimension, new chunks only, one restart to load", substitute: "no world generation", flag: "CYRUS_WORLDGEN" },
    library: { base: "available", reason: "ready-made sounds from the Nxeon sound library", substitute: "sounds made for this mod", flag: "CYRUS_SOUND_LIBRARY_CLEARED" },
  },
};

