      assert.deepEqual(missingLanes(a.capabilities), [], `${a.game} covers every lane`);
    }
  });
  it("a beta adapter without a complete catalogue fails the onboarding health check", () => {
    const rec = { game: "fakegame", status: "active", phase: "capability", declaredMaturity: "template", updatedAt: "2026-10-11", emitters: [], gates: {}, evidence: {}, research: ["x"] } as unknown as Parameters<typeof checkRecord>[0];
    assert.ok(errorsOf(checkRecord(rec, "beta", { catalogueMissing: ["texture"] })).some((i) => i.code === "capability_catalogue"));
