describe("Minecraft matrix: versions x lanes", () => {
  const cat = minecraftAdapter.capabilities!;
  const at = (v: string, l: Lane, f?: Record<string, boolean>) => resolveLane(cat, l, mc(v, f)).availability;
  const EXPECT: Record<string, Partial<Record<Lane, string>>> = {
    "1.21.1": { texture: "limited", itemStates: "unavailable", sound: "available", model3d: "unavailable", creature: "unavailable", motion: "unavailable", designItem: "available", designHud: "limited" },
    "1.21.4": { texture: "available", itemStates: "available", sound: "available", model3d: "limited", creature: "unavailable", motion: "limited" },
    "1.21.8": { texture: "available", itemStates: "available", creature: "unavailable" },
    "1.21.11": { texture: "available", itemStates: "available", sound: "available", model3d: "limited", creature: "unavailable", designBoss: "available", worldgen: "limited" },
    "26.2": { texture: "available", creature: "available", model3d: "limited" },
  };
  for (const [v, lanes] of Object.entries(EXPECT)) for (const [l, want] of Object.entries(lanes)) {
    it(`${v} ${l} = ${want}`, () => assert.equal(at(v, l as Lane), want));
  }
  it("every lane on every registry version resolves to a reason (never empty)", () => {
    for (const v of minecraftAdapter.versions.list()) for (const c of resolveCapabilities(cat, mc(v.id))) assert.ok(c.reason.length > 10, `${v.id} ${c.lane}`);
  });
  it("1.21.11 creature: honest 'Mob skin: coming soon' with the substitute and the minimum version", () => {
    const c = resolveLane(cat, "creature", mc("1.21.11"));
    assert.equal(c.cause, "version");
    const w = laneWarning(c, "Creature models", { gameName: "Minecraft", version: "1.21.11" });
    assert.match(w, /not available on Minecraft 1\.21\.11/);
    assert.match(w, /Mob skin: coming soon/);
    assert.match(w, /vanilla base mob/);
    assert.match(w, /Pick 26\.1\.2 or newer/);
  });
  it("a switched-off host flag says 'not switched on', never 'available'", () => {
    const c = resolveLane(cat, "designBoss", mc("1.21.11", {}));
    assert.equal(c.availability, "unavailable");
    assert.equal(c.cause, "flag");
    assert.match(c.reason, /not switched on/);
  });
});

describe("a fake second game gets the same warnings with no Minecraft code", () => {
  const fake: CapabilityCatalogue = {
    schema: CAPABILITY_SCHEMA, game: "fakegame",
    lanes: Object.fromEntries(LANES.map((l) => [l, l === "texture"
      ? { base: "available" as const, reason: "textures ship in a client zip", substitute: "the default art", minVersion: "2.0", requires: { capability: "texturePacks", reason: "{game} {version} has no texture packs" } }
      : { base: "unavailable" as const, reason: `{game} cannot do ${l}`, substitute: "plain code" }])),
  };
  const ctx = (version: string): CapabilityContext => ({ game: "fakegame", gameName: "Fake Game", version, hasCapability: (c) => version === "2.0" && c === "texturePacks" });
  it("old version: textures unavailable with reason, substitute and 'Pick 2.0 or newer'", () => {
    const c = resolveLane(fake, "texture", ctx("1.0"));
    assert.equal(c.availability, "unavailable");
    assert.equal(laneWarning(c, "Textures", { gameName: "Fake Game", version: "1.0" }), "Textures are not available on Fake Game 1.0: Fake Game 1.0 has no texture packs. Cyrus will build the default art instead. Pick 2.0 or newer to get them.");
  });
  it("new version: available", () => assert.equal(resolveLane(fake, "texture", ctx("2.0")).availability, "available"));
  it("a lane the game cannot do is unavailable everywhere", () => assert.equal(resolveLane(fake, "sound", ctx("2.0")).availability, "unavailable"));
  it("no catalogue at all = everything unavailable (fail closed)", () => assert.ok(resolveCapabilities(null, ctx("2.0")).every((c) => c.availability === "unavailable")));
});

