export function matchBossWords(text: string): string[] {
  const t = (text ?? "").replace(/\bboss ?bars?\b/gi, " ");
  if (BOSS_EXCLUDE.test(text ?? "")) return [];
  const m = BOSS_WORDS.exec(t);
  return m ? [`boss:${m[0].toLowerCase().slice(0, 30)}`] : [];
}

/** Menu / quest words (and no excluded feature): the gameplay part of the designer route. */
export function matchGameplayWords(text: string): { menus: boolean; quests: boolean; matched: string[] } {
  const t = text ?? "";
  if (GAMEPLAY_EXCLUDE.test(t)) return { menus: false, quests: false, matched: [] };
  const m = MENU_WORDS.exec(t), q = QUEST_WORDS.exec(t);
  return { menus: !!m, quests: !!q, matched: [...(m ? [`menu:${m[0].toLowerCase()}`] : []), ...(q ? [`quest:${q[0].toLowerCase()}`] : [])] };
}

/** Motion-prop words (and no vehicle / mob-animation request): the motion part of the designer route. */
export function matchMotionWords(text: string): string[] {
  const t = text ?? "";
  if (MOTION_EXCLUDE.test(t)) return [];
  const m = MOTION_WORDS.exec(t);
  return m ? [`motion:${m[0].toLowerCase()}`] : [];
}

const explicitDesign = (raw: unknown) => (Array.isArray(raw) ? raw.includes("design") : !!raw && typeof raw === "object" && (raw as Record<string, unknown>).design === true);

export function matchDesignerWords(text: string): string[] {
  const i = ITEM_WORDS.exec(text ?? ""), a = ABILITY_WORDS.exec(text ?? "");
  return i && a ? [`item:${i[0].toLowerCase()}`, `ability:${a[0].toLowerCase()}`] : [];
