  const text = String(b.text || "").trim();
  if (text.length < 4 || text.length > 4000) return { error: "text must be 4-4000 characters" };
  return { text, game: String(b.game || "minecraft").slice(0, 40), mcVersion: String(b.mcVersion || "").slice(0, 20) };
}

module.exports = { LANES, PLANNER_PROMPT, plannerInput, parsePlanBody };

