let healthCache: { at: number; v: { ok: boolean; [k: string]: unknown } | null } | null = null;
/** /health, cached for 5 minutes (also a failure, for 1 minute): used for the engine release record. */
export async function svcHealthCached(): Promise<{ ok: boolean; [k: string]: unknown } | null> {
  if (healthCache && Date.now() - healthCache.at < (healthCache.v ? 300_000 : 60_000)) return healthCache.v;
  const v = await svcHealth();
  healthCache = { at: Date.now(), v };
  return v;
}

export async function svcHealth(): Promise<{ ok: boolean; [k: string]: unknown } | null> {
  try {
    const r = await call("/health", { timeoutMs: 4000 });
    return r.ok ? await r.json() : null;
  } catch { return null; }
}

/**
 * `tier` (Cyrus model picker, lib/cyrus/models.ts): optional explicit model override.
 * Service image modbuilder:0.3+ maps katara/saka/yakko to a model and answers 400 for
 * anything else; omitted = the service's own routing (backwards compatible).
 */
export type SvcImage = { name: string; type: string; data: string };

/**
 * `images` (Cyrus, service image modbuilder:0.4+): reference images as base64. The service
 * re-checks type and size and puts them in the build workspace for the model to Read.
 * Omitted = no images (older images answer 400 for unknown shapes, so only send when present).
 */
/**
 * `assets` (Cyrus R1, lib/cyrus/assets/request.ts): what the PLAN allows this build to generate plus the mod's reserved
 * namespace. Only sent when something is allowed, so every other request is byte-identical to before.
 */
export async function svcCreate(body: { id: string; prompt: string; mcVersion: string; pluginName?: string; baseBuildId?: string; changeRequest?: string; tier?: "katara" | "saka" | "yakko"; images?: SvcImage[]; assets?: { texture: boolean; sound: boolean; namespace: string; library?: boolean }; /** Cyrus catalog tools (lib/cyrus/library/v2/build-offer.ts), image 0.6+ */ catalog?: import("../library/v2/build-offer").SvcCatalogOffer; /** Cyrus r31: a Designer Studio revision, built with no model */ designEdit?: { revisionId: string; files: { id: string; spec: unknown }[] } }): Promise<ServiceBuild> {
  const r = await call("/builds", { method: "POST", body: JSON.stringify(body), timeoutMs: body.images?.length ? 45_000 : 15_000 });
  const j = await r.json().catch(() => ({}));
  if (r.status !== 202) throw new Error((j as { error?: string }).error || `service returned ${r.status}`);
  return j as ServiceBuild;
}

