  const r = await call("/plan", { method: "POST", body: JSON.stringify(body), timeoutMs });
  if (!r.ok) throw new ModBuilderUnavailable(`planner returned ${r.status}`);
  const j = (await r.json().catch(() => ({}))) as { text?: unknown; costUsd?: unknown; ms?: unknown };
  return { text: typeof j.text === "string" ? j.text : null, costUsd: typeof j.costUsd === "number" ? j.costUsd : 0, ms: typeof j.ms === "number" ? j.ms : 0 };
}
