import { NextResponse } from "next/server";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { liveBuildSpend, modSpend } from "@/lib/cyrus/tokens/spend";
import { NOT_FOUND } from "@/app/api/mod-builder/_lib";

export const dynamic = "force-dynamic";

const ID = /^[A-Za-z0-9_-]{1,64}$/;

/**
 * r41 token spend (read only, the caller's own builds): ?build=<id> = the live meter of one build (estimated so far vs
 * settled); ?mod=<any build id of the mod> = the per-mod breakdown (every version, change and asset build).
 */
export async function GET(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const q = new URL(req.url).searchParams;
  const build = q.get("build");
  const mod = q.get("mod");
  const id = build ?? mod;
  if (!id || !ID.test(id)) return NOT_FOUND();
  const out = build ? await liveBuildSpend(user.id, id) : await modSpend(user.id, id);
  if (!out) return NOT_FOUND();
  return NextResponse.json(out, { headers: { "Cache-Control": "no-store" } });
}

