// Cyrus mod planner: the PRE-BUILD gate (pure). A plan with a lane the prompt needs but this game/version/plan cannot
// produce must be confirmed ("Continue anyway") BEFORE any tokens are held: lib/modbuilder/create.ts calls this before
// gateBuild (the hold), so a refused request never creates a reservation. API callers that cannot show a plan screen
// (API v1, the plain builds route) pass `requireAck: false` and get the same warnings back as asset notices instead.
import type { ModPlan } from "./decide";

export type PreBuildCheck = { ok: true } | { ok: false; status: 409; json: { error: string; code: "plan_confirm"; warnings: string[] } };

export function preBuildCheck(plan: Pick<ModPlan, "mustConfirm" | "warnings">, opts: { requireAck: boolean; ack: unknown }): PreBuildCheck {
  if (!opts.requireAck || !plan.mustConfirm || opts.ack === true) return { ok: true };
  return { ok: false, status: 409, json: { code: "plan_confirm", warnings: plan.warnings, error: `Before you spend anything: ${plan.warnings[0]}${plan.warnings.length > 1 ? ` (and ${plan.warnings.length - 1} more)` : ""} Press "Continue anyway" to build without it.` } };
}
