// Cyrus mod planner: the EVAL HOOK. Scores lane selection against labelled prompts: the planner golden set
// (test/fixtures/cyrus-planner/golden.json) and the build eval set (services/modbuilder/eval, loadEvalSet), whose
// assetKinds / designer / route labels map onto planner lanes here. Pure; the needs function is injected, so the same
// scorer runs the deterministic rules (free, in CI) or the planner model (scripts, budgeted by the caller).
import type { EvalPrompt } from "../eval/set";
import { LANES, type Lane, type LaneNeed } from "./lanes";

/** Asset-ish lanes: the ones over-requesting would cost money or promise assets. */
export const ASSET_LANES: readonly Lane[] = ["texture", "itemStates", "sound", "model3d", "creature", "designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion", "datapack", "worldgen"];

export type LaneCase = { id: string; text: string; need: Lane[]; never?: Lane[]; plain?: boolean };

/** An eval-set prompt as a lane case (labels: assetKinds, designer parts, route). */
export function caseFromEvalPrompt(p: EvalPrompt): LaneCase | null {
  if (p.must_refuse) return null;
  const k = p.assetKinds ?? [];
  const need = new Set<Lane>();
  if (k.includes("texture")) need.add("texture");
  if (k.includes("sound")) need.add("sound");
  if (k.includes("creature") || k.includes("model")) need.add("creature");
  for (const d of p.designer ?? []) {
    if (d === "item") need.add("designItem");
    if (d === "bosses") need.add("designBoss");
    if (d === "hud") need.add("designHud");
    if (d === "motion") need.add("motion");
  }
  if (p.route === "dataPack") need.add("datapack");
  const plain = p.route === "plugin" && !k.length && !(p.designer ?? []).length && ["commands", "gameplay", "stateful", "compat"].includes(p.category);
  return { id: p.key, text: p.prompt, need: [...need], plain };
}

export type CaseScore = { id: string; ok: boolean; missing: Lane[]; extra: Lane[]; forbidden: Lane[] };
export function scoreCase(c: LaneCase, needs: LaneNeed[]): CaseScore {
  const got = new Set(needs.filter((n) => n.need).map((n) => n.lane));
  const missing = c.need.filter((l) => !got.has(l));
  const never = new Set<Lane>([...(c.never ?? []), ...(c.plain ? ASSET_LANES.filter((l) => !c.need.includes(l)) : [])]);
  const forbidden = [...never].filter((l) => got.has(l));
  const extra = ASSET_LANES.filter((l) => got.has(l) && !c.need.includes(l) && !never.has(l));
  return { id: c.id, ok: !missing.length && !forbidden.length, missing, extra, forbidden };
}

export type SetScore = { cases: number; passed: number; recall: number; plainCases: number; plainOverRequested: number; results: CaseScore[] };
export function scoreSet(cases: LaneCase[], needsOf: (text: string) => LaneNeed[]): SetScore {
  const results = cases.map((c) => scoreCase(c, needsOf(c.text)));
  const wanted = cases.reduce((a, c) => a + c.need.length, 0);
  const hit = results.reduce((a, r, i) => a + (cases[i].need.length - r.missing.length), 0);
  const plain = cases.map((c, i) => [c, results[i]] as const).filter(([c]) => c.plain);
  return {
    cases: cases.length, passed: results.filter((r) => r.ok).length, recall: wanted ? Math.round((hit / wanted) * 100) / 100 : 1,
    plainCases: plain.length, plainOverRequested: plain.filter(([, r]) => r.forbidden.length > 0).length, results,
  };
}

export { LANES };

