import { decidePlan, readPlannedRequest, toAssetsRequest, builtLanes } from "../lib/cyrus/planner/decide";
import { analyzeNeeds, buildModPlan, capabilityContext } from "../lib/cyrus/planner/run";
import { preBuildCheck } from "../lib/cyrus/planner/gate";
import { autoModel, planEstimate } from "../lib/cyrus/planner/estimate";
import { caseFromEvalPrompt, scoreSet, type LaneCase } from "../lib/cyrus/planner/eval";
import { loadEvalSet } from "../lib/cyrus/eval/set";
import { resolveBuildAssets, type AssetRequestDeps } from "../lib/cyrus/assets/request";
import { parseTokenConfig } from "../lib/cyrus/tokens/config";
import { tokensForCost } from "../lib/cyrus/tokens/economy";

// eslint-disable-next-line @typescript-eslint/no-require-imports
const TXJS = require("../services/modbuilder/textures.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const P = require("../services/modbuilder/prompts.js");
// eslint-disable-next-line @typescript-eslint/no-require-imports
const PLN = require("../services/modbuilder/planner.js");

const GOLEM = "Create me a 3 block tall golem creature, thows rocks at you and grunts and groans when attacking and when attacked";
const golden = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-planner/golden.json"), "utf8")).prompts as LaneCase[];
const OFF: Record<string, boolean> = {};
const ON = { CYRUS_DESIGNER: true, CYRUS_ITEM_STATES: true, CYRUS_CREATURES: true, CYRUS_DATAPACK_STUDIO: true, CYRUS_WORLDGEN: true, CYRUS_SOUND_LIBRARY_CLEARED: true };
const plan = (text: string, version: string, tier: string | null, flags: Record<string, boolean> = OFF, toggles?: Partial<Record<Lane, boolean>>) => {
  const { ctx, catalogue } = capabilityContext("minecraft", version, flags);
  return decidePlan({ needs: ruleNeeds(text), source: "rules", catalogue, ctx, plan: tier, toggles });
};
const lane = (p: ReturnType<typeof plan>, l: Lane) => p.lanes.find((x) => x.lane === l)!;

describe("golden lane selection (deterministic rules, 40 prompts)", () => {
  const s = scoreSet(golden, (t) => ruleNeeds(t));
  for (const r of s.results) it(`${r.id}`, () => assert.ok(r.ok, `missing ${r.missing.join(",")} forbidden ${r.forbidden.join(",")}`));
  it("no over-requesting on plain-code prompts", () => assert.equal(s.plainOverRequested, 0));
  it("the build eval set: lane recall from the rules stays >= 0.9 (eval hook)", () => {
    const cases = loadEvalSet().map(caseFromEvalPrompt).filter((c): c is LaneCase => !!c);
    const e = scoreSet(cases, (t) => ruleNeeds(t));
    assert.ok(e.cases > 150, `${e.cases} eval prompts`);
    assert.ok(e.recall >= 0.9, `recall ${e.recall}`);
  });
});

describe("planner contract (zod) and the fallback", () => {
  const good = JSON.stringify({ lanes: { creature: { need: true, why: "a new golem mob", confidence: 0.9 }, sound: { need: true, why: "grunts", confidence: 0.8 }, texture: { need: true, why: "thrown rock", confidence: 0.7 } } });
  it("parses plain and fenced JSON, fills missing lanes as not needed", () => {
    for (const raw of [good, "```json\n" + good + "\n```", `Here you go: ${good}`]) {
      const p = parsePlannerText(raw)!;
      assert.equal(p.length, LANES.length);
      assert.deepEqual(p.filter((x) => x.need).map((x) => x.lane).sort(), ["creature", "sound", "texture"]);
    }
  });
  it("rejects invalid answers (not JSON, wrong types, out-of-range confidence)", () => {
    for (const raw of ["", "no", "{", JSON.stringify({ lanes: { texture: { need: "yes" } } }), JSON.stringify({ lanes: { texture: { need: true, confidence: 7 } } }), JSON.stringify({ nope: 1 })]) assert.equal(parsePlannerText(raw), null, raw);
  });
  it("a literal ask is never dropped by the model", () => {
    const m = mergeNeeds(parsePlannerText(JSON.stringify({ lanes: {} }))!, "A sword with a custom texture");
    assert.equal(m.lanes.find((l) => l.lane === "texture")!.need, true);
  });
  it("analyzeNeeds: planner answer -> source planner; timeout / invalid / throw / unsupported -> rules", async () => {
    const t = (s: string) => `${s} ${Math.random()}`; // distinct text per case (the cache)
    assert.equal((await analyzeNeeds({ text: t(GOLEM), game: "minecraft", mcVersion: "1.21.11" }, { ask: async () => ({ text: good, costUsd: 0.001, ms: 900 }) })).source, "planner");
    const slow = await analyzeNeeds({ text: t(GOLEM), game: "minecraft", mcVersion: "1.21.11" }, { ask: () => new Promise((r) => setTimeout(() => r({ text: good, costUsd: 0, ms: 0 }), 500)), timeoutMs: 20 });
    assert.equal(slow.source, "rules"); assert.match(slow.error!, /timed out/);
    assert.equal((await analyzeNeeds({ text: t(GOLEM), game: "minecraft", mcVersion: "1.21.11" }, { ask: async () => ({ text: "lol", costUsd: 0.001, ms: 1 }) })).source, "rules");
    assert.equal((await analyzeNeeds({ text: t(GOLEM), game: "minecraft", mcVersion: "1.21.11" }, { ask: async () => { throw new Error("down"); } })).source, "rules");
    assert.equal((await analyzeNeeds({ text: t(GOLEM), game: "minecraft", mcVersion: "1.21.11" }, { ask: async () => ({ text: good, costUsd: 0, ms: 0 }), supports: async () => false })).source, "rules");
    const fb = await analyzeNeeds({ text: t(GOLEM), game: "minecraft", mcVersion: "1.21.11" }, {});
    assert.deepEqual(fb.lanes.filter((x) => x.need).map((x) => x.lane).filter((l) => ["creature", "sound", "texture"].includes(l)).sort(), ["creature", "sound", "texture"]);
  });
  it("the service planner prompt names every lane and validates its body", () => {
    for (const l of LANES) assert.match(PLN.PLANNER_PROMPT, new RegExp(`- ${l}:`));
    assert.ok(PLN.parsePlanBody({ text: "hi" }).error);
    assert.equal(PLN.parsePlanBody({ text: GOLEM, mcVersion: "1.21.11" }).text, GOLEM);
    assert.match(PLN.plannerInput({ text: "x", game: "minecraft", mcVersion: "1.21.11" }), /<request>\nx\n<\/request>/);
  });
});

describe("capability router: the golem on 1.21.11 (the live test)", () => {
  const p = plan(GOLEM, "1.21.11", "all");
  it("texture and sound are built, the creature model is blocked with the honest reason", () => {
    assert.equal(lane(p, "texture").state, "build");
    assert.equal(lane(p, "sound").state, "build");
    assert.equal(lane(p, "creature").state, "blocked");
    assert.equal(lane(p, "creature").blockedBy, "version");
    assert.match(lane(p, "creature").warning!, /Mob skin: coming soon/);
    assert.match(lane(p, "creature").warning!, /Pick 26\.1\.2 or newer/);
  });
  it("needs an explicit Continue anyway", () => { assert.equal(p.mustConfirm, true); assert.ok(p.warnings.length >= 1); });
  it("the approved request carries only buildable lanes", () => {
    const a = toAssetsRequest(p);
    assert.equal(a.creature, false);
    assert.equal(a.texture, true);
    assert.equal(a.sound, true);
    assert.ok(!a.lanes.includes("creature"));
  });
  it("a toggle removes a lane (and adding one back works)", () => {
    assert.equal(lane(plan(GOLEM, "1.21.11", "all", OFF, { sound: false }), "sound").state, "skip");
    assert.equal(lane(plan("A /spawn command", "1.21.11", "all", OFF, { sound: true }), "sound").state, "build");
  });
});

describe("fail closed on plan, version and switches", () => {
  it("Saka: sounds yes, textures blocked by the plan with the unlock line", () => {
    const p = plan(GOLEM, "1.21.11", "saka");
    assert.equal(lane(p, "sound").state, "build");
    assert.equal(lane(p, "texture").blockedBy, "plan");
    assert.match(lane(p, "texture").warning!, /All models plan/);
  });
  it("free / unknown plan: no asset lane is built", () => {
    for (const t of ["free", null, "platinum"]) {
      const p = plan(GOLEM, "1.21.11", t);
      for (const l of ["texture", "sound", "creature"] as Lane[]) assert.notEqual(lane(p, l).state, "build", `${t} ${l}`);
    }
  });
  it("1.21.1 without the legacy switch: textures blocked by the version", () => {
    const p = plan("A ruby sword that sets enemies on fire", "1.21.1", "all");
    assert.equal(lane(p, "texture").blockedBy, "version");
    assert.match(lane(p, "texture").warning!, /Pick 1\.21\.4 or newer/);
  });
  it("designers off: a boss is blocked by the switch (not 'pick a version')", () => {
    const p = plan("A boss fight against a giant zombie king with three phases", "1.21.11", "all");
    assert.equal(lane(p, "designBoss").blockedBy, "flag");
    assert.doesNotMatch(lane(p, "designBoss").warning!, /Pick/);
    assert.equal(lane(plan("A boss fight against a giant zombie king with three phases", "1.21.11", "all", ON), "designBoss").state, "build");
  });
  it("a plain command plugin needs no confirmation and requests nothing", () => {
    const p = plan("A /spawn command that teleports players to spawn", "1.21.11", "all");
    assert.equal(p.mustConfirm, false);
    assert.deepEqual(builtLanes(p).filter((l) => l !== "config"), []);
  });
});

describe("pre-build gate: no hold before Continue anyway", () => {
  const p = plan(GOLEM, "1.21.11", "all");
  it("409 plan_confirm without the ack, ok with it, ok for API callers", () => {
    const r = preBuildCheck(p, { requireAck: true, ack: undefined });
    assert.equal(r.ok, false);
    if (!r.ok) { assert.equal(r.status, 409); assert.equal(r.json.code, "plan_confirm"); assert.match(r.json.error, /Continue anyway/); }
    assert.equal(preBuildCheck(p, { requireAck: true, ack: true }).ok, true);
    assert.equal(preBuildCheck(p, { requireAck: false, ack: undefined }).ok, true);
  });
  it("createModBuild runs the plan gate BEFORE the token hold (gateBuild) and the forge requires it", () => {
    const src = fs.readFileSync(path.join(__dirname, "../lib/modbuilder/create.ts"), "utf8");
    const body = src.slice(src.indexOf("export async function createModBuild"), src.indexOf("export async function createDesignerBuild"));
    assert.ok(body.indexOf("preBuildCheck(") > 0 && body.indexOf("preBuildCheck(") < body.indexOf("gateBuild("), "plan gate before the hold");
    assert.match(fs.readFileSync(path.join(__dirname, "../app/api/cyrus/generate/route.ts"), "utf8"), /requirePlanAck: true/);
  });
});

describe("estimates and the Auto model", () => {
  const cfg = parseTokenConfig({});
  it("the estimate excludes impossible lanes (the golem's creature model is not counted)", async () => {
    const r = await buildModPlan({ text: GOLEM, game: "minecraft", mcVersion: "1.21.11", tier: "all", cfg, needs: ruleNeeds(GOLEM) }, { flags: OFF });
    const y = r.models.find((m) => m.model === "yakko")!;
    assert.deepEqual(y.usd, planEstimate(GOLEM, "yakko", builtLanes(r.plan)).usd);
    assert.ok(!builtLanes(r.plan).includes("creature"));
    // the live build spent 431 tokens on Yakko with a 250 hold: the realistic hold now covers it
    assert.ok(y.hold! >= tokensForCost(0.6884, "yakko", cfg), `hold ${y.hold} vs 431`);
  });
  it("Auto picks the cheapest capable model, capped to the plan", () => {
    assert.equal(autoModel("A /spawn command that teleports players to spawn", []), "katara");
    assert.equal(autoModel(GOLEM, ["texture", "sound"]), "saka");
    const big = "A full RPG: quests with missions, a shop menu with coins, boss fights with phases and minions, a scoreboard leaderboard, teams, a lobby with rounds and a countdown, saved player data, permissions and config";
    assert.equal(autoModel(big, ["designQuest", "designMenu", "designBoss"]), "yakko");
    assert.equal(autoModel(big, ["designQuest"], ["katara", "saka"]), "saka");
    assert.equal(autoModel(GOLEM, ["texture"], ["katara"]), "katara");
  });
});

describe("the planned request through the real asset wiring", () => {
  const NS = "nx_ab12cd34";
  const deps = (tier: string): AssetRequestDeps => ({ tierOf: async () => tier, projectForRootBuild: async () => ({ id: "cp" + "1".repeat(20), namespace: NS }), createProject: async () => ({ id: "cp" + "1".repeat(20), namespace: NS }), servicePlanner: () => true });
  const base = { userId: "u1", rootBuildId: "mb1", change: false, mcVersion: "1.21.11" };
  it("golem: texture + sound reach the service with the 'produce these' lines; no creature on 1.21.11", async () => {
    const req = toAssetsRequest(plan(GOLEM, "1.21.11", "all"));
    const r = await resolveBuildAssets({ ...base, text: GOLEM, explicit: req, plannerSource: "rules" }, deps("all"));
    assert.equal(r.service?.texture, true);
    assert.equal(r.service?.sound, true);
    assert.equal(r.service?.creature, undefined);
    assert.ok(r.service?.plan?.some((x) => x.lane === "sound"));
    assert.deepEqual(r.meta?.planned?.lanes.filter((l) => l !== "config").sort(), ["sound", "texture"]);
    const svc = TXJS.parseAssetsRequest(r.service, "1.21.11", new Set(["1.21.11"]));
    assert.equal(svc.error, undefined);
    const block = P.initialPrompt({ prompt: GOLEM, mcVersion: "1.21.11", assets: svc }, "/ws", []);
    assert.match(block, /PLANNED FOR THIS MOD/);
    assert.match(block, /vanilla base mob/);
  });
  it("a plain prompt's planned request is byte-identical to no request (no lookups)", async () => {
    const req = toAssetsRequest(plan("A /spawn command that teleports players to spawn", "1.21.11", "all"));
    const r = await resolveBuildAssets({ ...base, text: "A /spawn command that teleports players to spawn", explicit: req }, { ...deps("all"), configStudioOn: () => false });
    assert.deepEqual(r, { plan: null, service: null, meta: null });
  });
  it("the server trusts only the lane list, never client booleans", () => {
    const r = readPlannedRequest({ plan: 1, lanes: ["sound"], texture: true, creature: true, parts: { bosses: true } })!;
    assert.equal(r.texture, false); assert.equal(r.creature, false); assert.equal(r.parts.bosses, false); assert.equal(r.sound, true);
    assert.equal(readPlannedRequest(["texture"]), null);
  });
  it("planned designer parts route without the keywords", async () => {
    const req = toAssetsRequest(plan("Gravelord, the bone tyrant of the crypt, with three stages", "1.21.11", "all", ON, { designBoss: true }));
    const r = await resolveBuildAssets({ ...base, text: "Gravelord, the bone tyrant of the crypt, with three stages", explicit: req }, { ...deps("all"), designerOn: () => true });
    assert.equal(r.service?.design, true);
    assert.equal(r.service?.bosses, true);
  });
  it("an older service never receives assets.plan (unknown fields are a 400 there)", async () => {
    const req = toAssetsRequest(plan(GOLEM, "1.21.11", "all"));
    const r = await resolveBuildAssets({ ...base, text: GOLEM, explicit: req }, { ...deps("all"), servicePlanner: () => false });
    assert.equal(r.service?.plan, undefined);
  });
});

