  setActiveFile: (path: string | null) => void;
        if (selection.level === "mod") select({ level: "category", gameId: selection.gameId, category: selection.category });
        else if (selection.level === "category") select({ level: "game", gameId: selection.gameId });
        else select({ level: "core" });
      },

      setModel: (model) => set({ model }),
      setPanelOpen: (panelOpen) => set({ panelOpen }),
      setPanelTab: (panelTab) => set({ panelTab, panelOpen: true }),
      setActiveFile: (activeFile) => set({ activeFile }),
    }),
    {
      name: "cyrus-state-v1",
      storage: createJSONStorage(() => localStorage),
      skipHydration: true,
      // v6: mods/games saved before the universal categories carry v5 keys ("worlds", "mechanics"…)
      merge: (persisted, current) => {
        const p = (persisted ?? {}) as Partial<CyrusState>;
        return {
          ...current,
          ...p,
          // Local TEMPLATE mods (the old "template preview" forge) cannot be changed, built or installed any more, and a leftover
          // one in a browser steals prompts that happen to share its words. Real mods come from the account, not from here.
          userMods: [],
          userVersions: {},
          activeVersion: {},
          ...(p.customGames ? { customGames: p.customGames.map((g) => ({ ...g, categories: [...new Set(g.categories.map(toCategory))] })) } : {}),
        };
      },
      partialize: (s) => ({
        userMods: s.userMods,
        userVersions: s.userVersions,
        activeVersion: s.activeVersion,
        notes: s.notes,
        aiNotes: s.aiNotes,
        model: s.model,
        mcVersion: s.mcVersion,
        layout: s.layout,
        customGames: s.customGames,
        panelWide: s.panelWide,
      }),
    },
  ),
);

