/** Run one forge request, and keep following a real build if the connection drops. */
async function run(open: (signal: AbortSignal) => Promise<Response>, ctx: Ctx) {
  const { handle, stop } = makeHandler(ctx);
  controller = new AbortController();
  const signal = controller.signal;
  try {
    let res = await open(signal);
    for (let attempt = 0; ; attempt++) {
      if (!res.ok || !res.body) {
        const j = (await res.json().catch(() => ({ error: res.statusText }))) as Record<string, unknown>;
        throw new HttpError(String(j.error ?? "The forge did not respond"), j);
      }
      await readStream(res, handle);
      if (ctx.finished) break;
      // A real build outlives the connection: re-attach (the server re-sends the code so far).
      const job = useStore.getState().job;
      if (!job?.buildId || attempt >= 12 || signal.aborted) throw new Error("The stream ended before the mod was packaged");
      await new Promise((r) => setTimeout(r, Math.min(1200 * (attempt + 1), 5000)));
      patchJob(() => ({ files: [], steps: [] }));
      res = await fetch(`/api/cyrus/generate?follow=${encodeURIComponent(job.buildId)}`, { signal });
    }
  } catch (err) {
    stop();
    const aborted = signal.aborted;
    const s = useStore.getState();
    const real = !!s.job?.real || !!s.job?.buildId;
    fx.stopStream();
    fx.setMode("idle");
    if (err instanceof HttpError) cyrusTokens.handleBuildError(err.json);
    useStore.setState((st) => ({
