// Cyrus live-test fix (A): what a build REALLY shipped, in plain words (pure, client-safe). The model's own summary
// can say "grunts and groans" or "custom textures" when no sound or texture was built (the first live test did); the
// notes, the done message and the panel use these lines so nothing claims an asset that does not exist.
import type { ModBuildView } from "../builder/types";

const CLAIMS: { kind: "sound" | "texture" | "creature"; re: RegExp }[] = [
  { kind: "sound", re: /\b(custom (?:sounds?|audio|music|voice)|sound effects?|grunts?|groans?|roars?|growls?|sound(?:s)? (?:when|on))\b/i },
  { kind: "texture", re: /\b(custom (?:textures?|looks?|items? (?:art|look))|textured|retextur\w*|its own (?:look|texture))\b/i },
  { kind: "creature", re: /\b(custom (?:mob|creature) (?:model|skin)s?|animated (?:creature|mob|model)s?|3d model)\b/i },
];

export type AssetTruth = { sounds: number; textures: number; creatures: number; lines: string[] };

export function assetTruth(b: Pick<ModBuildView, "result" | "cyrus"> | null | undefined): AssetTruth {
  const a = b?.result?.assets ?? null;
  const sounds = new Set((a?.sounds ?? []).map((s) => `${s.set}.${s.event}`)).size;
  const textures = a?.textures?.length ?? 0;
  const creatures = a?.creatures?.length ?? 0;
  const s = b?.result?.summary;
  const said = [s?.tagline, s?.text, ...(s?.howToUse ?? [])].filter(Boolean).join(" \n ");
  const lines: string[] = [];
  if (textures) lines.push(`Custom textures: ${textures} in this mod's resource pack.`);
  if (sounds) lines.push(`Custom sounds: ${sounds} sound event${sounds === 1 ? "" : "s"}${a?.soundRender === "off" ? " (designed, not in the pack yet: no sound render host here)" : ""}.`);
  if (creatures) lines.push(`Creature models: ${creatures}.`);
  const has = { sound: sounds > 0, texture: textures > 0, creature: creatures > 0 };
  const claimed = new Set(CLAIMS.filter((c) => c.re.test(said)).map((c) => c.kind));
  if (!has.sound && (claimed.has("sound") || !lines.length)) lines.push("No custom audio in this build: it uses vanilla sounds.");
  if (!has.texture && (claimed.has("texture") || !lines.length || lines.length === 1 && !has.sound)) lines.push("No custom textures in this build: it uses vanilla looks.");
  if (!has.creature && claimed.has("creature")) lines.push("No custom creature model in this build: the mob keeps its vanilla look.");
  const notices = ((b?.cyrus as { assets?: { notices?: unknown[] } } | null)?.assets?.notices ?? []).filter((n): n is string => typeof n === "string");
  for (const n of notices.slice(0, 3)) if (!lines.includes(n)) lines.push(n);
  return { sounds, textures, creatures, lines };
}
EOF
