};
// eslint-disable-next-line @typescript-eslint/no-require-imports
const L = require("../services/modbuilder/live.js") as Live;
const PNG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 13]);
const b64 = (b: Buffer) => b.toString("base64");

describe("modbuilder live: streamed tool input", () => {
  const full = JSON.stringify({ file_path: "/work/x/src/main/java/A.java", content: 'package a;\n\tString s = "q\\"u";\n// é \u00e9' });
  it("decodes the content field at every cut point without ever inventing characters", () => {
    const want = JSON.parse(full).content as string;
    for (let i = 0; i <= full.length; i++) {
      const r = L.partialField(full.slice(0, i), "content");
      if (!r) continue;
      assert.ok(want.startsWith(r.text), `prefix at ${i}: ${JSON.stringify(r.text)}`);
    }
    assert.deepEqual(L.partialField(full, "content"), { text: want, done: true });
  });
  it("waits on a split escape instead of emitting half of it", () => {
    assert.deepEqual(L.partialField('{"content": "ab\\', "content"), { text: "ab", done: false });
    assert.deepEqual(L.partialField('{"content": "ab\\u00', "content"), { text: "ab", done: false });
    assert.deepEqual(L.partialField('{"content": "ab\\u00e9', "content"), { text: "abé", done: false });
  });
  it("finds the path once it is complete", () => {
    assert.deepEqual(L.partialField('{"file_path": "/w/src/main/java/A.ja', "file_path"), { text: "/w/src/main/java/A.ja", done: false });
    assert.equal(L.partialField('{"file_pa', "file_path"), null);
  });
});

describe("modbuilder live: only src/main/** is ever shown", () => {
  it("accepts plugin source and resources", () => {
    assert.equal(L.liveRel("/work/b1", "/work/b1/src/main/java/dev/x/A.java"), "src/main/java/dev/x/A.java");
    assert.equal(L.liveRel("/work/b1", "src/main/resources/plugin.yml"), "src/main/resources/plugin.yml");
  });
  it("refuses everything else", () => {
    for (const p of ["/work/b1/build.gradle.kts", "/work/b1/modbuilder.json", "/work/b1/reference/1.png", "/work/b2/src/main/java/A.java", "/work/b1/../b2/src/main/java/A.java", "/etc/passwd", "/work/b1/src/main/java/../../../x", "/work/b1/src/test/java/A.java", ""]) {
      assert.equal(L.liveRel("/work/b1", p), null, p);
