describe("modbuilder images: checked by content, not by claim", () => {
  it("sniffs the four image types", () => {
    assert.equal(L.sniffImage(PNG), "image/png");
    assert.equal(L.sniffImage(Buffer.from([0xff, 0xd8, 0xff, 0xe0])), "image/jpeg");
    assert.equal(L.sniffImage(Buffer.from("RIFF0000WEBPVP8 ")), "image/webp");
    assert.equal(L.sniffImage(Buffer.from("GIF89a....")), "image/gif");
    assert.equal(L.sniffImage(Buffer.from("<svg onload=alert(1)>")), null);
  });
  it("accepts up to 4 real images and nothing else", () => {
    assert.deepEqual(L.parseImages(undefined), { refs: [] });
    assert.equal(L.parseImages([{ name: "a.png", type: "image/png", data: b64(PNG) }]).refs?.[0].type, "image/png");
    assert.match(L.parseImages(Array(5).fill({ data: b64(PNG) })).error ?? "", /at most 4/);
    assert.match(L.parseImages([{ type: "image/png", data: b64(Buffer.from("<html>")) }]).error ?? "", /not a PNG/);
    assert.match(L.parseImages([{ data: "%%%not base64%%%" }]).error ?? "", /base64/);
    assert.match(L.parseImages([{ data: b64(Buffer.concat([PNG, Buffer.alloc(L.MAX_REF_BYTES)])) }]).error ?? "", /too large|5 MB/);
    assert.match(L.parseImages("x").error ?? "", /array/);
  });
  it("cleans the name", () => {
    assert.equal(L.parseImages([{ name: "../../etc/<x>.png", data: b64(PNG) }]).refs?.[0].name, "....etcx.png");
  });
});

