async function writeTool(idx, rel, content) {
  const id = `toolu_live_${idx}`;
  const input = JSON.stringify({ file_path: path.join(ws, rel), content });
  out({ type: "stream_event", event: { type: "content_block_start", index: 1, content_block: { type: "tool_use", id, name: "Write", input: {} } } });
  for (let i = 0; i < input.length; i += CHUNK) {
    out({ type: "stream_event", event: { type: "content_block_delta", index: 1, delta: { type: "input_json_delta", partial_json: input.slice(i, i + CHUNK) } } });
    if (DELAY) await sleep(DELAY);
  }
  out({ type: "stream_event", event: { type: "content_block_stop", index: 1 } });
  out({ type: "assistant", message: { id: `m${idx}`, content: [{ type: "tool_use", id, name: "Write", input: { file_path: path.join(ws, rel), content } }] } });
  fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true });
  fs.writeFileSync(path.join(ws, rel), content);
  out({ type: "user", message: { content: [{ type: "tool_result", tool_use_id: id, content: "File written" }] } });
}

