p='components/cyrus-tokens/Spend.tsx'; s=open(p).read()
old=s[s.index('/** Build screen: estimated so far vs held while it runs, then the settled result. */'):s.index('const KIND_LABEL')]
new='''const STAGE_WORD: Record<string, string> = { queued: "Waiting for a builder", planning: "Planning", coding: "Writing code", compiling: "Compiling", repairing: "Fixing", scanning: "Safety check", succeeded: "Done", failed: "Stopped" };
const clock = (ms: number) => { const t = Math.max(0, Math.round(ms / 1000)); return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, "0")}`; };

/** Ticks once a second while `on` (the elapsed clock). */
function useNow(on: boolean): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (!on) return;
    const t = window.setInterval(() => setNow(Date.now()), 1000);
    return () => window.clearInterval(t);
  }, [on]);
  return now;
}

/**
 * Build screen: the live meter. While it runs: tokens so far (from the builder's live usage, or a labelled stage
 * estimate when the builder reports none yet), the stage and the elapsed time; at the end: the settled figure, with a
 * plain line when the build spent more than it held.
 */
export function LiveSpendMeter({ buildId, live }: { buildId?: string; live: boolean }) {
  const s = useBuildSpend(buildId, live);
  const [seenAt, setSeenAt] = useState(0);
  useEffect(() => { if (s) setSeenAt(Date.now()); }, [s]);
  const running = !!s && (s.state === "running" || s.state === "settling");
  const now = useNow(running);
  if (!s || s.state === "untracked") return null;
  const pct = s.held > 0 ? Math.min(100, ((running ? s.estimated : s.charged ?? 0) / s.held) * 100) : 0;
  const elapsed = s.elapsedMs + (running && seenAt ? now - seenAt : 0);
  const kindWord = s.estimateKind === "usage" ? "from live AI usage" : s.estimateKind === "stage" ? "estimated from the stage and time" : "estimated";
  return (
    <div className="cys-meter" data-state={s.state} data-kind={s.estimateKind} aria-live="polite">
      <div className="cys-meter-top">
        <span className="cys-k">Tokens</span>
        {running ? (
          <span className="cys-v">
            <b title="Not a charge: the build is settled when it ends, for what it really used.">≈ {n(s.estimated)}</b> so far <span className="cys-est">{kindWord}</span>
            <span className="cys-of"> of {n(s.held)} held</span>
          </span>
        ) : (
          <span className="cys-v">
            <b>{n(s.charged ?? 0)}</b> spent of {n(s.held)} held <span className="cys-set">settled</span>
            {(s.returned ?? 0) > 0 && <span className="cys-of"> · {n(s.returned ?? 0)} returned to your balance</span>}
            {s.writeoff > 0 && <span className="cys-of"> · {n(s.writeoff)} covered by Cyrus</span>}
          </span>
        )}
      </div>
      <div className="cys-bar" role="meter" aria-valuemin={0} aria-valuemax={s.held} aria-valuenow={running ? s.estimated : s.charged ?? 0} aria-label="Tokens used of the tokens held">
        <span className={running ? "cys-fill cys-fill-live" : "cys-fill"} style={{ width: `${pct}%` }} />
      </div>
      <div className="cys-fine">
        {running ? (
          <>
            <span className="cys-stage">{STAGE_WORD[s.stage] ?? "Working"} · {clock(elapsed)}</span>{" "}
            {s.state === "settling" ? "Finishing up: settling the final charge..." : s.estimated > s.held ? "This build is using more than it held; the extra comes from your balance when it settles." : "You only pay for the work this build does. Whatever it doesn't use goes back to your balance."}
          </>
        ) : s.overHeld ? `${spendReason(s.reason)}. It used ${n((s.charged ?? 0) - s.held)} more than it held, taken from your balance (builds are charged for what they really use).` : spendReason(s.reason)}
      </div>
    </div>
  );
}

/** One line for a finished build (build detail). */
export function BuildSpendLine({ buildId }: { buildId?: string }) {
  const s = useBuildSpend(buildId, false);
  if (!s || s.state === "untracked") return null;
  if (s.state === "running" || s.state === "settling") return <span className="cys-line">Tokens: ≈ {n(s.estimated)} so far ({s.estimateKind === "usage" ? "live usage" : "estimated"}), {n(s.held)} held</span>;
  return (
    <span className="cys-line" title={spendReason(s.reason)}>
      Tokens: <b>{n(s.charged ?? 0)}</b> spent of {n(s.held)} held{s.overHeld ? ` (${n((s.charged ?? 0) - s.held)} more than held, from your balance)` : ""}{(s.returned ?? 0) > 0 ? `, ${n(s.returned ?? 0)} returned` : ""}{s.writeoff > 0 ? `, ${n(s.writeoff)} covered by Cyrus` : ""}
    </span>
  );
}

