#!/usr/bin/env node
// Cyrus live-test fix (B): a FAKE Claude CLI that replays the SHAPE of the first live production build
// (mbd5126c104c50af552a37, Yakko / claude-opus-5, 7 turns, $0.6877, ~79 s of planning before the first Write) at a
// compressed speed, with the stream-json the real CLI prints under --include-partial-messages: per turn a
// message_start (input + cache usage), thinking / text / tool-input deltas, message_delta (output tokens), the
// assistant message with its usage, the tool result, and finally `result` with total_cost_usd. No model, nothing paid.
// Knobs in $HOME/live-usage-fake.json: { "planMs": thinking time before the first Write (default 1500), "chunkMs": 15 }.
"use strict";
const fs = require("fs");
const path = require("path");

const a = process.argv.slice(2);
const prompt = a[a.indexOf("--") + 1] || "";
let CFG = {};
try { CFG = JSON.parse(fs.readFileSync(path.join(process.env.HOME || "/nonexistent", "live-usage-fake.json"), "utf8")); } catch { CFG = {}; }
const PLAN_MS = Math.max(0, Number(CFG.planMs ?? 1500));
const CHUNK_MS = Math.max(0, Number(CFG.chunkMs ?? 15));
const ws = process.cwd();
const out = (o) => process.stdout.write(JSON.stringify(o) + "\n");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const FILES = [
  ["src/main/resources/plugin.yml", "name: RockGolem\nversion: 1.0.0\nmain: dev.nxeon.plugins.rockgolem.RockGolem\napi-version: '1.21'\ndescription: A rock-throwing golem\nauthor: Nxeon Mod Builder\n"],
  ["src/main/resources/config.yml", "golem:\n  health: 120\n  scale: 3.0\n  throw-cooldown-ticks: 60\n"],
  ["src/main/java/dev/nxeon/plugins/rockgolem/GolemManager.java", "package dev.nxeon.plugins.rockgolem;\n\npublic class GolemManager {\n  // spawns and drives the golem\n}\n"],
  ["src/main/java/dev/nxeon/plugins/rockgolem/RockGolem.java", "package dev.nxeon.plugins.rockgolem;\n\nimport org.bukkit.plugin.java.JavaPlugin;\n\npublic class RockGolem extends JavaPlugin {\n  @Override\n  public void onEnable() { saveDefaultConfig(); }\n}\n"],
  ["modbuilder.json", JSON.stringify({ name: "RockGolem", version: "1.0.0", tagline: "A 3 block tall rock-throwing golem", summary: "Adds a golem that throws rocks.", howToUse: ["/golem spawn"] })],
];

// Per turn: [uncached, cacheWrite, cacheRead, output] roughly like the live build (Opus 5 prices make ~$0.69 in total).
const TURNS = [[3200, 21000, 0, 9800], [6, 1400, 21000, 1900], [6, 900, 22400, 2600], [6, 1600, 23300, 3900], [6, 800, 24900, 1400], [6, 600, 25700, 1500], [4, 300, 26300, 300]];

async function turn(i, write) {
  const [inp, cw, cr, outTok] = TURNS[i];
  const id = `msg_live_${i}`;
  out({ type: "stream_event", event: { type: "message_start", message: { id, usage: { input_tokens: inp, cache_creation_input_tokens: cw, cache_read_input_tokens: cr, output_tokens: 1 } } } });
  // thinking: the long, silent part of planning (no file yet)
  const thinkChars = Math.round(outTok * 4 * (write ? 0.3 : 1));
  const steps = i === 0 ? Math.max(4, Math.round(PLAN_MS / Math.max(1, CHUNK_MS * 4))) : 6;
  out({ type: "stream_event", event: { type: "content_block_start", index: 0, content_block: { type: "thinking", thinking: "" } } });
  for (let k = 0; k < steps; k++) {
    out({ type: "stream_event", event: { type: "content_block_delta", index: 0, delta: { type: "thinking_delta", thinking: "x".repeat(Math.ceil(thinkChars / steps)) } } });
    await sleep(i === 0 ? PLAN_MS / steps : CHUNK_MS);
  }
  out({ type: "stream_event", event: { type: "content_block_stop", index: 0 } });
  const content = [];
  if (write) {
    const [rel, text] = write;
    const tid = `toolu_lu_${i}`;
    const input = JSON.stringify({ file_path: path.join(ws, rel), content: text });
    out({ type: "stream_event", event: { type: "content_block_start", index: 1, content_block: { type: "tool_use", id: tid, name: "Write", input: {} } } });
    for (let k = 0; k < input.length; k += 120) { out({ type: "stream_event", event: { type: "content_block_delta", index: 1, delta: { type: "input_json_delta", partial_json: input.slice(k, k + 120) } } }); await sleep(CHUNK_MS); }
    out({ type: "stream_event", event: { type: "content_block_stop", index: 1 } });
    content.push({ type: "tool_use", id: tid, name: "Write", input: { file_path: path.join(ws, rel), content: text } });
  } else content.push({ type: "text", text: "Done." });
  out({ type: "stream_event", event: { type: "message_delta", delta: { stop_reason: write ? "tool_use" : "end_turn" }, usage: { output_tokens: outTok } } });
  const usage = { input_tokens: inp, cache_creation_input_tokens: cw, cache_read_input_tokens: cr, output_tokens: outTok };
  out({ type: "assistant", message: { id, usage, content } });
  if (write) {
    fs.mkdirSync(path.dirname(path.join(ws, write[0])), { recursive: true });
    fs.writeFileSync(path.join(ws, write[0]), write[1]);
    out({ type: "user", message: { content: [{ type: "tool_result", tool_use_id: content[0].id, content: "File written" }] } });
  }
}

(async () => {
  out({ type: "system", subtype: "init", model: "claude-opus-5" });
  const build = /Build this Paper/.test(prompt);
  // turn 0 plans (thinking only, then the first Write), turns 1..4 write the rest, the last turn answers
  if (build) { for (let i = 0; i < FILES.length; i++) await turn(i, FILES[i]); await turn(6, null); }
  else await turn(6, null);
  const tot = TURNS.reduce((s, t) => s + (t[0] * 5 + t[1] * 6.25 + t[2] * 0.5 + t[3] * 25) / 1e6, 0);
  out({ type: "result", subtype: "success", is_error: false, num_turns: build ? 7 : 1, total_cost_usd: build ? 0.6877 : +(tot / 7).toFixed(4), duration_ms: 3000, duration_api_ms: 2800, result: "Done.", usage: { input_tokens: 3238, cache_creation_input_tokens: 26600, cache_read_input_tokens: 143600, output_tokens: 21400 } });
})();

