// Live-test fix (B): the build service's running AI cost (service 0.6+, features.liveUsage) as stored on the build row
// (ModBuildResult.live). Pure; bounded and type-checked because the service is not trusted.
import type { ModBuildResult } from "./types";

export function liveFromService(raw: unknown): NonNullable<ModBuildResult["live"]> | null {
  const l = raw as { costUsd?: unknown; turns?: unknown; phase?: unknown; stage?: unknown; at?: unknown } | null | undefined;
  if (!l || typeof l.costUsd !== "number" || !Number.isFinite(l.costUsd)) return null;
