// planning (before the first file), never goes down, and settles on the billed cost; then the portal's mapping
// (liveFromService) and the meter's figure (liveEstimate / buildSpendFrom): "usage" while live usage comes in, a labelled
// "stage" estimate when it does not (an older builder: the production case, stuck at 5), "final" at the end.
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";
import { liveFromService } from "../lib/cyrus/builder/live-usage";
import { buildSpendFrom, liveEstimate } from "../lib/cyrus/tokens/spend";
import { parseTokenConfig } from "../lib/cyrus/tokens/config";
import { tokensForCost } from "../lib/cyrus/tokens/economy";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const KEY = "test-key-liveusage-0123456789";
const GOLEM = "Create me a 3 block tall golem creature, thows rocks at you and grunts and groans when attacking and when attacked";
const FAKE_JAVAC = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2); const d = a[a.indexOf("-d") + 1];
for (const f of a.filter((x) => x.endsWith(".java"))) { const pkg = (fs.readFileSync(f, "utf8").match(/^package ([\\w.]+);/m) || [, ""])[1]; const o = path.join(d, pkg.replace(/\\./g, "/"), path.basename(f, ".java") + ".class"); fs.mkdirSync(path.dirname(o), { recursive: true }); fs.writeFileSync(o, "x"); }
`;
const FAKE_JAR = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2); const file = a[a.indexOf("--file") + 1];
if (a[0] === "--extract") { const j = JSON.parse(fs.readFileSync(file, "utf8")); for (const [k, v] of Object.entries(j)) { fs.mkdirSync(path.dirname(k) === "." ? "." : path.dirname(k), { recursive: true }); fs.writeFileSync(k, Buffer.from(v, "base64")); } process.exit(0); }
const out = {};
const add = (root, rel) => { const abs = path.join(root, rel); if (fs.statSync(abs).isDirectory()) { for (const n of fs.readdirSync(abs)) add(root, rel === "." ? n : rel + "/" + n); } else out[rel] = fs.readFileSync(abs).toString("base64"); };
for (let i = 0; i < a.length; i++) if (a[i] === "-C") { add(a[i + 1], a[i + 2]); i += 2; }
if (file) fs.writeFileSync(file, JSON.stringify(Object.fromEntries(Object.entries(out).sort((x, y) => (x[0] < y[0] ? -1 : 1)))));
`;
const YAML_STUB = `module.exports = {
  parse(t) { const o = {}; for (const l of String(t).split("\\n")) { const m = l.match(/^([\\w-]+):\\s*(.*)$/); if (m) o[m[1]] = m[2].replace(/^'(.*)'$/, "$1"); } return o; },
  stringify(o) { return Object.entries(o).map(([k, v]) => k + ": " + (typeof v === "string" && /^[\\d.]+$/.test(v) ? "'" + v + "'" : v)).join("\\n") + "\\n"; },
};
`;

type Snap = { t: number; status: string; cost: number; live: number | null; phase: string | null; wrote: number };
let proc: ChildProcess | null = null;
let dir = "";
let err = "";
const snaps: Snap[] = [];
let final: Record<string, unknown> = {};

describe("live token meter: real build service + replayed live-shaped stream", () => {
  before(async () => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "mb-liveusage-"));
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    fs.copyFileSync(path.join(ROOT, "scripts/cyrus/live-usage-fake-cli.js"), path.join(bin, "claude"));
    fs.chmodSync(path.join(bin, "claude"), 0o755);
    for (const [n, t] of [["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", "#!/usr/bin/env node\n"]]) fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\n");
    fs.writeFileSync(path.join(dir, "live-usage-fake.json"), JSON.stringify({ planMs: 1600, chunkMs: 10 }));
    const nodePath = path.join(dir, "node_modules");
    try { require.resolve("yaml", { paths: [SVC] }); } catch { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), YAML_STUB); }
    const port = 43000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: { PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"), MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_DEDUPE: "off", MB_GUARD: "off", NODE_PATH: nodePath } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc.stderr?.on("data", (d) => { err += d; });
    const url = (p: string) => `http://127.0.0.1:${port}${p}`;
    const H = { Authorization: `Bearer ${KEY}` };
    let up = false;
    for (let i = 0; i < 100 && !up; i++) { try { const h = await (await fetch(url("/health"))).json(); up = !!h.ok && h.features?.liveUsage === true; } catch { /* starting */ } if (!up) await new Promise((r) => setTimeout(r, 100)); }
    assert.ok(up, `service up with features.liveUsage: ${err.slice(-1500)}`);
    await fetch(url("/builds"), { method: "POST", headers: { ...H, "Content-Type": "application/json" }, body: JSON.stringify({ id: "live-usage-01", prompt: GOLEM, mcVersion: "1.21.11", tier: "yakko" }) });
    const t0 = Date.now();
    for (let i = 0; i < 2000; i++) {
      const r = (await (await fetch(url("/builds/live-usage-01"), { headers: H })).json()) as Record<string, unknown>;
      const live = r.live as { costUsd?: number; phase?: string } | undefined;
      snaps.push({ t: Date.now() - t0, status: String(r.status), cost: Number(r.costUsd) || 0, live: typeof live?.costUsd === "number" ? live.costUsd : null, phase: live?.phase ?? null, wrote: ((r.events as { message: string }[]) ?? []).filter((e) => /^Wrote /.test(e.message)).length });
      if (r.status === "succeeded" || r.status === "failed") { final = r; break; }
      await new Promise((res) => setTimeout(res, 60));
    }
  });
  after(() => { proc?.kill("SIGKILL"); if (dir) fs.rmSync(dir, { recursive: true, force: true }); });

  it("the build succeeds and bills the CLI's real total", () => {
    assert.equal(final.status, "succeeded", err.slice(-1500));
    assert.equal(final.costUsd, 0.6877);
  });
  it("the live cost moves DURING planning, before any file is written (the old meter sat at 5 here)", () => {
    const planning = snaps.filter((s) => s.wrote === 0 && s.live !== null && s.live > 0);
    assert.ok(planning.length >= 3, `planning snapshots with live usage: ${planning.length}`);
    assert.ok(new Set(planning.map((s) => s.live)).size >= 2, "it increases while the model is still thinking");
    assert.ok(planning.every((s) => s.cost === 0), "while the billed cost is still 0 (the call has not ended)");
    assert.ok(planning.some((s) => s.phase === "thinking"));
  });
  it("never goes down, and lands on the billed cost", () => {
    const vals = snaps.map((s) => s.live ?? 0);
    for (let i = 1; i < vals.length; i++) assert.ok(vals[i] + 1e-9 >= vals[i - 1], `step ${i}: ${vals[i - 1]} -> ${vals[i]}`);
    assert.equal((final.live as { costUsd: number }).costUsd, final.costUsd);
  });
  it("portal: the mapped usage drives the meter ('usage'), tokens rise with it, and settle as 'final'", () => {
    const cfg = parseTokenConfig({});
    const mid = snaps.find((s) => s.wrote === 0 && (s.live ?? 0) > 0.05)!;
    const result = { live: liveFromService({ costUsd: mid.live, phase: "thinking", turns: 1 }) };
    const e = liveEstimate({ id: "b", status: "planning", costUsd: 0, cyrus: null, result, createdAt: new Date(Date.now() - 30_000) }, 500, "yakko", cfg);
    assert.equal(e.kind, "usage");
    assert.equal(e.estimated, tokensForCost(mid.live!, "yakko", cfg));
    assert.ok(e.estimated > 5, `${e.estimated} > the old stuck 5`);
    const done = buildSpendFrom({ id: "b", status: "succeeded", costUsd: 0.6877, cyrus: null, result: { live: liveFromService(final.live) } }, { amount: 250, status: "settled", charged: 431, model: "yakko", settledAt: new Date() }, null, cfg);
    assert.equal(done.estimateKind, "final");
    assert.equal(done.overHeld, true, "spent more than held is reported, not hidden");
  });
  it("an older builder (no live usage): a labelled stage estimate that moves with the stage and the time", () => {
    const cfg = parseTokenConfig({});
    const at = (status: string, secs: number) => liveEstimate({ id: "b", status, costUsd: 0.00067, cyrus: null, result: {}, createdAt: new Date(Date.now() - secs * 1000) }, 600, "yakko", cfg);
    const p1 = at("planning", 5), p2 = at("planning", 60), c = at("coding", 120);
    assert.equal(p1.kind, "stage");
    assert.ok(p1.estimated >= 5 && p2.estimated > p1.estimated && c.estimated > p2.estimated, `${p1.estimated} < ${p2.estimated} < ${c.estimated}`);
    assert.ok(c.estimated <= 600, "never above the hold");
    assert.equal(liveFromService({ costUsd: "x" }), null);
    assert.equal(liveFromService({ costUsd: 1e9 })!.costUsd, 50);
  });
});

