// Cyrus live-test fixes (2026-10-11, the owner's first production test): honest asset lines (A), the hold and the Auto
// model (C), node categories and parts (D). Pure; the planner and the live meter have their own tests
// (test/cyrus-planner.test.ts, test/cyrus-live-usage-e2e.test.ts).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { assetTruth } from "../lib/cyrus/assets/truth";
import { realNotes } from "../lib/cyrus/real";
import type { ModBuildView } from "../lib/cyrus/builder/types";

const GOLEM = "Create me a 3 block tall golem creature, thows rocks at you and grunts and groans when attacking and when attacked";
const view = (over: Partial<ModBuildView> & { result?: Partial<NonNullable<ModBuildView["result"]>> | null } = {}): ModBuildView => ({
  id: "mbd5126c104c50af552a37", status: "succeeded", prompt: GOLEM, changeRequest: null, baseBuildId: null, rootBuildId: null, mcVersion: "1.21.11",
  pluginName: "RockGolem", version: "1.0.0", error: null, errorCode: null, attempts: 1, durationMs: 201_800, jarName: "RockGolem-1.0.0.jar", jarSize: 1000,
  createdAt: "2026-10-11T17:47:23Z", finishedAt: "2026-10-11T17:50:46Z", lastInstall: null, cyrus: { model: "yakko" },
  ...over,
  result: over.result === null ? null : ({ summary: { tagline: "A 3 block tall golem that throws rocks", text: "The golem grunts and groans when it attacks and when it is hit, with custom sounds.", howToUse: [], limitations: [], changes: "" }, commands: [], permissions: [], config: [], warnings: [], files: [], safety: null, events: [], repairs: 0, queuePosition: 0, errorDetail: null, ...(over.result ?? {}) } as unknown as ModBuildView["result"]),
});

describe("A: the summary never claims assets that were not built", () => {
  it("the live build (no assets section, summary says grunts + custom sounds): says vanilla sounds plainly", () => {
    const t = assetTruth(view());
    assert.equal(t.sounds, 0);
    assert.ok(t.lines.includes("No custom audio in this build: it uses vanilla sounds."));
    assert.match(realNotes(view()), /## Assets\n- No custom audio in this build: it uses vanilla sounds\./);
  });
  it("a build that really shipped sounds and a texture lists them and claims nothing else", () => {
    const t = assetTruth(view({ result: { assets: { status: "ready", namespace: "nx_ab12cd34", projectId: "cp", revisionId: null, textures: [{ name: "golem_rock", model: "nx_ab12cd34:golem_rock", specSha256: "a", pngSha256: "b", quality: "pass" }], sounds: [{ set: "golem", event: "grunt", key: "k", subtitle: "Golem grunts", role: "attack", category: "hostile", variants: 2, quality: "pass", specSha256: "c" }, { set: "golem", event: "groan", key: "k2", subtitle: "Golem groans", role: "hurt", category: "hostile", variants: 2, quality: "pass", specSha256: "d" }], dropped: [] } as never } }));
    assert.deepEqual(t.lines.slice(0, 2), ["Custom textures: 1 in this mod's resource pack.", "Custom sounds: 2 sound events."]);
    assert.ok(!t.lines.some((l) => /^No custom/.test(l)));
  });
  it("the plan's notices (e.g. Mob skin: coming soon) are repeated on the build", () => {
    const t = assetTruth(view({ cyrus: { model: "yakko", assets: { requested: [], allowed: [], notices: ["Mob skin: coming soon."] } } }));
    assert.ok(t.lines.includes("Mob skin: coming soon."));
  });
});

