describe("C: the hold is a realistic estimate, Auto picks the cheapest capable model", async () => {
  const { parseTokenConfig } = await import("../lib/cyrus/tokens/config");
  const { holdRange, tokensForCost, reserveRange } = await import("../lib/cyrus/tokens/economy");
  const { planEstimate, autoModel } = await import("../lib/cyrus/planner/estimate");
  const cfg = parseTokenConfig({});
  it("the live build: 250 held / 431 spent before; the planned hold now covers 431", () => {
    const e = planEstimate(GOLEM, "yakko", ["texture", "sound"]);
    assert.deepEqual(reserveRange("yakko", e.complexity, cfg), [100, 250], "the old hold");
    const h = holdRange("yakko", e.complexity, cfg, e.usd);
    assert.ok(h[1] >= tokensForCost(0.6884, "yakko", cfg), `hold ${h[1]} >= 431`);
    assert.ok(h[1] <= 1000, "and stays sane");
  });
  it("no estimate: the owner's reserve table, unchanged", () => assert.deepEqual(holdRange("saka", "standard", cfg), reserveRange("saka", "standard", cfg)));
  it("a higher token rate raises the hold with it (the owner's tokensPerUsd decision flows through)", () => {
    const e = planEstimate(GOLEM, "saka", ["texture", "sound"]);
    const lo = holdRange("saka", e.complexity, parseTokenConfig({ cyrus_tok_tokens_per_usd: "300" }), e.usd)[1];
    const hi = holdRange("saka", e.complexity, parseTokenConfig({ cyrus_tok_tokens_per_usd: "2000" }), e.usd)[1];
    assert.ok(hi > lo);
  });
  it("Auto: the golem builds on Saka, not Yakko (cost ~$0.12-0.26 vs $0.69 measured on Yakko)", () => {
    assert.equal(autoModel(GOLEM, ["texture", "sound"]), "saka");
    assert.ok(planEstimate(GOLEM, "saka", ["texture", "sound"]).usd[1] < 0.69);
  });
});
EOF
timeout 900 /opt/nxeon/scripts/devhost test test/cyrus-live-test-fixes.test.ts test/cyrus-tokens-economy.test.ts 2>&1 | grep -E "^# (pass|fail)|^\s*not ok" | head

