"use client";

// Live-test fix (E): the Minecraft version selector, in the Cyrus visual language (dark glass panel, readable text),
// replacing the native <select> whose white popup made 1.21.8 / 1.21.4 / 1.21.1 near invisible. Every registry version
// is listed with its loader and status: buildable ones can be picked (with a one-line capability note), previews are
// shown disabled with an honest reason, and "Match my server" appears when a connected server's version is known.
// Keyboard: Enter/Space/ArrowDown opens; ArrowUp/Down, Home/End move over enabled options; Enter/Space picks; Escape
// closes. ARIA listbox semantics; on phones the panel spans the screen width. "What this version supports" shows the
// capability catalogue for the highlighted version (from GET /api/cyrus/capabilities, the host's switches applied;
// before it loads, the version facts without switches).
import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { versionChoices, laneLabel, type VersionChoice } from "@/lib/cyrus/versions/choices";
import "./versionpicker.css";

let cache: Promise<VersionChoice[] | null> | null = null;
function loadChoices(game: string): Promise<VersionChoice[] | null> {
  cache ??= fetch(`/api/cyrus/capabilities?game=${encodeURIComponent(game)}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).then((j) => (j?.versions as VersionChoice[] | undefined) ?? null).catch(() => null);
  return cache;
}

const STATUS: Record<string, string> = { supported: "Supported", preview: "Preview", legacy: "Legacy", blocked: "Blocked" };
const AV: Record<string, string> = { available: "Yes", limited: "Limited", unavailable: "No" };

/** The last version this browser picked (per account in the studio store; this is the fallback for other pages). */
export function rememberVersion(v: string) { try { localStorage.setItem("cyrus-last-version", v); } catch { /* private mode */ } }
export function recallVersion(): string | null { try { return localStorage.getItem("cyrus-last-version"); } catch { return null; } }

export function VersionPicker({ value, onChange, disabled, serverVersion, game = "minecraft", compact = false, label = "Minecraft version" }: { value: string; onChange: (v: string) => void; disabled?: boolean; serverVersion?: string | null; game?: string; compact?: boolean; label?: string }) {
  const local = useMemo(() => versionChoices(game, {}), [game]);
  const [remote, setRemote] = useState<VersionChoice[] | null>(null);
  const [open, setOpen] = useState(false);
  const [hi, setHi] = useState<string | null>(null);
  const [showCaps, setShowCaps] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const id = useId();
  const choices = remote ?? local;
  const cur = choices.find((c) => c.id === value) ?? choices.find((c) => c.buildable);
  const server = serverVersion ? choices.find((c) => c.id === serverVersion) : null;
  const enabled = choices.filter((c) => c.buildable);

  useEffect(() => { if (open && !remote) void loadChoices(game).then((r) => r && setRemote(r)); }, [open, remote, game]);
  useEffect(() => {
    if (!open) return;
    const close = (e: PointerEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false); };
    window.addEventListener("pointerdown", close);
    return () => window.removeEventListener("pointerdown", close);
  }, [open]);
  useEffect(() => { if (open) { setHi(cur?.id ?? null); requestAnimationFrame(() => listRef.current?.focus()); } }, [open]); // eslint-disable-line react-hooks/exhaustive-deps

  const pick = (v: string) => { const c = choices.find((x) => x.id === v); if (!c?.buildable) return; onChange(v); rememberVersion(v); setOpen(false); };
  const move = (d: 1 | -1 | "home" | "end") => {
    if (!enabled.length) return;
    const i = enabled.findIndex((c) => c.id === hi);
    const next = d === "home" ? 0 : d === "end" ? enabled.length - 1 : Math.max(0, Math.min(enabled.length - 1, (i < 0 ? 0 : i + d)));
    setHi(enabled[next].id);
  };
  const onListKey = (e: KeyboardEvent) => {
    if (e.key === "ArrowDown") { e.preventDefault(); move(1); }
    else if (e.key === "ArrowUp") { e.preventDefault(); move(-1); }
    else if (e.key === "Home") { e.preventDefault(); move("home"); }
    else if (e.key === "End") { e.preventDefault(); move("end"); }
    else if (e.key === "Enter" || e.key === " ") { e.preventDefault(); if (hi) pick(hi); }
    else if (e.key === "Escape" || e.key === "Tab") { setOpen(false); }
  };
  const caps = choices.find((c) => c.id === (hi ?? cur?.id)) ?? cur;

  return (
    <div ref={ref} className={`cyvp${compact ? " cyvp-compact" : ""}`}>
      <button type="button" className="cyvp-btn" disabled={disabled} aria-haspopup="listbox" aria-expanded={open} aria-label={`${label}: ${cur?.loader ?? ""} ${cur?.id ?? value}`} onClick={() => setOpen((o) => !o)}
        onKeyDown={(e) => { if (!open && (e.key === "ArrowDown" || e.key === "ArrowUp")) { e.preventDefault(); setOpen(true); } }}>
        <span className="cyvp-loader">{cur?.loader ?? "Paper"}</span> <b>{cur?.id ?? value}</b>
        {server && server.id === value && <span className="cyvp-chip cyvp-chip-ok">your server</span>}
        <span aria-hidden className="cyvp-caret">▾</span>
      </button>
      {open && (
        <div className="cyvp-panel" role="presentation">
          {server && (
            <button type="button" className="cyvp-match" disabled={!server.buildable} onClick={() => pick(server.id)}>
              Match my server <span className="cyvp-dim">({server.loader} {server.id}{server.buildable ? "" : `: ${server.reason}`})</span>
            </button>
          )}
          <div ref={listRef} role="listbox" tabIndex={0} aria-label={label} aria-activedescendant={hi ? `${id}-${hi}` : undefined} className="cyvp-list" onKeyDown={onListKey}>
            {choices.map((c) => (
              <div key={c.id} id={`${id}-${c.id}`} role="option" aria-selected={c.id === value} aria-disabled={!c.buildable || undefined}
                className={`cyvp-opt${c.id === hi ? " hi" : ""}${c.buildable ? "" : " off"}`}
                onPointerEnter={() => c.buildable && setHi(c.id)} onClick={() => pick(c.id)}>
                <span className="cyvp-row">
                  <span className="cyvp-loader">{c.loader}</span> <b>{c.id}</b>
                  <span className={`cyvp-chip cyvp-chip-${c.status}`}>{STATUS[c.status] ?? c.status}</span>
                  {c.id === value && <span className="cyvp-check" aria-hidden>✓</span>}
                </span>
                <span className="cyvp-note">{c.buildable ? c.note : c.reason}</span>
              </div>
            ))}
          </div>
          {caps && (
            <div className="cyvp-caps">
              <button type="button" className="cyvp-capsbtn" aria-expanded={showCaps} onClick={() => setShowCaps((s) => !s)}>What {caps.loader} {caps.id} supports {showCaps ? "▴" : "▾"}</button>
              {showCaps && <CapabilityList lanes={caps.lanes} />}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/** "What this version supports": one row per lane (Yes / Limited / No) with the reason. Also used on the project page. */
export function CapabilityList({ lanes }: { lanes: VersionChoice["lanes"] }) {
  return (
    <ul className="cyvp-caplist">
      {lanes.map((l) => (
        <li key={l.lane} data-av={l.availability}>
          <span className="cyvp-capname">{laneLabel(l.lane)}</span>
          <span className={`cyvp-av cyvp-av-${l.availability}`}>{AV[l.availability]}</span>
          {l.availability !== "available" && <span className="cyvp-capwhy">{l.reason}{l.substitute ? `. Instead: ${l.substitute}` : ""}</span>}
        </li>
      ))}
    </ul>
  );
}

