cd /tank/dev-worktrees/cyrus-fix1 && cat >> test/cyrus-live-test-fixes.test.ts <<'EOF'

describe("E: the version selector lists every registry version honestly", async () => {
  const { versionChoices } = await import("../lib/cyrus/versions/choices");
  const { VERSIONS } = await import("../lib/cyrus/versions/registry");
  const fs = await import("node:fs");
  const c = versionChoices("minecraft", {});
  it("every registry version, buildable first (newest first), previews disabled with a reason", () => {
    assert.deepEqual([...c.map((x) => x.id)].sort(), VERSIONS.map((v) => v.id).sort());
    assert.deepEqual(c.filter((x) => x.buildable).map((x) => x.id), ["1.21.11", "1.21.8", "1.21.4", "1.21.1"]);
    for (const p of c.filter((x) => !x.buildable)) { assert.equal(p.reason, "Preview: not buildable yet", p.id); assert.equal(p.status, "preview"); }
    assert.ok(c.every((x) => x.loader === "Paper" && x.note.length > 10));
  });
  it("1.21.1's note says what it cannot do (legacy path when switched on, otherwise no textures)", () => {
    assert.match(c.find((x) => x.id === "1.21.1")!.note, /No custom textures on 1\.21\.1|legacy path/);
  });
  it("each version carries the capability panel (every lane)", () => assert.ok(c.every((x) => x.lanes.length === 15)));
  it("no native <select> for the version in the Forge dock or the new-mod flow any more", () => {
    for (const f of ["components/cyrus/prompt/PromptDock.tsx", "components/cyrus/app/NewModFlow.tsx"]) {
      const src = fs.readFileSync(f, "utf8");
      assert.ok(src.includes("<VersionPicker"), f);
      assert.ok(!/<select[^>]*(mcVersion|setVersion)/.test(src), `${f}: no native version select`);
    }
  });
});
EOF
timeout 900 /opt/nxeon/scripts/devhost test test/cyrus-live-test-fixes.test.ts 2>&1 | grep -E "^# (pass|fail)|^\s*not ok|error:" | head

