// Cyrus v6: broad-request prompt ROUTING (PURE, client-safe, zero API calls).
//
// The dock no longer needs a hovered game or mod. Anything typed anywhere ("make me a mod for
// Minecraft where creepers drop diamonds", "work on my frost axe mod and fix the cooldown",
// "add a shop command to my Rust plugin", "what mods do I have for Valheim", "update the boss
// mod for the new version") becomes a RouteDecision: what to do, on which game, in which
// universal category, on which of the user's projects.
//
// Cost-aware by design: a deterministic fast path decides almost everything instantly in the
// browser (game aliases + typo-tolerant matching, "my <name> mod" fuzzy-matched against the
// user's own projects, intent verbs, category keywords). When the input is genuinely ambiguous
// it does NOT call a model: it returns `clarify` with one-tap options ("Frost Axe v2 or Frost
// Axe?", "Which game is this for?"). The current selection (and hover) always wins as context.
// Unit-tested in test/cyrus-route.test.ts.

import { CYRUS_CATEGORY, bestCategory, categoriesForGame, toCategory, type CyrusCategoryId } from "./categories";

export type RouteIntent = "create" | "refine" | "fix" | "explain" | "install" | "browse" | "unknown";

export type RouteDecision = {
  intent: RouteIntent;
  /** The game the request lands on (null = not known yet: see clarify). */
  gameId: string | null;
  /** Universal category (create: where the new mod goes; others: the project's). */
  categoryId: CyrusCategoryId | null;
  /** The studio mod id of the target project (refine/fix/explain/install). */
  projectId?: string;
  /** 0..1. Below ~0.5 the dock shows the decision as a suggestion rather than acting on it. */
  confidence: number;
  /** One line in customer voice for the dock chip: "Creating a new Minecraft mod in Weapons". */
  reason: string;
  /** Present when one tap from the user is needed. Each option is a complete decision. */
  clarify?: { question: string; options: RouteOption[] };
  /** A game the user named that Cyrus doesn't build for. */
  unsupported?: string;
  /** What decided it (for tests and the dock's wording). */
  via: "selection" | "prompt" | "project" | "default";
};

export type RouteOption = { label: string; hint?: string; decision: RouteDecision };

export type RouteGame = { id: string; name: string; short?: string; aliases: string[]; real?: boolean };

export type RouteProject = {
  /** Studio mod id ("nx-<rootId>" for real projects, the local id for template mods). */
  id: string;
  gameId: string;
  categoryId: CyrusCategoryId | string;
  title: string;
  /** Other names it goes by (the plugin name, an old title). */
  aliases?: string[];
  /** ms epoch, newest wins ties. */
  updatedAt?: number;
};

export type RouteSelection = { level: "core" | "game" | "category" | "mod"; gameId?: string; category?: string; modId?: string };

export type RouteContext = {
  selection?: RouteSelection;
  /** What the pointer is over right now (counts like a selection when nothing is selected). */
  hover?: { gameId?: string; modId?: string };
};

export type RouteWorld = { games: RouteGame[]; projects: RouteProject[] };

/* ───────────── Text helpers ───────────── */
const VERSION_TOKEN = /^v?\d+$/;
const sig = (toks: string[]) => toks.filter((t) => !NAME_STOP.has(t) && !VERSION_TOKEN.test(t));
const titleTokens = (s: string) => sig(tokens(s.replace(/([a-z0-9])([A-Z])/g, "$1 $2")));

/** "my frost axe mod", "the boss plugin", "my Rust plugin": the words between the determiner and "mod". */
export function namedReference(text: string): { words: string[]; generic: boolean } | null {
  const t = normalizeText(text);
  const m = t.match(/\b(my|our|the|this|that)\s+((?:[a-z0-9'-]+\s+){0,6}?)(mod|mods|plugin|plugins|addon|script|datapack|pack|project)\b/);
  if (!m) return null;
  const words = sig(m[2].trim().split(/\s+/).filter(Boolean));
  return { words, generic: m[1] === "my" || m[1] === "our" };
}

function tokenOverlap(phrase: string[], title: string[]): number {
  if (!phrase.length || !title.length) return 0;
  // "coinshop" vs "Coin Shop"
  if (fuzzyEq(phrase.join(""), title.join(""))) return 1;
  let hit = 0;
  for (const p of phrase) if (title.some((t) => fuzzyEq(p, t) || (p.length >= 4 && t.startsWith(p)))) hit++;
  // every phrase word should be in the title; extra title words cost a little
  return (hit / phrase.length) * (0.75 + 0.25 * Math.min(1, phrase.length / title.length));
}

type ProjectHit = { p: RouteProject; score: number };

function matchProjects(words: string[], projects: RouteProject[]): ProjectHit[] {
  return projects
    .map((p) => ({ p, score: Math.max(tokenOverlap(words, titleTokens(p.title)), ...(p.aliases ?? []).map((a) => tokenOverlap(words, titleTokens(a)))) }))
    .filter((h) => h.score >= 0.5)
    .sort((a, b) => b.score - a.score || (b.p.updatedAt ?? 0) - (a.p.updatedAt ?? 0));
}

/**
 * A project named in the text without "my ... mod" around it ("add /baltop to coin shop", "the
 * quest board is broken"): all of a short title's words, or at least two of a longer one's.
 */
function implicitProjects(text: string, projects: RouteProject[]): ProjectHit[] {
  const toks = sig(tokens(text));
  const joined = toks.join("");
  return projects
    .map((p) => {
      const tt = titleTokens(p.title);
      if (!tt.length || !tt.some((t) => t.length >= 4)) return { p, score: 0 };
      if (tt.length > 1 && joined.includes(tt.join(""))) return { p, score: 0.95 };
      const n = tt.filter((t) => toks.some((x) => fuzzyEq(x, t))).length;
      const all = n === tt.length;
      const most = tt.length >= 3 && n >= 2 && n / tt.length >= 0.66;
      return { p, score: all ? 0.9 + Math.min(0.09, tt.length * 0.03) : most ? 0.7 : 0 };
    })
    .filter((h) => h.score > 0)
    .sort((a, b) => b.score - a.score || (b.p.updatedAt ?? 0) - (a.p.updatedAt ?? 0));
}

/* ───────────── The router ───────────── */

const gameName = (games: RouteGame[], id: string | null) => games.find((g) => g.id === id)?.name ?? "this game";
const catLabel = (c: CyrusCategoryId | null) => (c ? CYRUS_CATEGORY[c].label : null);

function describe(d: Omit<RouteDecision, "reason">, world: RouteWorld, title?: string): string {
  const g = gameName(world.games, d.gameId);
  switch (d.intent) {
    case "create": return d.gameId ? `Creating a new ${g} mod${d.categoryId ? ` in ${catLabel(d.categoryId)}` : ""}` : "Creating a new mod";
    case "refine": return `Refining ${title ?? "this mod"}`;
    case "fix": return `Fixing ${title ?? "this mod"}`;
    case "explain": return `Explaining ${title ?? "this mod"}`;
    case "install": return `Installing ${title ?? "this mod"} on a server`;
    case "browse": return d.gameId ? `Showing your ${g} mods` : "Showing all your mods";
    default: return "Tell Cyrus which game or mod this is for";
  }
}

function decide(d: Omit<RouteDecision, "reason"> & { reason?: string }, world: RouteWorld, title?: string): RouteDecision {
  return { ...d, reason: d.reason ?? describe(d, world, title) };
}

/** A create decision on `gameId`, category from the text (falling back to `fallbackCat`). */
function createOn(gameId: string, text: string, world: RouteWorld, fallbackCat: string | undefined, confidence: number, via: RouteDecision["via"]): RouteDecision {
  const allowed = categoriesForGame(gameId);
  const cat = bestCategory(text, allowed)?.id ?? (fallbackCat ? toCategory(fallbackCat) : null);
  return decide({ intent: "create", gameId, categoryId: cat, confidence, via }, world);
}

function projectDecision(intent: RouteIntent, p: RouteProject, world: RouteWorld, confidence: number, via: RouteDecision["via"], text: string): RouteDecision {
  const versionBump = intent === "refine" && RE.version.test(normalizeText(text)) && /\bupdate|upgrade|port\b/.test(normalizeText(text));
  return decide({
    intent, gameId: p.gameId, categoryId: toCategory(p.categoryId), projectId: p.id, confidence, via,
    ...(versionBump ? { reason: `Updating ${p.title} for the new version` } : {}),
  }, world, p.title);
}

function pickIntent(t: string, hasTarget: boolean, modSelected = false): RouteIntent {
  // With a mod open, only a short navigation-style line can mean "browse"; a long description is always about the open mod.
  if (RE.browse.test(t) && !(modSelected && t.split(" ").length > 8)) return "browse";
  if (RE.install.test(t)) return "install";
  if (RE.fix.test(t)) return "fix";
  // "how do I…/what does…" is a question; "what if it also…" is a change
  if (RE.explain.test(t) && !/\b(make|add|create|build|forge)\b/.test(t)) return "explain";
  if (hasTarget && RE.refine.test(t)) return "refine";
  if (RE.create.test(t)) return "create";
  if (hasTarget) return "refine";
  return "create";
}

/**
 * Decide where a free-text request goes. Pure and instant.
 * `world.projects` should be the user's own mods (real projects + local template mods), not idea seeds.
 */
export function routeRequest(text: string, ctx: RouteContext, world: RouteWorld): RouteDecision {
  const t = normalizeText(text);
  const sel = ctx.selection ?? { level: "core" };
  const hover = sel.level === "core" ? ctx.hover : undefined;
  const ctxGame = sel.gameId ?? hover?.gameId;
  const ctxModId = sel.level === "mod" ? sel.modId : hover?.modId;
  const ctxMod = ctxModId ? world.projects.find((p) => p.id === ctxModId) : undefined;
  const supported = world.games;

  if (!t) {
    if (ctxMod) return projectDecision("refine", ctxMod, world, 0.3, "selection", "");
    return decide({ intent: "unknown", gameId: ctxGame ?? null, categoryId: sel.category ? toCategory(sel.category) : null, confidence: 0, via: "default", reason: "Describe a mod, or ask about one of yours" }, world);
  }

  const gameHits = detectGames(text, supported);
  const strongGames = gameHits.filter((h) => h.strong);
  const namedGame = strongGames[0]?.id ?? null;
  const unsupported = strongGames.length ? null : detectUnsupported(text);

  // ── which project does the text point at? ──
  const ref = namedReference(text);
  const refWords = ref ? ref.words.filter((w) => !gameHits.some((h) => h.word.split(" ").includes(w)) && !supported.some((g) => fuzzyEq(w, normalizeText(g.id)) || fuzzyEq(w, normalizeText(g.name)))) : [];
  const scope = (list: RouteProject[]) => (namedGame ? list.filter((p) => p.gameId === namedGame) : list);
  const strictNew = RE.newMod.test(t);
  const createish = RE.createish.test(t);
  let hits: ProjectHit[] = [];
  let generic = false;
  let namedMiss = false;
  if (!strictNew && ref && refWords.length) {
    hits = matchProjects(refWords, scope(world.projects));
    namedMiss = !hits.length;
  } else if (!strictNew && ref?.generic) generic = true; // "my mod", "my Rust plugin"
  // an implicit title match only counts with an action on it ("fix", "add", "explain", "install"):
  // a plain description that happens to share a title's words is a new mod
  const acts = RE.fix.test(t) || RE.refine.test(t) || RE.install.test(t) || RE.explain.test(t);
  if (!hits.length && !generic && !namedMiss && !strictNew && !createish && acts) hits = implicitProjects(text, scope(world.projects));
  const useCtxMod = !!ctxMod && !strictNew && !(createish && /\b(a|an|another)\s+(\w+\s+){0,2}(mod|plugin|addon)\b/.test(t));
  const hasTarget = !strictNew && (hits.length > 0 || generic || namedMiss || useCtxMod);
  const intent = pickIntent(t, hasTarget, useCtxMod);

  // ── unsupported game named ──
  if (unsupported && intent !== "browse") {
    const offered = supported.filter((g) => g.real).length ? supported.filter((g) => g.real) : supported;
    const options: RouteOption[] = offered.map((g) => ({ label: g.name, hint: g.real ? "Builds for real" : "Coming soon", decision: createOn(g.id, text, world, undefined, 0.8, "prompt") }));
    return decide({
      intent: "unknown", gameId: null, categoryId: bestCategory(text)?.id ?? null, confidence: 0.9, via: "prompt", unsupported,
      reason: `Cyrus doesn't build ${unsupported} mods yet`,
      clarify: { question: `Cyrus builds for ${offered.map((g) => g.name).join(", ").replace(/, ([^,]*)$/, " and $1")} today. Pick one to continue:`, options },
    }, world);
  }

  // ── several games named: ask which one first ──
  if (strongGames.length > 1 && !hits.length && intent !== "browse") {
    const options = strongGames.slice(0, 4).map((h) => ({ label: gameName(supported, h.id), decision: createOn(h.id, text, world, undefined, 0.8, "prompt") }));
    return decide({ intent: "create", gameId: null, categoryId: bestCategory(text)?.id ?? null, confidence: 0.3, via: "prompt", reason: "This mentions more than one game", clarify: { question: "Which game is this mod for? (Each game gets its own mod.)", options } }, world);
  }

  // ── browse ──
  if (intent === "browse") {
    const gameId = namedGame ?? (gameHits[0]?.id ?? null) ?? null;
    return decide({ intent, gameId: gameId ?? (sel.level !== "core" ? ctxGame ?? null : null), categoryId: bestCategory(text)?.id ?? null, confidence: gameId ? 0.9 : 0.7, via: gameId ? "prompt" : "default" }, world);
  }

  // ── an explicit project reference ──
  if (hits.length) {
    const top = hits[0];
    const close = hits.filter((h) => h.score >= top.score - 0.08);
    if (close.length > 1) {
      const options = close.slice(0, 3).map((h) => ({ label: h.p.title, hint: gameName(supported, h.p.gameId), decision: projectDecision(intent === "create" ? "refine" : intent, h.p, world, 0.9, "project", text) }));
      return decide({ intent: intent === "create" ? "refine" : intent, gameId: top.p.gameId, categoryId: toCategory(top.p.categoryId), confidence: 0.4, via: "project", reason: `Which ${refWords.join(" ") || "mod"}?`, clarify: { question: `${options.map((o) => o.label).join(" or ")}?`, options } }, world);
    }
    return projectDecision(intent === "create" ? "refine" : intent, top.p, world, Math.min(0.97, 0.55 + top.score * 0.4), "project", text);
  }

  // ── "my frost axe mod" that matches nothing ──
  if (namedMiss && intent !== "create") {
    const name = refWords.join(" ");
    const g = namedGame ?? ctxGame ?? null;
    const recent = scope(world.projects).sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0)).slice(0, 2);
    const options: RouteOption[] = recent.map((p) => ({ label: p.title, hint: gameName(supported, p.gameId), decision: projectDecision(intent, p, world, 0.9, "project", text) }));
    if (g) options.push({ label: `New ${gameName(supported, g)} mod`, hint: `called ${name}`, decision: createOn(g, text, world, undefined, 0.8, "prompt") });
    return decide({ intent, gameId: g, categoryId: null, confidence: 0.25, via: "project", reason: `No mod called "${name}" yet`, clarify: options.length ? { question: `Cyrus couldn't find "${name}" among your mods. Did you mean:`, options } : undefined }, world);
  }

  // ── "my mod" / "my Rust plugin" with no name ──
  if (generic) {
    const mine = scope(world.projects).sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0));
    const inCtx = useCtxMod && ctxMod && (!namedGame || ctxMod.gameId === namedGame) ? ctxMod : undefined;
    if (inCtx) return projectDecision(intent === "create" ? "refine" : intent, inCtx, world, 0.85, "selection", text);
