function check(text: string, ctx: RouteContext, want: Want, w: RouteWorld = world) {
  const d = routeRequest(text, ctx, w);
  const label = `${JSON.stringify(text)} -> ${JSON.stringify({ intent: d.intent, gameId: d.gameId, categoryId: d.categoryId, projectId: d.projectId, clarify: d.clarify?.options.map((o) => o.label), reason: d.reason, conf: d.confidence })}`;
  for (const k of ["intent", "gameId", "categoryId", "projectId", "unsupported", "via"] as const) if (k in want) assert.equal(d[k], want[k], `${k}: ${label}`);
  if (want.clarify !== undefined) assert.equal(!!d.clarify, want.clarify, `clarify: ${label}`);
  if (want.options) assert.deepEqual(d.clarify?.options.map((o) => o.label).slice(0, want.options.length), want.options, `options: ${label}`);
  if (want.minConf !== undefined) assert.ok(d.confidence >= want.minConf, `confidence >= ${want.minConf}: ${label}`);
  if (want.maxConf !== undefined) assert.ok(d.confidence <= want.maxConf, `confidence <= ${want.maxConf}: ${label}`);
  if (want.reason) assert.match(d.reason, want.reason, label);
  // every clarify option is itself a complete, actionable decision
  for (const o of d.clarify?.options ?? []) assert.ok(!o.decision.clarify, `option ${o.label} must not need another question: ${label}`);
  return d;
}

