content.content:
"use client";

// Cyrus v6: where the request in the dock will go, shown while typing ("Creating a new
// Minecraft mod in Weapons", "Refining Frost Axe"), and the one-tap clarification when the
// router needs it ("Frost Axe v2 or Frost Axe?", "Which game is this for?").

import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { GameEmblem } from "@/components/cyrus/icons/GameEmblems";
import { SparkleIcon } from "@/components/cyrus/icons/ui";
import { CYRUS_CATEGORY } from "@/lib/cyrus/categories";
import type { RouteDecision, RouteOption } from "@/lib/cyrus/route";
import { getGame } from "@/lib/cyrus/store";

const INTENT_VERB: Record<RouteDecision["intent"], string> = { create: "New mod", refine: "Refine", fix: "Fix", explain: "Explain", install: "Install", browse: "Show", unknown: "" };

export function RouteChip({ d, onPick, emphasis }: { d: RouteDecision; onPick: (o: RouteOption) => void; emphasis?: boolean }) {
  const game = getGame(d.gameId ?? undefined);
  const cat = d.categoryId ? CYRUS_CATEGORY[d.categoryId] : null;
  const rgb = cat?.rgb ?? game?.rgb ?? "167 139 250";
  const warn = !!d.unsupported || d.intent === "unknown";
  return (
    <div className="min-w-0 flex-1" data-testid="cyrus-route-chip" data-intent={d.intent} data-game={d.gameId ?? ""} data-category={d.categoryId ?? ""} data-project={d.projectId ?? ""}>
      <span
        className="tint inline-flex max-w-full items-center gap-1.5 truncate rounded-full py-1 pl-1.5 pr-2.5 text-[11px] font-medium text-cy-ink-2"
        style={{ ["--c" as string]: rgb, background: warn ? "rgb(251 191 36 / 0.13)" : `rgb(${rgb} / 0.12)` }}
        aria-live="polite"
      >
        <span className="text-[13px]" style={{ color: warn ? "rgb(251 191 36)" : "var(--cc)" }}>
          {cat ? <CategoryIcon k={cat.id} /> : game ? <GameEmblem emblem={game.emblem} logo={game.logo} logoTone={game.logoTone} /> : <SparkleIcon />}
        </span>
        {!warn && INTENT_VERB[d.intent] && d.confidence >= 0.5 && <span className="text-cy-muted">{INTENT_VERB[d.intent]} ·</span>}
        <span className="truncate">{d.reason}</span>
      </span>
      {d.clarify && (
        <div className={`mt-2 rounded-2xl border px-2.5 py-2 transition ${emphasis ? "border-cy-accent/60 bg-[rgb(var(--glow)/0.1)]" : "border-cy-line bg-[rgb(var(--glow)/0.04)]"}`} role="group" aria-label={d.clarify.question}>
          <p className="mb-1.5 px-0.5 text-[11.5px] text-cy-ink-2">{d.clarify.question}</p>
          <div className="flex flex-wrap gap-1.5">
            {d.clarify.options.map((o) => {
              const g = getGame(o.decision.gameId ?? undefined);
              const c = o.decision.categoryId ? CYRUS_CATEGORY[o.decision.categoryId] : null;
              const orgb = g?.rgb ?? c?.rgb ?? "167 139 250";
              return (
                <button
                  key={`${o.label}:${o.decision.projectId ?? o.decision.gameId}`}
                  type="button"
                  onClick={() => onPick(o)}
                  className="tint inline-flex max-w-full items-center gap-1.5 rounded-full border py-1 pl-1.5 pr-2.5 text-[12px] font-medium text-cy-ink transition hover:brightness-110"
                  style={{ ["--c" as string]: orgb, borderColor: `rgb(${orgb} / 0.55)`, background: `rgb(${orgb} / 0.1)` }}
                >
                  <span className="text-[13px]" style={{ color: "var(--cc)" }}>
                    {g ? <GameEmblem emblem={g.emblem} logo={g.logo} logoTone={g.logoTone} /> : c ? <CategoryIcon k={c.id} /> : <SparkleIcon />}
                  </span>
                  <span className="truncate">{o.label}</span>
                  {o.hint && <span className="hidden text-[10.5px] font-normal text-cy-muted sm:inline">{o.hint}</span>}
                </button>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

