cd /tank/dev-worktrees/cyrus-fix1 && cat > test/cyrus-route-context.test.ts <<'EOF'
// Cyrus live-test fix (2026-10-11): a change request typed with "Chunk Mirror" open was sent to "Mob Duplication"
// because the request contained "mob" and "duplication" (implicit title-word match outranked the open mod).
// CONTEXT WINS: with a mod selected, only an explicit name moves a change; with nothing selected, a title-word guess
// is never acted on silently. Pure (no DB, no network).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { GAMES } from "../lib/cyrus/data";
import { needsClarify, routeRequest, type RouteContext, type RouteProject, type RouteWorld } from "../lib/cyrus/route";

const games = GAMES.map((g) => ({ id: g.id, name: g.name, short: g.short, aliases: g.aliases, real: g.real }));
const CM: RouteProject = { id: "nx-mb010552be90ff314b9b0a", gameId: "minecraft", categoryId: "gameplay", title: "Chunk Mirror", aliases: ["ChunkMirror"], updatedAt: 1900 };
const MD: RouteProject = { id: "nx-mb5bb3cee727ae2d8922f3", gameId: "minecraft", categoryId: "gameplay", title: "Mob Duplication", aliases: ["MobDuplication"], updatedAt: 1800 };
const CS: RouteProject = { id: "nx-shop", gameId: "minecraft", categoryId: "economy", title: "Coin Shop", aliases: ["CoinShop"], updatedAt: 100 };
const world: RouteWorld = { games, projects: [CM, MD, CS] };
const onMod = (p: RouteProject): RouteContext => ({ selection: { level: "mod", gameId: p.gameId, category: String(p.categoryId), modId: p.id } });
const core: RouteContext = { selection: { level: "core" } };

// The owner's change request (as recorded), and the follow-up in the same session (the second message is the same
// request continued: the recorded text was cut at "dont drop...").
const MSG1 = "mob spawners that spawn mobs need to mirror the mobs as well. Also to avoid duplication cheating, the mirrored blocks that I place dont drop";
const MSG2 = "also the mirrored mobs should not drop loot or xp, so nobody can farm duplicated mobs";

describe("context wins: a selected mod is the target of a change", () => {
  it("the live case: Chunk Mirror selected + 'mob ... duplication' text -> Chunk Mirror, no question", () => {
    const d = routeRequest(MSG1, onMod(CM), world);
    assert.equal(d.projectId, CM.id);
    assert.equal(d.intent, "refine");
    assert.equal(d.via, "selection");
    assert.equal(needsClarify(d), false);
  });
  it("replay of both messages with Chunk Mirror open: both land on Chunk Mirror", () => {
    for (const m of [MSG1, MSG2]) assert.equal(routeRequest(m, onMod(CM), world).projectId, CM.id, m);
  });
  it("a selected mod + another mod NAMED explicitly -> the named mod", () => {
    assert.equal(routeRequest("in Mob Duplication, add a cooldown to duplicating", onMod(CM), world).projectId, MD.id);
    assert.equal(routeRequest("add a cooldown to my mob duplication mod", onMod(CM), world).projectId, MD.id);
  });
  it("title words alone never move it (mob, chunk, block, item are common words)", () => {
    assert.equal(routeRequest("add a chunk limit and fix the mob duplication bug", onMod(CS), world).projectId, CS.id);
  });
});

describe("no selection: a title-word guess asks first, with the guess first", () => {
  it("unique guess -> 'Apply this change to Mob Duplication, or create a new mod?'", () => {
    const d = routeRequest("fix the duplication bug in mob duplication when mobs die", core, world);
    assert.ok(needsClarify(d));
    assert.equal(d.clarify!.options[0].label, "Mob Duplication");
    assert.equal(d.clarify!.options[0].decision.projectId, MD.id);
    assert.match(d.clarify!.options.at(-1)!.label, /^New Minecraft mod$/);
    assert.match(d.clarify!.question, /^Apply this change to Mob Duplication, or create a new mod\?$/);
  });
  it("ambiguous (two titles fully present) -> both offered plus a new mod", () => {
    const d = routeRequest("update chunk mirror and mob duplication so they share the config", core, world);
    assert.ok(needsClarify(d));
    assert.deepEqual(d.clarify!.options.map((o) => o.label).sort(), ["Chunk Mirror", "Mob Duplication", "New Minecraft mod"].sort());
  });
  it("the live text with nothing selected: no silent build on Mob Duplication", () => {
    const d = routeRequest(MSG1, core, world);
    assert.ok(!(d.projectId === MD.id && !needsClarify(d)), "never acts on the guess silently");
  });
  it("a title made only of common words is never guessed", () => {
    const w: RouteWorld = { games, projects: [{ id: "nx-mb", gameId: "minecraft", categoryId: "creatures", title: "Mob Spawner", updatedAt: 1 }] };
    assert.equal(routeRequest("add more mob spawner types", core, w).projectId, undefined);
  });
  it("an explicit name with nothing selected still acts directly", () => {
    const d = routeRequest("add /baltop to my coin shop mod", core, world);
    assert.equal(d.projectId, CS.id);
    assert.equal(needsClarify(d), false);
  });
});

describe("the Forge sends the selected mod and shows the target", () => {
  it("forge() builds its context from the store selection; runDecision re-selects only the router's target", () => {
    const forge = readFileSync("lib/cyrus/forge.ts", "utf8");
    assert.match(forge, /const sel = state\.selection;/);
    assert.match(forge, /modId: refineMod\.id/);
    assert.match(forge, /the build lands on the mod the plan screen showed as its target/);
  });
  it("the plan screen and the prompt bar show the target mod and the version it creates", () => {
    assert.match(readFileSync("components/cyrus/prompt/PlanSheet.tsx", "utf8"), /Change \{draft\.target\.name\} → v\{draft\.target\.version\}/);
    assert.match(readFileSync("components/cyrus/prompt/RouteChip.tsx", "utf8"), /Target: <b className="text-cy-ink">\{m\.name\}<\/b> → v\{n\}/);
  });
});
EOF
timeout 900 /opt/nxeon/scripts/devhost test test/cyrus-route-context.test.ts test/cyrus-route.test.ts 2>&1 | grep -E "^# (pass|fail)|^\s*not ok|error:|expected|actual" | head -30

