p='lib/cyrus/route.ts'; s=open(p).read()
a=s.index('function explicitlyNamed(text: string, projects: RouteProject[]): ProjectHit[] {')
b=s.index('/* ───────────── The router ───────────── */')
new='''function explicitlyNamed(text: string, projects: RouteProject[]): ProjectHit[] {
  const raw = ` ${text.toLowerCase().replace(/[‘’`"“”]/g, " ")} `;
  const esc = (w: string) => w.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\\\$&");
  return projects
    .map((p) => {
      const names = [p.title, ...(p.aliases ?? [])].map((n) => titleTokens(n)).filter((tt) => tt.length && tt.some((w) => !COMMON_TITLE_WORDS.has(w)));
      const hit = names.some((tt) => {
        const ph = tt.map(esc).join("[\\\\s_-]*");
        // "in Mob Duplication, ..." / "to Coin Shop:" / "for Chunk Mirror." (the title ends the phrase) or "Coin Shop mod"
        return new RegExp(`\\\\b(in|on|to|into|for)\\\\s+(the\\\\s+)?${ph}\\\\s*([,:;.!?]|$|\\\\s+(mod|plugin|addon)\\\\b)`).test(raw.trimEnd()) || new RegExp(`\\\\b${ph}\\\\s+(mod|plugin|addon)\\\\b`).test(raw)
          // the plugin name as written ("MobDuplication")
          || (tt.length > 1 && new RegExp(`(^|[^a-z0-9])${tt.join("")}([^a-z0-9]|$)`).test(raw));
      });
      return { p, score: hit ? 1 : 0 };
    })
    .filter((h) => h.score > 0)
    .sort((a, b) => (b.p.updatedAt ?? 0) - (a.p.updatedAt ?? 0));
}

'''
